@pytest.mark.parametrize(
    ("reason", "said"),
    [
        ('"the bars are proportions, each with its Wilson interval"', []),
        ('""', [_MEANS, _ERRORS]),
        ("5", [_MEANS, _ERRORS]),
        ("\n  - value: barplot\n    why: a list is no reason", [_MEANS, _ERRORS]),
    ],
)
def test_a_reason_beside_the_figure_stands_its_bars_down(
    tmp_path: Path, reason: str, said: list[str]
) -> None:
    """`allow_bars` in the figure's guard file, with a reason, stands down both findings of
    the script beside it. An empty one, or one that is no sentence, stands down nothing."""
    from manuscript_guard.classify import Classifier
    from manuscript_guard.gates.figure_source import check_figure_source

    path = tmp_path / "bars.R"
    path.write_text("library(ggplot2)\np <- ggplot(d, aes(arm, y)) + stat_summary(geom = 'bar')\n"
                    "q <- ggplot(s, aes(arm, p)) + geom_col() + geom_errorbar()\n",
                    encoding="utf-8")  # fmt: skip
    (tmp_path / "bars.guard.yaml").write_text(f"allow_bars: {reason}\n", encoding="utf-8")
    found = [code for code, _severity, _call in _bars_said(
        check_figure_source(path, Classifier.load()))]  # fmt: skip
    assert found == said
    if not said:
        return
    hint = next(f.hint for f in check_figure_source(path, Classifier.load()).findings
                if f.code == _MEANS)  # fmt: skip
    assert "bars.guard.yaml under allow_bars" in hint, hint


def test_a_supplementary_figure_s_bars_are_said_too(project: Path) -> None:
    """A figure the supplement places is read as the paper's are: its script, in figures/,
    draws bars from plotnine with error bars and no points."""
    script = project / "figures" / "S1_doses.py"
    script.write_bytes(
        b"from plotnine import aes, geom_col, geom_errorbar, ggplot\n"
        b"plot = ggplot(rates, aes('dose', 'rate')) + geom_col()"
        b" + geom_errorbar(aes(ymin='low', ymax='high'))\n"
    )
    supplement = project / "manuscript" / "supplementary" / "S3_doses.md"
    supplement.write_bytes(b"# Figure S1\n\n![Reports by dose](../../figures/S1_doses.svg)\n")
    found = [(f.code, f.path.name, f.line) for f in gate_report(project).findings
             if f.code.startswith("figure-bars-")]  # fmt: skip
    assert found == [(_ERRORS, "S1_doses.py", 2)]


def _divergent(project: Path) -> list[tuple[str, str]]:
    """The divergent-display findings of the project, as (severity, message)."""
    return [(f.severity, f.message) for f in gate_report(project).findings
            if f.code == "divergent-display"]


def test_same_quantity_under_two_keys_is_said_and_fails_nothing(project: Path) -> None:
    """One quantity, two keys, two roundings — 3.84 in one place and 3.8 in another.

    Both displays are honest renderings of the value. The pair is said, as a note: the
    results file records nothing that tells it from two quantities that agree, or from one
    printed two ways on purpose, so it fails nothing (2026-11-11; Known gaps, "G8 fails no
    pair of keys for holding one value"). A pair declared one quantity still fails when it
    parts (`test_one_estimate_under_two_names_declared_one_fails_when_it_parts`).
    """
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["values"]["ror.duplicate"] = dict(document["values"]["ror.point"])
    document["values"]["ror.duplicate"]["display"] = "3.8"
    document["values"]["ror.duplicate"]["digits"] = 1
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)  # the edit is legitimate here; we are testing G8, not G1
    assert "divergent-display" not in codes(gate_report(project))
    assert [severity for severity, _ in _divergent(project)] == ["info"]


def _add_keys(project: Path, keys: dict[str, dict]) -> None:
    """Add keys to the example's fragment, each a copy of `ror.point` with no unit and the
    fields given, and sign the fragment again: these tests are of G8, not G1."""
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    point = document["values"]["ror.point"]
    for key, fields in keys.items():
        document["values"][key] = {**{k: v for k, v in point.items() if k != "unit"}, **fields}
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)


def test_two_quantities_that_happen_to_be_equal_fail_nothing(project: Path) -> None:
    """arXiv 2409.10841, rebuilt with the R emitter: a count of two conditions written "2"
    and a median ratio of 2.00, and a share written "0.0" beside a difference at "0.00", none of
    them with a unit, failed at drafting as one quantity written two ways, and the hint said
    to emit each pair once, which would have made the paper wrong. Equal values are all the
    record shows, so the pairs are said as notes and nothing fails."""
    _add_keys(project, {
        "design.n_conditions": {"value": 2, "display": "2", "digits": 0},
        "ratio.median_max": {"value": 2, "display": "2.00", "digits": 2},
        "time.share_equal": {"value": 0, "display": "0.0", "digits": 1},
        "accuracy.diff_min": {"value": 0, "display": "0.00", "digits": 2},
    })
    assert "divergent-display" not in codes(gate_report(project))
    said = _divergent(project)
    assert [severity for severity, _ in said] == ["info", "info"], said
    hint = next(f.hint for f in gate_report(project).findings if f.code == "divergent-display")
    assert "`unit`" in hint and "pick one display" not in hint


def test_one_correlation_in_apa_form_beside_its_interval_fails_nothing(project: Path) -> None:
    """PsyArXiv d8hkq_v1, an APA paper rebuilt with the R emitter: a correlation printed
    ".47" in the text and "0.47" beside its interval "[0.21, 0.72]", emitted under two keys
    as the results-binding skill says to emit a second display, failed `divergent-display`.
    One quantity printed two ways on purpose is what the skill asks for: a note, no failure.
    """
    _add_keys(project, {
        "cor.r": {"value": 0.4712, "display": ".47", "digits": 2},
        "cor.point": {"value": 0.4712, "display": "0.47", "digits": 2},
        "cor.ci_low": {"value": 0.2093, "display": "0.21", "digits": 2,
                       "bounds": "cor.point", "bound": "low"},
        "cor.ci_high": {"value": 0.7168, "display": "0.72", "digits": 2,
                        "bounds": "cor.point", "bound": "high"},
    })
    report = gate_report(project)
    assert not {"divergent-display", "declared-same-but-displayed-differently"} & codes(report)
    assert [severity for severity, _ in _divergent(project)] == ["info"]


def test_one_estimate_under_two_names_declared_one_fails_when_it_parts(project: Path) -> None:
    """The duplicate G8 is for: one estimate emitted under a second name, which a later run
    updates and the other does not. Declared one quantity with `same_as`, the pair fails the
    moment the two hold numbers the coarser display does not round both to, or are printed
    otherwise than as one rounding of the other: here with a unit one of them lacks."""
    _add_keys(project, {
        "est.main": {"value": 3.8439, "display": "3.84", "digits": 2},
        "est.abstract": {"value": 3.9012, "display": "3.90", "digits": 2,
                         "same_as": "est.main"},
        "est.summary": {"value": 3.8439, "display": "3.84 a.u.", "same_as": "est.main"},
    })
    found = codes(gate_report(project))
    assert {"declared-same-but-differs", "declared-same-but-displayed-differently"} <= found


@pytest.mark.parametrize(("second", "value", "display"), [
    ("APA's form, no leading zero", 0.4712, ".47"),
    ("a coarser rounding", 0.4712, "0.5"),
    ("a finer rounding", 0.4712, "0.4712"),
    ("trailing zeros", 0.4712, "0.47120"),
])
def test_a_second_display_declared_same_as_passes(
    project: Path, second: str, value: float, display: str
) -> None:
    """The author's decision on #628 (PsyArXiv d8hkq_v1, an APA paper: a correlation ".47"
    in the text and "0.47" beside its interval): `same_as` ties two displays of one value.
    The pair passes where the two hold one value and their displays differ only in form,
    and G8 notes nothing, the pair being declared."""
    _add_keys(project, {
        "cor.point": {"value": 0.4712, "display": "0.47", "digits": 2},
        "cor.r": {"value": value, "display": display, "same_as": "cor.point"},
    })
    report = gate_report(project)
    assert not {code for code in codes(report) if code.startswith("declared-same")}, second
    assert _divergent(project) == [], second


@pytest.mark.parametrize(("value", "display"), [
    (0.5188, ".52"), (0.5588, "0.6"), (0.4688, ".47"),
])
def test_a_second_display_declared_same_as_fails_when_the_values_part(
    project: Path, value: float, display: str
) -> None:
    """".47" declared the same as "0.52" holds another number, and the pair fails. So does
    one holding another value that the two displays round alike, ".47" for 0.4688 beside
    "0.47" for 0.4712: `same_as` ties two displays of one value, not two values, and the
    values are compared exactly, as before #628."""
    _add_keys(project, {
        "cor.point": {"value": 0.4712, "display": "0.47", "digits": 2},
        "cor.r": {"value": value, "display": display, "same_as": "cor.point"},
    })
    assert "declared-same-but-differs" in codes(gate_report(project))


def _declared_p(project: Path, display: str) -> set[str]:
    """The failures of a p value of 0.0004 shown "<0.001", beside one declared the same
    quantity and shown `display`."""
    _add_keys(project, {
        "p.main": {"value": 0.0004, "display": "<0.001"},
        "p.apa": {"value": 0.0004, "display": display, "same_as": "p.main"},
    })
    return codes(gate_report(project))


@pytest.mark.parametrize("display", ["<.001", "<0.0010", "< 0.001"])
def test_a_p_value_under_one_comparator_in_two_forms_passes(project: Path, display: str) -> None:
    """Round 1 of #628: a declared pair shown "<0.001" and APA's "<.001" failed, a display
    with a comparator being read as no number at all. The same comparator before one number
    written two ways is a difference of form."""
    found = _declared_p(project, display)
    assert not {code for code in found if code.startswith("declared-same")}, found


@pytest.mark.parametrize("display", ["≤0.001", "0.0004", "<0.01"])
def test_a_p_value_under_another_comparator_or_bound_fails(project: Path, display: str) -> None:
    """Another comparator, a comparator on one side only, or another bound is more than
    form: "<0.001" and "0.0004" say different things of one value."""
    assert "declared-same-but-displayed-differently" in _declared_p(project, display)


def test_a_group_tied_only_in_part_is_still_noted(project: Path) -> None:
    """Round 1 of #628: the note is left out only where `same_as` ties every key of the
    group. Two keys tied, ".47" and "0.47", and a third holding 0.4712 that nothing declares,
    shown "0.4712", are still said, the third among them."""
    _add_keys(project, {
        "cor.point": {"value": 0.4712, "display": "0.47"},
        "cor.r": {"value": 0.4712, "display": ".47", "same_as": "cor.point"},
        "cor.other": {"value": 0.4712, "display": "0.4712"},
    })
    said = _divergent(project)
    assert [severity for severity, _ in said] == ["info"], said
    assert "cor.other" in said[0][1] and "cor.r" in said[0][1]


@pytest.mark.parametrize("chain", [
    {"a.one": "a.two", "a.two": "a.three"},  # a chain
    {"a.one": "a.two", "a.two": "a.one"},  # a cycle
])
def test_keys_tied_through_a_chain_or_a_cycle_are_not_noted(
    project: Path, chain: dict[str, str]
) -> None:
    """Keys tied through a chain of `same_as`, or round a cycle, are one group: no note, and
    each declared pair is held, so nothing fails."""
    displays = {"a.one": ".47", "a.two": "0.47", "a.three": "0.5"}
    _add_keys(project, {
        key: {"value": 0.4712, "display": displays[key],
              **({"same_as": chain[key]} if key in chain else {})}
        for key in sorted({*chain, *chain.values()})
    })
    report = gate_report(project)
    assert _divergent(project) == []
    assert not {code for code in codes(report) if code.startswith(("declared-same", "same-as"))}


def test_a_count_and_a_percentage_that_coincide_are_not_one_quantity(project: Path) -> None:
    """56 sources and 56.0 per cent are two quantities that happen to share a number.

    G8 used to key collisions on the bare value, so this pair reported one quantity written
    two ways and failed the build. There was no fix available to the author except to change
    the paper until the coincidence went away, which is the tool corrupting the manuscript
    rather than protecting it. Units are what distinguish the two, and they are recorded.
    """
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    point = document["values"]["ror.point"]
    document["values"]["ror.point"] = {
        **point, "value": 56.0, "display": "56.0%", "digits": 1, "unit": "%",
    }
    document["values"]["sources.n"] = {
        **point, "value": 56, "display": "56", "digits": 0,
    }
    document["values"]["sources.n"].pop("unit", None)
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    # Verified to fail without the unit key: with G8 grouping on the bare value, this
    # fragment reports divergent-display and the build stops.
    assert "divergent-display" not in codes(gate_report(project))


@pytest.mark.parametrize(
    ("first", "second"),
    [("%", None), ("percent", "%"), ("years", "y")],
    ids=["once with no unit", "percent spelt two ways", "years spelt two ways"],
)
def test_one_quantity_whose_unit_is_written_two_ways_is_not_said(
    project: Path, first: str, second: str | None
) -> None:
    """A known gap (DESIGN.md, Known gaps, "G8 compares only values whose units agree"): one
    quantity emitted once with a unit and once with none, or with its unit spelt two ways,
    is no longer reported as written two ways. With the one unit on both, the pair is said."""

    def said(other: str | None) -> list[str]:
        _add_keys(project, {
            "share.text": {"value": 41.7, "display": "41.7", "digits": 1, "unit": first},
            "share.table": {"value": 41.7, "display": "41.7", "digits": 1,
                            **({"unit": other} if other else {})},
        })  # fmt: skip
        return [f.code for f in gate_report(project).findings if "share.text" in f.message
                and f.code in ("duplicate-quantity", "divergent-display")]  # fmt: skip

    assert said(second) == []
    # The other side of G8's keying on the unit: the same unit twice is one quantity.
    assert said(first) == ["duplicate-quantity"]


@pytest.mark.parametrize("value", [0, 1, -1])
def test_a_count_and_a_bound_that_both_are_zero_or_one_are_not_one_quantity(
    project: Path, value: int
) -> None:
    """A count of none, "0", and an interval's lower bound clamped at nought, "0.00", failed
    the athlete-leakage study's build as one quantity written two ways, as did a count of
    one beside a bound at one; the author could change neither. At nought and one, where
    bounds and shares clamp and counts are small, a whole count and a measured value are two
    quantities. A measured value under two keys and two roundings is still one."""
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    point = document["values"]["ror.point"]
    document["values"]["cohort.n_under_18"] = {**point, "value": value, "display": str(value),
                                               "digits": 0}  # fmt: skip
    document["values"]["reliability.ci_low"] = {**point, "value": float(value),
                                                 "display": f"{value}.00", "digits": 2}
    document["values"]["reliability.other"] = {**point, "value": float(value),
                                               "display": f"{value}.0", "digits": 1}
    for key in ("cohort.n_under_18", "reliability.ci_low", "reliability.other"):
        document["values"][key].pop("unit", None)
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    said = [f.message for f in gate_report(project).findings if f.code == "divergent-display"]
    assert said == [f"2 quoted keys hold the value {value}, written with decimals: "
                    "reliability.ci_low, reliability.other"], said


def _two_keys(project: Path, first: tuple, second: tuple) -> list[str]:
    """The divergent-display findings of a fragment that holds two more keys, each given as
    (value, display, digits)."""
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    point = document["values"]["ror.point"]
    for key, (value, display, digits) in (("one.key", first), ("other.key", second)):
        document["values"][key] = {**point, "value": value, "display": display, "digits": digits}
        document["values"][key].pop("unit", None)
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    return [f.message for f in gate_report(project).findings if f.code == "divergent-display"]


def test_a_count_and_a_bound_at_nought_are_two_however_the_number_was_written(
    project: Path,
) -> None:
    """Round 1 of #542: R writes a double 0 as `0`, so a bound clamped at nought arrives as
    an int beside the count. The kind is read from the display."""
    assert _two_keys(project, (0, "0", 0), (0, "0.00", 2)) == []


def test_a_value_written_whole_and_with_decimals_elsewhere_is_still_one_quantity(
    project: Path,
) -> None:
    """Round 1 of #542: away from nought and one, a count emitted again with decimals is
    still one quantity written two ways."""
    assert _two_keys(project, (2, "2", 0), (2.0, "2.00", 2)) == [
        "2 quoted keys hold the value 2: one.key, other.key"]


@pytest.mark.parametrize("value", [0, 1, -1])
def test_one_quantity_written_whole_and_with_decimals_at_nought_or_one_is_not_said(
    project: Path, value: int
) -> None:
    """The cost G8 accepts (round 2 of #542, finding 3; Known gaps, "G8 tells a count from a
    measure at nought and one by how each is written"): at nought, one and minus one, one
    quantity written whole in one place and with decimals in another is taken for two, and
    nothing is said. Pinned so that a change narrowing or widening the split is seen."""
    assert _two_keys(project, (value, str(value), 0), (float(value), f"{value}.0", 1)) == []


def test_a_display_edited_away_from_its_value_is_caught(project: Path) -> None:
    """A bonus from checking displays at emit time: the read path checks them too.

    Re-signing the sidecar hides a hand-edit from G1, but the edited fragment still has to
    be a coherent one. Changing a display to a number the value does not round to now fails
    on load, so the easiest form of the re-signing attack — retype the display, recompute
    the digest — no longer works.
    """
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["values"]["ror.point"]["display"] = "9.99"
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    assert "no-display" in codes(gate_report(project))


MARGINS = [
    {"kind": "sum", "key": "cohort.n_reports",
     "of": ["table2x2.a", "table2x2.b", "table2x2.c", "table2x2.d"]},
    {"kind": "sum", "key": "cohort.n_drug_reports", "of": ["table2x2.a", "table2x2.b"]},
    {"kind": "in_order", "key": "cohort.period_start", "of": ["cohort.period_end"]},
]  # fmt: skip


def _declare_relations(project: Path, relations: list[dict], flows: dict | None = None,
                       values: dict | None = None) -> dict:  # fmt: skip
    """What `em.relation` and `em.flow` would have written, put in the example's fragment."""
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["relations"] = relations
    if flows:
        document["flows"] = flows
    for key, value in (values or {}).items():
        document["values"][key] = {"value": value, "display": str(value), "quoted": False}
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    return document


def _edit_value(project: Path, key: str, value: int) -> None:
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["values"][key].update(value=value, display=str(value))
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)


def test_a_cell_that_no_longer_sums_to_its_margin_is_caught(project: Path) -> None:
    """The four cells of the 2x2 table and its margins: each bound, each passing on its own,
    and nothing held them to each other until the analysis declared it."""
    _declare_relations(project, MARGINS)
    clean = gate_report(project)
    assert not {f.code for f in clean.findings} & {"relation-broken", "relation-unresolved"}
    # The three relations declared here, and the flow the example itself records.
    assert clean.counts["relations_checked"] == 3 + 1
    _edit_value(project, "table2x2.d", 3381)
    assert "relation-broken" in codes(gate_report(project))


def test_a_period_that_ends_before_it_starts_is_caught(project: Path) -> None:
    _declare_relations(project, MARGINS)
    _edit_value(project, "cohort.period_start", 2025)
    assert "relation-broken" in codes(gate_report(project))


def test_a_relation_naming_a_key_nothing_emits_is_caught(project: Path) -> None:
    _declare_relations(project, [{"kind": "sum", "key": "cohort.n_reports",
                                  "of": ["table2x2.a", "table2x2.e"]}])  # fmt: skip
    assert "relation-unresolved" in codes(gate_report(project))


def test_a_flow_stage_that_its_exclusions_do_not_reach_is_caught(project: Path) -> None:
    """A flow diagram's counts, typed by hand, were the one place no check looked."""
    counts = {"flow.screening.stage.1": 4000, "flow.screening.stage.2": 426,
              "flow.screening.excluded.1.1": 3574}  # fmt: skip
    record = {"stages": [{"label": "Reports", "key": "flow.screening.stage.1"},
                         {"label": "Reports of the drug", "key": "flow.screening.stage.2"}],
              "exclusions": [[{"reason": "Another drug", "key": "flow.screening.excluded.1.1"}]],
              "overlapping": False}  # fmt: skip
    _declare_relations(project, [], flows={"screening": record}, values=counts)
    assert not {f.code for f in gate_report(project).findings} & {"flow-broken"}
    _edit_value(project, "flow.screening.excluded.1.1", 3575)
    assert "flow-broken" in codes(gate_report(project))


@pytest.mark.parametrize(
    ("named", "cited"),
    [("house-style", "project:house-style"), (None, r"project:\d+(?:[.,]\d+)*")],
    ids=["named", "unnamed"],
)
def test_a_projects_own_allowlist_is_reported_not_silent(
    project: Path, named: str | None, cited: str
) -> None:
    """`conventions:` and `terms:` are self-service on purpose. Invisible is not on purpose.

    A pattern of `\\d+` with a `why` of "house style" is schema-legal and disables G2, and
    the run read exactly like one that had exempted nothing. Every run now says how many
    numbers the project accounted for with its own rules, and which rules did it: by the
    name the author gave the rule (`id`), or by the start of its pattern.
    """
    paper = project / "paper.yaml"
    document = yaml.safe_load(paper.read_text(encoding="utf-8"))
    convention = {"why": "house style", "pattern": r"\d+(?:[.,]\d+)*"}
    if named:
        convention["id"] = named
    document["conventions"] = [convention]
    paper.write_text(
        yaml.safe_dump(document, sort_keys=False, allow_unicode=True), encoding="utf-8"
    )
    main_md(project).write_text(
        main_md(project).read_text(encoding="utf-8") + "\n\nLoose 4321, 9876 and 5.55 here.\n",
        encoding="utf-8",
    )

    report = gate_report(project)
    assert "schema-violation" not in codes(report)
    assert report.counts["atoms_project_exempt"] == 3
    finding = next(f for f in report.findings if f.code == "project-exemption")
    assert cited in finding.message


@pytest.mark.parametrize(
    "conventions",
    [
        pytest.param(r"\d+", id="a pattern where a list is expected"),
        pytest.param([r"\d+"], id="a list of patterns with no reason"),
        pytest.param([{"pattern": r"\d+"}], id="an entry with no reason"),
        pytest.param([{"pattern": r"\d+", "why": ""}], id="an entry with an empty reason"),
        pytest.param(
            [{"pattern": r"(?a)(?u)\d+", "why": "pasted"}], id="a pattern that does not compile"
        ),
    ],
)
def test_a_convention_the_schema_refuses_exempts_nothing(project: Path, conventions) -> None:
    """A `conventions:` in the wrong shape is not read, so the gate runs where it raised. What
    it must not do is read part of it: a pattern with no reason is not an exemption."""
    from manuscript_guard.cli import _run_gates

    paper = project / "paper.yaml"
    document = yaml.safe_load(paper.read_text(encoding="utf-8"))
    document["conventions"] = conventions
    paper.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")
    main_md(project).write_text(
        main_md(project).read_text(encoding="utf-8") + "\n\nLoose 4321 here.\n", encoding="utf-8"
    )

    report, _project, _chosen, _deferred = _run_gates(project)
    assert {"schema-violation", "unclassified-number"} <= codes(report)
    assert "gate-errored" not in codes(report)
    assert report.counts["atoms_project_exempt"] == 0


@pytest.mark.parametrize(
    "conventions",
    [
        pytest.param(
            [
                {"id": "house", "pattern": "7 spare kits", "why": "kept by every site"},
                {"id": "house", "pattern": "13 spare forms", "why": "kept by every site"},
            ],
            id="named alike",
        ),
        pytest.param(
            [
                {"pattern": "(?i)(?:each site kept )?7 spare kits", "why": "kept by every site"},
                {"pattern": "(?i)(?:each site kept )?13 spare forms", "why": "kept by every site"},
            ],
            id="patterns that begin alike",
        ),
    ],
)
def test_conventions_under_one_name_each_exempt_their_own_number(
    project: Path, conventions
) -> None:
    """A rule's matches were kept under its name, so a second convention under the same
    name, an `id` given twice or two patterns whose first 24 characters agree, replaced the
    first one's: the number the first was written for failed as unbound."""
    from manuscript_guard.cli import _run_gates

    paper = project / "paper.yaml"
    document = yaml.safe_load(paper.read_text(encoding="utf-8"))
    document["conventions"] = conventions
    paper.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")
    main_md(project).write_text(
        main_md(project).read_text(encoding="utf-8")
        + "\n\nEach site kept 7 spare kits and 13 spare forms.\n",
        encoding="utf-8",
    )

    report, _project, _chosen, _deferred = _run_gates(project)
    assert "unclassified-number" not in codes(report), report.render(project)
    assert report.counts["atoms_project_exempt"] == 2


def test_a_number_typed_into_a_file_that_is_not_utf8_is_not_a_pass(project: Path) -> None:
    """G2 cannot read the file, so it cannot report the number in it. The run fails all the
    same at every stage, on a finding that names the file, and nothing is built from it."""
    from manuscript_guard.cli import _run_gates, main
    from manuscript_guard.policy import STAGES

    path = main_md(project)
    path.write_bytes(path.read_bytes() + b"\nThe caf\xe9 saw 4321 patients.\n")

    for stage in STAGES:
        report, _project, _chosen, _deferred = _run_gates(project, stage=stage)
        assert "manuscript-unreadable" in codes(report), stage
        assert "gate-errored" not in codes(report), stage
    assert main(["build", str(project), "--offline"]) == 1
    assert main(["build", str(project), "--offline", "--skip-checks"]) == 2
    assert not list((project / "build").rglob("*.docx"))


@pytest.mark.parametrize(
    "convention",
    ["p < 0.37", "p < 0.5", "89% CI", "power of 63%"],
)
def test_near_miss_conventions_are_not_waved_through(project: Path, convention: str) -> None:
    """The allowlist is pinned to conventional values, not to the shape of a phrase.

    A rule matching "p < <anything>" would let every reported p-value in the paper through
    as a convention, which is precisely backwards: a p-value you obtained is a result.
    """
    path = main_md(project)
    path.write_text(
        path.read_text(encoding="utf-8") + f"\n\nAn added sentence with {convention} in it.\n",
        encoding="utf-8",
    )
    assert "unclassified-number" in codes(gate_report(project))


@pytest.mark.parametrize(
    ("sentence", "unbound"),
    [
        # The athlete-leakage study, 2026-11-06: "Table 2's are not" failed as "2's".
        ("The models of Table 1's first rows are adjusted.", False),
        ("The bars of Figure 1\N{RIGHT SINGLE QUOTATION MARK}s upper panel are intervals.", False),
        ("The counts were 7's and 8's.", True),
    ],
)
def test_a_possessive_pointer_is_a_pointer_and_a_possessive_number_is_not(
    project: Path, sentence: str, unbound: bool
) -> None:
    """A table or a figure named in the possessive is pointed at: the cross-reference rule
    covered "Table 2" and left the word "2's" a number bound to nothing. A number with an
    apostrophe and nothing before it to point is still a number."""
    path = main_md(project)
    path.write_text(path.read_text(encoding="utf-8") + f"\n\n{sentence}\n", encoding="utf-8")
    assert ("unclassified-number" in codes(gate_report(project))) is unbound


_TWIN = (
    "\n@article{fictionalSecondSignal2019,\n  title = {A second fictional signal},\n"
    "  author = {Fictional, Eve},\n  year = {2019},\n}\n"
)
#: Authors whose names a .bib writes in TeX, as Better BibTeX's BibTeX export does, and one
#: whose TeX the check does not read (`\IJ`).
_NAMES_IN_TEX = r"""
@article{angstromNotes2018,
  title = {Fictional notes},
  author = {{\AA}ngstr{\"o}m, Nils and Other, Eve},
  year = {2018},
}
@article{lokkeSurvey2017,
  title = {A fictional survey},
  author = {Anne L{\o}kke},
  year = {2017},
}
@article{sebekCohort2016,
  title = {A fictional cohort},
  author = {\v{S}ebek, Petr},
  year = {2016},
}
@article{ijsselRegister2015,
  title = {A fictional register},
  author = {{\IJ}ssel, Jan},
  year = {2015},
}
@report{whoReport2018, author = {{World Health Organization}}, year = {2018},}
@article{benitezStudy2018, author = {Ben{\'\i}tez, Ana}, year = {2018},}
@article{citanStudy2018, author = {\c{C}{\i}tan, Ali}, year = {2018},}
"""


@pytest.mark.parametrize(
    ("typed", "year", "said"),
    [
        ("(Fictional, 2021)", "2021", "holds a work by Fictional from 2021: if it is the one "
         "meant, cite it with its key, [@fictionalHepaticCohort2021],"),
        # The year's letter and the given names are not compared: a work by that name and
        # year is one the author may mean, not the one they meant.
        ("(Fictional, 2021b)", "2021b", "holds a work by Fictional from 2021: if it is the one "
         "meant, cite it with its key, [@fictionalHepaticCohort2021],"),
        # A name the .bib writes in TeX is read as a reader sees it, and typed with or
        # without its accents or its letters of their own.
        ("(\N{LATIN CAPITAL LETTER A WITH RING ABOVE}ngstr"
         "\N{LATIN SMALL LETTER O WITH DIAERESIS}m, 2018)", "2018", "[@angstromNotes2018]"),
        ("(Angstrom, 2018)", "2018", "[@angstromNotes2018]"),
        ("L\N{LATIN SMALL LETTER O WITH STROKE}kke (2017)", "2017", "[@lokkeSurvey2017]"),
        ("(Lokke, 2017)", "2017", "[@lokkeSurvey2017]"),
        ("(\N{LATIN CAPITAL LETTER S WITH CARON}ebek, 2016)", "2016", "[@sebekCohort2016]"),
        ("(IJssel, 2015)", "2015", "the name of [@ijsselRegister2015], from 2015, holds TeX"),
        ("(Fictional et al., 2019)", "2019", "[@fictionalClassSignal2019]"),
        ("(Fictional & Other, 2019)", "2019", "[@fictionalClassSignal2019]"),
        ("Fictional (2019)", "2019", "[@fictionalClassSignal2019]"),
        ("Fictional and Other (2021)", "2021", "[@fictionalHepaticCohort2021]"),
        ("(Other, 2018; Fictional, 2021)", "2021", "[@fictionalHepaticCohort2021]"),
        ("(Other, 2018; Fictional, 2021)", "2018", "adding the work there first if"),
        ("(Fictional, 2018)", "2018", "adding the work there first if it is not yet in it"),
        # Round 2 of #510: a group's name, and TeX the check misreads, match no entry, and
        # the hint must not say the work is missing. A dotless i no accent is on, before a
        # t, is still read as `\it` (DESIGN.md, Known gaps).
        ("(World Health Organization, 2018)", "2018", "adding the work there first if"),
        ("(\N{LATIN CAPITAL LETTER C WITH CEDILLA}\N{LATIN SMALL LETTER DOTLESS I}tan, 2018)",
         "2018", "adding the work there"),
        # An accent on a dotless i, `{\'\i}`, is read as the letter since #520.
        ("(Ben\N{LATIN SMALL LETTER I WITH ACUTE}tez, 2018)", "2018", "[@benitezStudy2018]"),
        ("(Benitez, 2018)", "2018", "[@benitezStudy2018]"),
        ("(Fictional, 2019)", "2019", "2 works by Fictional from 2019"),
        ("(March, 2019)", "2019", "a date is one placeholder"),
    ],
)
def test_the_year_of_a_citation_typed_as_text_fails_and_its_hint_names_the_key(
    project: Path, typed: str, year: str, said: str
) -> None:
    """A co-author types "(Fictional, 2018)" in Word, `import` merges it as text, and G2 fails
    the year as a number nobody bound: it still does, matched or not. Its hint said to bind
    it with {{results.<key>}}, where the author needed the work's key: it names the key now,
    each of them where `references.bib` holds two works of that first author and year, and
    says to add the work if it is not there yet. A month is no name.

    Round 1 of #510: a work by that family name and year was said to be the one meant, though
    neither the year's letter nor a given name is compared, and the old hint was dropped; and
    a name the .bib writes in TeX, `{\\AA}ngstr{\\"o}m`, was said to be missing, which invites
    a second entry. The hint says what may be, and a name it cannot read is not missing."""
    bib = project / "literature" / "references.bib"
    added = _NAMES_IN_TEX + (_TWIN if "2 works" in said else "")
    bib.write_text(bib.read_text(encoding="utf-8") + added, encoding="utf-8")
    path = main_md(project)
    path.write_text(
        path.read_text(encoding="utf-8") + f"\n\nThe counts were as reported {typed}.\n",
        encoding="utf-8",
    )
    report = gate_report(project)
    found = [f for f in report.failures if f.code == "unclassified-number"
             and f.message == f"{year!r} is not bound to any source"]  # fmt: skip
    assert len(found) == 1, report.render(project)
    hint = " ".join(found[0].hint.split())
    assert said in hint and "holds no work" not in hint, hint
    if "a date" not in said:
        # Said as what may be, never as fact, and the hint G2 gave before stays after it,
        # whether the hint names a key, an entry it cannot read, or none (Known gaps F04).
        assert "typed as text" in hint and "Otherwise, bind it with {{results" in hint, hint
        assert "holds the work" not in hint, hint
    if "adding the work there" in said:
        # Where no entry is the work, none is named as one the author may mean.
        assert "[@" not in hint.split("Otherwise,")[0].replace("[@key]", ""), hint


#: Works of `references.bib` for the limits of G2's hint: one a citation names, beside one a
#: citation just past the limit does not; a name in Chinese or Japanese, folded, in TeX the
#: hint does not read, and an author written as a `@string` macro.
_TYPED_YEAR_BIB = r"""
@string{smithname = "Smith, Ann"}
@article{fictional2018, author = {Fictional, Anne}, year = {2018}}
@article{fictional2014, author = {Fictional, Anne}, year = {2014}}
@article{yamada2015, author = {Yamada, Taro}, year = {2015}}
@article{kanji2015, author = {山田, 太郎}, year = {2015}}
@article{zhang2019, author = {Zhang, Wei}, year = {2019}}
@article{hanzi2019, author = {张, 伟}, year = {2019}}
@article{vanberg2017, author = {van Berg, Jan}, year = {2017}}
@article{muller2016, author = {M{\"u}ller, Hans}, year = {2016}}
@article{ijssel2014, author = {{\IJ}ssel, Jan}, year = {2014}}
@article{macro2013, author = smithname, year = {2013}}
@article{smith2012, author = {Smith, Ann}, year = {2012}}
@article{japan2011, author = {Japan, Ken}, year = {2011}}
"""
#: What G2 says where it reads no citation: the hint it gave before, and nothing more.
_NOT_READ = "generic"
#: What it says of a citation it reads and finds no entry for.
_NO_ENTRY = "adding the work there first if it is not yet in it"


@pytest.mark.parametrize(
    ("typed", "said"),
    [
        ("(Fictional, 2018)", "[@fictional2018]"),
        ("(Fictional, 2018, p. 4)", _NOT_READ),
        ("(see Fictional, 2018)", "[@fictional2018]"),
        ("(e.g., Fictional, 2018)", _NOT_READ),
        ("(fictional, 2018)", _NOT_READ),
        ("(Yamada, 2015)", "[@yamada2015]"),
        ("(山田, 2015)", _NOT_READ),
        ("(Zhang, 2019)", "[@zhang2019]"),
        ("(张, 2019)", _NOT_READ),
        ("Fictional (2018)", "[@fictional2018]"),
        ("Fictional's (2018)", _NO_ENTRY),
        ("Japan (2011)", "[@japan2011]"),
        ("Japan (2018)", _NO_ENTRY),
        ("in japan (2011)", _NOT_READ),
        ("(van Berg, 2017)", "[@vanberg2017]"),
        ("(Berg, 2017)", "[@vanberg2017]"),
        ("(Bergen, 2017)", _NO_ENTRY),
        ("(Müller, 2016)", "[@muller2016]"),
        ("(Muller, 2016)", "[@muller2016]"),
        ("(Mueller, 2016)", "[@muller2016]"),
        ("(Moller, 2016)", _NO_ENTRY),
        ("(IJssel, 2014)", "the name of [@ijssel2014], from 2014, holds TeX"),
        ("(Other, 2014)", "the name of [@ijssel2014], from 2014, holds TeX"),
        ("(Fictional, 2014)", "[@fictional2014]"),
        ("(Smith, 2012)", "[@smith2012]"),
        ("(Smith, 2013)", _NO_ENTRY),
    ],
)
def test_the_hint_for_a_typed_year_reads_the_author_year_forms_and_no_more(
    tmp_path: Path, typed: str, said: str
) -> None:
    """Known gaps, "The year of a citation typed as text is read in the author-year forms
    only", each limit beside the case just inside it: a page after the year, a part opening
    with a lower-case word and a comma, a name that opens with no capital or is written in
    Chinese or Japanese are read as no citation, though the work is there; a possessive is
    read with its "'s" and matches nothing; a capitalised word is a name, "Japan"; a family
    name is compared by its last word, "Müller" as "Muller" and "Mueller" are, and not as
    another letter; a name in TeX the hint
    does not read is named for every citation of its year that matches no other entry; and
    an author written as a `@string` macro is not found."""
    from manuscript_guard.gates.numbers import _GENERIC_HINT, _hint_for
    from manuscript_guard.gates.typed_citations import works_by
    from manuscript_guard.text.masking import mask
    from manuscript_guard.text.tokens import find_atoms

    bib = tmp_path / "references.bib"
    bib.write_text(_TYPED_YEAR_BIB, encoding="utf-8")
    works = works_by(bib)
    text = f"The counts were as reported {typed}."
    years = [a for a in find_atoms(text, mask(text)) if re.fullmatch(r"(18|19|20)\d\d", a.text)]
    assert len(years) == 1, years
    hint = " ".join(_hint_for(years[0], works).split())
    if said == _NOT_READ:
        assert hint == _GENERIC_HINT, hint
        return
    assert said in hint and "Otherwise, bind it with {{results" in hint, hint
    if said == _NO_ENTRY:
        assert "[@" not in hint.replace("[@key]", ""), hint
    elif "holds TeX" not in said:
        assert "holds TeX" not in hint, hint


@pytest.mark.parametrize(
    ("typed", "read"),
    [("Fictional (2018)", True), ("Fictional~(2018)", False),
     ("Fictional et al. (2018)", True), ("Fictional et~al. (2018)", False)],
)  # fmt: skip
def test_a_latex_tie_before_a_typed_year_is_not_read_as_a_space(typed: str, read: bool) -> None:
    """Known gaps, "The year of a citation typed as text is read in the author-year forms
    only": a LaTeX citation that ties the name to its year, `Name~(2018)`, is read as no
    citation, and gets the generic hint."""
    from manuscript_guard.gates.typed_citations import typed_citation

    found = typed_citation(typed, len(typed) - 5, len(typed) - 1)
    assert (found is not None) is read, found
    if read:
        assert (found.name, found.year) == ("Fictional", "2018")


@pytest.mark.parametrize(
    "title", ["# References", "## 7. Reference list {-}", "**References**", "**References:**"]
)
def test_a_number_in_a_typed_reference_list_passes_and_one_just_after_it_fails(
    project: Path, title: str
) -> None:
    """The real-paper corpus (PsyArXiv d8hkq_v1, rebuilt with `init --from`): G2 failed each
    year, volume and page of the typed reference list, 169 of them, and told the author to
    bind each. A list `text.reference_lists` finds, under a heading or a title in bold, holds
    no claim of the paper's, and its numbers are not read. Where it ends, at a table's caption
    after it, they are again: 4321 there still fails, and so does one typed in the sentence
    before the list. A binding typed in the list is still checked."""
    path = main_md(project)
    path.write_text(
        path.read_text(encoding="utf-8") + "\n\nWe counted 8765 more.\n\n"
        f"{title}\n\nSmith, J. A., & Jones, B. (2020). A title of work. *Journal of Things*, "
        "*12*(3), 45--67. https://doi.org/10.1000/xyz123\n\n"
        "Lee, C. (2018). *A book of things*. Publisher. {{results.no_such_key}}\n\n"
        "Table 9. Counts; 4321 were seen.\n",
        encoding="utf-8",
    )
    report = gate_report(project)
    failed = {f.message for f in report.failures if f.gate == "G2"}
    assert "'4321' is not bound to any source" in failed, report.render(project)
    assert "'8765' is not bound to any source" in failed, report.render(project)
    for listed in ("2020", "12*(3", "45--67", "2018", "10.1000/xyz123"):
        assert f"{listed!r} is not bound to any source" not in failed, failed
    assert any(f.code == "unresolved-binding" for f in report.failures), failed


@pytest.mark.parametrize(
    "title", ["# References", "## 7. Reference list {-}", "**References**", "**References:**"]
)
@pytest.mark.parametrize(
    "after",
    ["[^mgnote]: We excluded 4321 patients.", "Abstract\n\nWe excluded 4321 patients.",
     "**Appendix**\n\nWe excluded 4321 patients.", "3. Conclusion\n\nWe excluded 4321 patients.",
     # Round 2 of #638: pandoc's escaped number, and a caption numbered with a letter.
     "3\\. Conclusion\n\nWe excluded 4321 patients.", "Table A1. We excluded 4321 patients.",
     # The final check of #638: each caption's shape, and Roman and bracketed numbers as
     # pandoc 3.9 writes a Word title so numbered.
     "Fig. A2. Rates of 4321 patients.", "TABLE A1 | Counts of 4321 patients.",
     "Supplementary Table A1. We excluded 4321 patients.",
     "III\\. Results\n\nWe excluded 4321 patients.", "3\\) Conclusion\n\nWe excluded 4321.",
     "Table A.1. Counts of 4321 patients.", "Figure A2 Rates of 4321 patients."],
    ids=["note", "abstract", "appendix in bold", "numbered conclusion", "escaped number",
         "lettered caption", "fig.", "caption bar", "supplementary", "roman", "bracketed",
         "dotted appendix number", "no stop"],
)
def test_a_note_or_a_section_s_name_after_a_typed_list_ends_it(
    project: Path, title: str, after: str
) -> None:
    """Round 1 of #638: pandoc puts a Word paper's notes after its last section, the
    reference list, and the list ran on over them: "We excluded 4321 patients." in a note
    passed G2, where it failed before the list was let through. A footnote's definition ends
    the list, and so does a line that is a section's name alone (`section_name_alone`)."""
    path = main_md(project)
    path.write_text(
        path.read_text(encoding="utf-8") + "\n\nAs noted.[^mgnote]\n\n"
        f"{title}\n\nLee, C. (2018). *A book of things*. Publisher.\n\n{after}\n",
        encoding="utf-8",
    )
    failed = {f.message for f in gate_report(project).failures if f.gate == "G2"}
    assert "'4321' is not bound to any source" in failed, failed
    assert "'2018' is not bound to any source" not in failed, failed


def test_a_paragraph_after_a_typed_list_with_nothing_to_end_it_is_read_as_an_entry(
    project: Path,
) -> None:
    """Known gaps: a paragraph of the paper's own straight after the list, under no heading,
    caption, note or section's name, is read as one more entry, and its numbers pass."""
    path = main_md(project)
    path.write_text(
        path.read_text(encoding="utf-8") + "\n\n# References\n\n"
        "Lee, C. (2018). *A book of things*. Publisher.\n\nWe excluded 4321 patients.\n",
        encoding="utf-8",
    )
    failed = {f.message for f in gate_report(project).failures if f.gate == "G2"}
    assert "'4321' is not bound to any source" not in failed, failed


@pytest.mark.parametrize(
    ("typed", "named"),
    [
        ("Fictional (2021)", True),
        ("Fictional et al. (2021)", True),
        ("Fictional~(2021)", False),
        ("Fictional et~al. (2021)", False),
    ],
    ids=["space", "et al", "tie", "et~al"],
)
def test_a_latex_citation_typed_with_a_tie_before_its_year_is_given_the_generic_hint(
    project: Path, typed: str, named: bool
) -> None:
    """Known gaps (round 1 of #510): LaTeX's tie, `Fictional~(2021)` or `Fictional et~al.
    (2021)`, is not read as a space between the name and the year, so G2's hint for the year
    is the generic one and names no key; written with a space, the same citation is told
    `\\cite{fictionalHepaticCohort2021}`."""
    shutil.rmtree(project / "manuscript")
    shutil.copytree(TWIN, project / "manuscript")
    path = project / "manuscript" / "main.tex"
    anchor = "This analysis asks whether the signal extends to example-drug specifically"
    text = path.read_text(encoding="utf-8")
    assert text.count(anchor) == 1
    path.write_text(text.replace(anchor, f"As {typed} reported, it was studied. {anchor}"),
                    encoding="utf-8")  # fmt: skip
    found = [f for f in gate_report(project).failures if f.code == "unclassified-number"
             and f.message == "'2021' is not bound to any source"]  # fmt: skip
    assert len(found) == 1, [f.message for f in gate_report(project).failures]
    hint = " ".join(found[0].hint.split())
    assert ("\\cite{fictionalHepaticCohort2021}" in hint) is named, hint
    assert ("typed as text" in hint) is named, hint


def _in_methods(project: Path, sentence: str) -> None:
    path = main_md(project)
    anchor = "Reporting follows the checklist"
    text = path.read_text(encoding="utf-8")
    assert anchor in text
    path.write_text(text.replace(anchor, f"{sentence}\n\n{anchor}", 1), encoding="utf-8")


def test_an_escaped_threshold_is_still_a_convention(project: Path) -> None:
    """Pandoc's Markdown writer escapes every comparison, so a Methods section converted from
    Word reads `p \\< 0.05` and `ROR \\> 2`; `import` escapes a `>` that a `<` earlier in the
    paragraph could close as a tag. Each prints the bare character. G2 read neither: the
    threshold rules never matched, and `\\>3` was an atom no rule began at."""
    _in_methods(
        project,
        r"Significance was set at p \< 0.05; a signal needed ROR \> 2, IC025 \> 0 and \>3 cases.",
    )
    report = gate_report(project)
    # The example declares its alpha and its case threshold, so the two that equal them fail
    # as typed parameters: a verdict only a number read as a convention can get.
    typed = sorted(f.message.split()[0] for f in report.failures if f.code == "typed-parameter")
    assert typed == ["'0.05'", "'3'"], report.render(project)
    assert codes(report) == {"typed-parameter"}, report.render(project)


@pytest.mark.parametrize("where", ["abstract", "methods"])
def test_a_structured_abstract_cannot_state_its_own_signal_threshold(
    project: Path, where: str
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A structured abstract cannot state its own signal
    threshold"): `methods_only` rules need a Methods heading, and the abstract's chain is
    `("Abstract",)`, so a threshold its **Methods.** part states is an unbound number, where
    the same sentence under the Methods heading is a convention."""
    sentence = "Signals were those with IC025 > 0."
    if where == "methods":
        _in_methods(project, sentence)
    else:
        path = main_md(project)
        text = path.read_text(encoding="utf-8")
        anchor = "against all other drugs.\n**Results.**"
        assert anchor in text
        path.write_text(text.replace(anchor, anchor.replace(".\n", f". {sentence}\n"), 1),
                        encoding="utf-8")  # fmt: skip
    report = gate_report(project)
    found = [(f.code, f.message.split()[0]) for f in report.failures]
    expected = [("unclassified-number", "'0'")] if where == "abstract" else []
    assert found == expected, report.render(project)


def test_an_escaped_threshold_between_escaped_backticks_is_still_a_convention(
    project: Path,
) -> None:
    """`import` writes a backslash before every backtick typed in Word, and G2 paired the
    escaped backticks as a code span: in `` (\\` ROR \\> 2 \\`) `` the `\\>` was taken for a
    backslash code prints, and the threshold pandoc prints, `ROR > 2`, was an unbound
    number. An escaped backtick opens no code span; one before a code span's closing run
    closes it, as pandoc reads it."""
    _in_methods(project, "A signal needed (\\` ROR \\> 2 \\`) here.")
    report = gate_report(project)
    assert "unclassified-number" not in codes(report), report.render(project)
    _in_methods(project, "A signal needed `ROR\\` and ROR \\> 2 here.")
    assert "unclassified-number" not in codes(gate_report(project))


@pytest.mark.parametrize(
    "written",
    [
        pytest.param(r"A signal needed ROR \> 7 here.", id="no-conventional-value"),
        pytest.param(r"A signal needed p \< 0.37 here.", id="no-conventional-p"),
        pytest.param(r"A signal needed \>9 cases here.", id="no-conventional-count"),
        pytest.param(
            "Of the reports,\n412)\\>ULOQ were excluded.", id="list-marker-at-a-line-start"
        ),
        pytest.param("## 1204\\<ULOQ reports", id="numbered-heading"),
        pytest.param(r"A signal needed `ROR \> 2` here.", id="backslash-printed-in-code"),
        pytest.param(r"A signal needed \\>3 cases here.", id="backslash-printed-before-it"),
    ],
)
def test_an_escaped_comparison_does_not_launder_a_number(project: Path, written: str) -> None:
    """Read as the character it prints, and no further. Read as a space, the backslash met a
    rule that wanted one: `412)\\>ULOQ` at a line start was a list marker, and 412 passed. And
    a backslash that prints is no escape: in code, or after another backslash, `\\>` prints
    both characters, and `ROR \\> 2` there is not the threshold."""
    _in_methods(project, written)
    assert "unclassified-number" in codes(gate_report(project))


#: A fenced listing of Python in the Methods, around one line.
_TICKS_LISTING = "`" * 3 + "python\n{}\n" + "`" * 3 + "\n"


def _g2_failed(project: Path) -> list[tuple[str, str]]:
    return [(f.code, f.message.split()[0]) for f in gate_report(project).failures
            if f.gate == "G2"]  # fmt: skip


@pytest.mark.parametrize(
    ("written", "failed"),
    [
        (r"A signal needed n\>3 cases here.", [("typed-parameter", "'3'")]),
        # The other side: unescaped, `n>3` is one word, and unbound.
        ("A signal needed n>3 cases here.", [("unclassified-number", "'n>3'")]),
    ],
    ids=["escaped", "printed as typed"],
)
def test_an_escaped_comparison_is_split_where_the_printed_text_is_not(
    project: Path, written: str, failed: list[tuple[str, str]]
) -> None:
    """A known gap (DESIGN.md, Known gaps, "G2 reads an escaped comparison by a pattern, not
    as pandoc does", "Split where the printed text is not"): the backslash is blanked, so
    `n\\>3 cases` is read as `n` and a count of `>3 cases`, a typed copy of the example's
    case threshold, where `n>3 cases`, which pandoc prints for both, is one unbound word."""
    _in_methods(project, written)
    assert _g2_failed(project) == failed


@pytest.mark.parametrize(
    ("written", "failed"),
    [
        (_TICKS_LISTING.format(r'print("Signal if ROR \> 2")'), []),
        # The other side of the threshold rule: a value no rule names is still found.
        (_TICKS_LISTING.format(r'print("Signal if ROR \> 7")'), [("code-block-text-number",
                                                                  "'7'")]),
    ],
    ids=["a conventional threshold", "no conventional value"],
)
def test_an_escaped_comparison_in_a_listing_is_read_as_the_threshold(
    project: Path, written: str, failed: list[tuple[str, str]]
) -> None:
    """A known gap (DESIGN.md, Known gaps, "G2 reads an escaped comparison by a pattern, not
    as pandoc does", "In text that is not Markdown"): a listing prints its backslash, and
    `print("Signal if ROR \\> 2")` is read as the threshold `ROR > 2` all the same."""
    _in_methods(project, written)
    assert _g2_failed(project) == failed


@pytest.mark.parametrize(
    ("tail", "number"),
    [
        ("# Results\n\nThe excess was significant\n# Methods\n(p < 0.001).\n", "0.001"),
        ("# Results\n\nThe excess was significant\nMethods\n=======\n\n(p < 0.001).\n", "0.001"),
        ("# Results\n\nThe reporting odds ratio was\n## 3.84 times the background.\n", "3.84"),
        ("# Results\n\n#\n3.84 times the background rate was reported.\n", "3.84"),
    ],
    ids=["atx", "setext", "numbered atx", "lone hash"],
)
def test_a_heading_pandoc_prints_as_prose_does_not_excuse_a_number(
    project: Path, tail: str, number: str
) -> None:
    """Pandoc does not let a heading interrupt a paragraph, so a `# Methods` line directly
    under Results prose is printed as part of that prose. G2 took it for a heading, and the
    `p < 0.001` under it passed as the alpha chosen in advance. The same line starting with a
    number was taken for heading numbering, and so was a number on the line after a lone `#`,
    which pandoc prints as an empty heading above an ordinary paragraph."""
    path = main_md(project)
    path.write_text(path.read_text(encoding="utf-8") + "\n\n" + tail, encoding="utf-8")
    report = gate_report(project)
    assert any(
        f.code == "unclassified-number" and repr(number) in f.message for f in report.failures
    )


@pytest.mark.parametrize(
    "tail",
    [
        # Pandoc reads a table between lines of dashes, and prints the heading under it. The
        # walk does not model such a table, so it read the rows as a paragraph and the
        # heading as part of it.
        "# Methods\n\nAlpha was set in advance.\n\n-----------  -----------\n"
        "Age          Years\n-----------  -----------\n# Results\n\n"
        "The excess was significant (p < 0.001).\n",
        # Pandoc prints a level-7 heading; the walk stopped at six hashes.
        "# Methods\n\nAlpha was set in advance.\n\n####### Note\n# Results\n\n"
        "The excess was significant (p < 0.001).\n",
    ],
    ids=["dash table", "seven hashes"],
)
def test_a_heading_line_the_walk_does_not_place_still_ends_methods(
    project: Path, tail: str
) -> None:
    """Whatever the walk misses, it reads as paragraph text, and a paragraph swallowed the
    real `# Results` below it: the Methods section ran on, and the p-value passed as the
    alpha. A line shaped like a heading now ends the section it is in whether or not the walk
    places it; only a heading the walk does place can open Methods."""
    path = main_md(project)
    path.write_text(path.read_text(encoding="utf-8") + "\n\n" + tail, encoding="utf-8")
    report = gate_report(project)
    assert any(
        f.code == "unclassified-number" and "'0.001'" in f.message for f in report.failures
    )


RESULTS_READ_AS_METHODS = {
    # Pandoc prints a level-2 heading reading "# Results". Its literal title matched no
    # Results pattern, so it nested under Methods and kept the Methods rules. `main` read the
    # line as an ATX "Results", and reported the number.
    "a hashed title over a rule": (
        "# Methods\n\nAlpha was set in advance.\n\n# Results\n---\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a hashed title over a rule under prose": (
        "# Methods\n\nAlpha was set in advance.\n\nProse ran on\n# Results\n---\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a bulleted title over a rule": (
        "# Methods\n\nAlpha was set in advance.\n\n- Results\n---\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # A wrapped "# of reports" ended the Results for the gates, and the subsection under it
    # read as Methods. Pandoc prints the line as text, inside the Results.
    "a wrapped hash over a methods-like subsection": (
        "# Results\n\nReporting rose over the period, and the\n# of reports naming the drug "
        "doubled.\n\n## Sensitivity analyses\n\nThe estimate was unchanged (p < 0.001).\n"
    ),
    # A `<del>` closed mid-line was counted open for the rest of the file, so a later line
    # ending in `</del>` ended its paragraph and the `# Methods` under it became a heading.
    "a deletion closed mid-line": (
        "# Results\n\n<del>The excess was not\nsignificant.</del> It was.\n\n"
        "The reporting odds ratio was <del>not</del>\n# Methods\n(p < 0.001).\n"
    ),
    # Indented, a comment is inline: it starts a paragraph, which the `#` line continues.
    "an indented comment": (
        "# Results\n\n <!-- TODO: check -->\n# Methods\n\nThe excess was significant "
        "(p < 0.001).\n"
    ),
    # A no-break space after the hash: pandoc prints the line as text. `main`'s `\s` ended
    # the Methods there; the fallback did not.
    "a hash and a no-break space": (
        "# Methods\n\nAlpha was set in advance.\n\nProse ran on\n#" + chr(0xA0) + "Results\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # Found by the fifth review. An underline or a rule written after a comment is text:
    # blanked, the comment left a line the walk read as `===`, or as a rule.
    "an underline after a comment": (
        "# Results\n\nMethods\n<!-- -->===\n\nThe excess was significant (p < 0.001).\n"
    ),
    "a rule with a comment after it": (
        "# Results\n\nThe excess was clear.\n\n--- <!-- revised -->\n<!-- TODO --># Methods\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # Pandoc reads the rest of a tag's line over an underline as a setext title, "# Methods",
    # not as a `#` heading.
    "a tag and a hash over an underline": (
        "# Results\n\n<div># Methods\n-\n\nThe excess was significant (p < 0.001).\n\n</div>\n"
    ),
    # A `#` heading after a tag or a comment on its line, which `main` never read, opened
    # Methods wherever the walk wrongly started a block.
    "a hash after a tag under a stray closing tag": (
        "# Results\n\nSome text\n</script>\n<ins># Methods\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a hash after a comment under a raw tag and an indented line": (
        "# Results\n\n<del>\n    Old sentence.\n<!-- moved --># Methods\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # A pipe that is escaped, or in code, is text: the table ended above it, and the
    # heading under it was skipped by the net as a table row.
    "an escaped pipe under a table": (
        "# Methods\n\nAlpha was set in advance.\n\n| a | b |\n|---|---|\n| 1 | 2 |\n"
        "Results \\| x\n===\n\nThe excess was significant (p < 0.001).\n"
    ),
    "a pipe in code under a table": (
        "# Methods\n\nAlpha was set in advance.\n\n| a | b |\n|---|---|\n| 1 | 2 |\n"
        "Results `a|b`\n===\n\nThe excess was significant (p < 0.001).\n"
    ),
    # A lone `##` is an empty heading, and "Results" under it a paragraph. The page shows
    # "Results" over the number; `main` read it as the heading's title.
    "a lone hash over a results line": (
        "# Methods\n\nAlpha was set in advance.\n\n##\nResults\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # Found by the sixth review. The walk ends a tag at its first `>`, and pandoc does not:
    # with a quote left open there is no tag, and the heading reads `<div class="a>Methods`.
    # Only a line starting with the tag was marked as text, not one after a comment.
    "a tag after a comment over an underline": (
        '# Results\n\n<!-- c --><div class="a>Methods\n===\n\n'
        "The excess was significant (p < 0.001).\n"
    ),
    "a tag after a comment inside a code span": (
        "# Results\n\nUse the `x\n<!-- c --><div>Methods\n===\n`\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a tag after a comment under a table": (
        '# Results\n\n| a | b |\n|---|---|\n| 1 | 2 |\n<!-- c --><div>Methods {k="$ | $"}\n'
        "===\n\nThe excess was significant (p < 0.001).\n"
    ),
    # A Results title with raw HTML or TeX in it, which the page does not show, did not read
    # as Results; a seven-hash Methods under it, which `main` never read, opened Methods.
    "a seven-hash methods under a struck-through results": (
        "# <del>Results</del>\n\n####### Methods\n\nThe excess was significant (p < 0.001).\n"
    ),
    "a seven-hash methods with attributes under a results anchor": (
        '# Results <a id="r"></a>\n\n####### Methods {-}\n\n'
        "The excess was significant (p < 0.001).\n"
    ),
    "a seven-hash methods under a results label": (
        "# Results \\label{sec:results}\n\n####### Methods\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # A Results heading after a comment is marked as text, so it was never on the printed
    # chain; a `#` line pandoc prints as text then took it off the other one.
    "a results after a comment ended by a line printed as text": (
        "# Methods\n\n<!-- x --># Results\n\nProse ran on\n# Outcomes\n\n# Results\n-\n\n"
        "Statistical analysis\n-\n\nThe excess was significant (p < 0.001).\n"
    ),
    # Found by the seventh review. An unclosed comment in an attribute block took the `}`
    # with it when raw markup was stripped first, and the title no longer read as Results.
    "a comment in a results attribute block": (
        "# Methods\n\n-----  -----\na      b\n-----  -----\n"
        '# Results {title="<!--"}\n\n## Statistical analysis\n\n'
        "The excess was significant (p < 0.001).\n"
    ),
    # Seven hashes, which `main` never read, opened Methods wherever the walk wrongly placed
    # one, or under a Results title the gates do not read.
    "seven hashes under a stray closing tag": (
        "# Outcomes\n\nText\n</script>\n####### Methods\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "seven hashes under a results span": (
        "# [Results]{.underline}\n\n####### Methods\n\nThe excess was significant (p < 0.001).\n"
    ),
    # A `#` line over a rule is a setext heading, "# Outcomes", at level 2, and it nested under
    # a Methods the walk placed in error. `main` read it at level 1, which closes them.
    "a hash line over a rule under a misplaced methods": (
        "# Results\n\nText\n</script>\n# Methods\n# Outcomes\n---\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a hash line over a rule in a dash table": (
        "# Results\n\n-----  -----\nText\n---\n# Methods\n# Outcomes\n---\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # Found by the eighth review. The level-1 reading of a `# X` line over a rule is `main`'s,
    # and `main` read only a `#` at the margin: an indented ` # Y`, or one after a comment,
    # took level 1 too, and the printed chain lost the Results it still held.
    "an indented hash line over a rule after a comment-led one": (
        "# Results\n\nText\n<!-- c --># Outcomes\n\n # Y\n-\n\n## Sensitivity analyses\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "an indented hash line over a rule after an unclosed quote": (
        '# Results\n\n<div class="a># Outcomes\n\n # Y\n-\n\n## Statistical analysis\n\n'
        "The excess was significant (p < 0.001).\n"
    ),
    "a comment-led hash line over a rule after a quote over an underline": (
        "# Results\n\nText\n> Outcomes\n===\n\n<!-- c --># Y\n-\n\n## Methods\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # A setext title `main` refused, starting `>` or `|`, opened a section wherever the walk
    # placed one wrongly, under a stray `</script>`.
    "a quote title over an underline under a stray closing tag": (
        "# Results\n\nText\n</script>\n> Outcomes\n===\n\n## Methods\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a pipe title over an underline under a stray closing tag": (
        "# Results\n\nText\n</script>\n| Outcomes\n===\n\n## Methods\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # An empty `###` in a paragraph, which `main` read with the line below it as its title.
    "an empty heading in a paragraph over a results line": (
        "# Res<!-- -->ults\n\n## Statistical analysis\n\nText\n###\nResults\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # Found by the ninth review. A setext title `main` read as an ATX heading kept its place
    # on the printed chain, but at pandoc's level rather than at `main`'s hash count.
    "two hashes over an underline under a stray closing tag": (
        "# Results\n\nText\n</script>\n## Outcomes\n===\n\n## Statistical analysis\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "three hashes over a rule under a level-two results": (
        "## Results\n\nText\n</script>\n### Y\n---\n\n### Sensitivity analyses\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # `main`'s `#{1,6}\s+` took a no-break space after the hash too.
    "a hash and a no-break space over a rule": (
        "## Results\n\nText\n</script>\n#" + chr(0xA0) + "Results\n-\nMethods\n---\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a hash and an em space over a rule": (
        "## Results\n\nText\n</script>\n#" + chr(0x2003) + "Results\n-\nMethods\n---\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    # Found by the tenth review. The same title, when the walk marks it as text and it does
    # not say Results, stays off the printed chain, and on the other it took the underline's
    # level: it nested under a wrongly placed Methods that `main`'s level 1 closed.
    "a hash and a no-break space over a rule under a misplaced methods": (
        "# Results\n\nText\n</script>\n# Methods\n\n#" + chr(0xA0) + "Outcomes\n---\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
    "a hash line over a rule in a misplaced methods paragraph": (
        "# Results\n\nText\n</script>\n# Methods\nText\n# Y\n-\n\n"
        "The excess was significant (p < 0.001).\n"
    ),
}


@pytest.mark.parametrize("name", sorted(RESULTS_READ_AS_METHODS))
def test_results_are_not_read_as_methods(project: Path, name: str) -> None:
    """Found by the fourth review of #38. Each let a Results p-value pass as the alpha."""
    path = main_md(project)
    tail = RESULTS_READ_AS_METHODS[name]
    path.write_text(path.read_text(encoding="utf-8") + "\n\n" + tail, encoding="utf-8")
    report = gate_report(project)
    assert any(
        f.code == "unclassified-number" and "'0.001'" in f.message for f in report.failures
    )


def _reported(project: Path, sections: list[str]) -> set[str]:
    """The numbers G2 reports as bound to nothing once `sections` end the manuscript."""
    path = main_md(project)
    path.write_text(path.read_text(encoding="utf-8") + "\n\n" + "".join(sections), "utf-8")
    return {
        f.message.split("'")[1]
        for f in gate_report(project).failures
        if f.code == "unclassified-number"
    }


def _reported_lines(project: Path, sections: list[str]) -> set[int]:
    """The lines on which G2 reports a number as bound to nothing once `sections` end the
    manuscript."""
    path = main_md(project)
    path.write_text(path.read_text(encoding="utf-8") + "\n\n" + "".join(sections), "utf-8")
    return {f.line for f in gate_report(project).failures if f.code == "unclassified-number"}


# Where pandoc prints a heading-shaped line as text: in a paragraph, a list item, a
# quotation, a `<pre>` and a LaTeX environment, a `#` line and an underlined title.
_AS_TEXT = {
    "paragraph": "The rule counted\n{line}\n",
    "list item": "- The rule counted\n{line}\n",
    "quotation": "> The rule counted\n{line}\n",
    "pre": "<pre>\n{line}\n</pre>\n",
    "latex": "\\begin{{center}}\n{line}\n\\end{{center}}\n",
}


def test_a_line_shaped_like_a_heading_ends_a_section_for_g2_and_opens_no_methods(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A line shaped like a heading always ends a
    section for G2"): each heading-shaped line pandoc prints as text ends the Methods above
    it, so the threshold after it is reported, and one titled Methods under the Results
    opens no Methods rules. Not such lines, the other side: a `\\#` that starts a wrapped
    line, and the last row of a table the walk reads, or a table placeholder, over a rule."""
    sections: list[str] = []
    reported: list[str] = []
    passed: list[str] = []

    def section(heading: str, lines: str, case: str) -> str:
        return f"# {heading}\n\nText.\n\n{lines}\nThe threshold ({case}) was p < 0.05.\n\n"

    for name in sorted(_AS_TEXT):
        for kind, line in [("hash", "# {title}"), ("underlined", "{title}\n========")]:
            for heading, title, what in [("Methods", "Outcomes", "ends"),
                                         ("Results", "Methods", "opens")]:  # fmt: skip
                case = f"{what} {kind} {name}"
                lines = _AS_TEXT[name].format(line=line.format(title=title))
                sections.append(section(heading, lines, case))
                reported.append(case)
    # A Methods paragraph wrapped at "# of reports" reports the threshold after it.
    sections.append(section("Methods", "The rule counted the\n# of reports named.\n", "wrap"))
    reported.append("wrap")
    for case, lines in [
        ("escaped", "The rule counted the\n\\# of reports named.\n"),
        ("table", "| a | b |\n|---|---|\n| 1 | 2 |\n---\n"),
        ("placeholder", "{{table.two_by_two}}\n---\n"),
    ]:
        sections.append(section("Methods", lines, case))
        passed.append(case)
    found = _reported_lines(project, sections)
    written = main_md(project).read_text(encoding="utf-8").split("\n")

    def line_of(case: str) -> int:
        return next(i for i, text in enumerate(written, 1) if f"({case})" in text)

    assert [case for case in reported if line_of(case) not in found] == []
    assert [case for case in passed if line_of(case) in found] == []


@pytest.mark.skipif(
    __import__("shutil").which("pandoc") is None, reason="pandoc is not installed"
)
@pytest.mark.parametrize(
    ("fence", "printed"),
    [("~~~", True), (" " + "`" * 3, True), ("`" * 3, False)],
    ids=["tilde", "indented", "backtick at the margin"],
)
def test_a_fence_under_a_line_of_prose_is_code_to_the_gates(
    project: Path, fence: str, printed: bool
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A fence directly under a line of prose is code
    to the gates and prose to pandoc"): a tilde fence, or one indented a space, straight
    under a line of prose is printed as text, and the `# Methods` past the blank line is a
    heading, where the gates blank the whole span: the number in it goes unread by G2 and
    the heading is missed. A backtick fence at the margin, the other side, is code to both."""
    from test_pandoc_agreement import pandoc_headings

    from manuscript_guard.text.sections import headings

    snippet = (
        f"# Results\n\nWe saw it.\n{fence}\nThe ROR was 9.99.\n\n# Methods\n\n"
        f"The threshold was p < 0.05.\n{fence}\n\n"
    )
    assert headings(snippet) == ["Results"]
    assert pandoc_headings(snippet) == (["Results", "Methods"] if printed else ["Results"])
    # The other side, the same lines with no fence: G2 reads the number.
    bare = snippet.replace(f"{fence}\n", "").replace("9.99", "9.98")
    found = _reported(project, [snippet, bare])
    assert "9.98" in found
    assert not {"9.99", "0.05"} & found


@pytest.mark.skipif(
    __import__("shutil").which("pandoc") is None, reason="pandoc is not installed"
)
@pytest.mark.parametrize("gap", ["", "\n"], ids=["directly under", "apart"])
def test_a_heading_directly_under_a_figure_line_is_printed_as_text(
    project: Path, gap: str
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A heading directly under a `{{figure.x}}` line is
    printed as text"): the build writes an image there, the heading on the next line does
    not interrupt the paragraph, and the gates read it as text too, so the threshold under
    it is reported as the Results'. With a blank line between, it is a heading to both."""
    from test_pandoc_agreement import pandoc_headings

    from manuscript_guard.build import assemble

    path = main_md(project)
    text = path.read_text(encoding="utf-8")
    anchor = "{{figure.forest}}\n\n# Discussion"
    assert text.count(anchor) == 1
    snippet = f"{{{{figure.forest}}}}\n{gap}# Methods\n\nThe threshold was p < 0.05.\n\n"
    path.write_text(text.replace(anchor, snippet + "# Discussion"), encoding="utf-8")
    projekt, _ = load_project(project)
    namespace, results, _literature, _report = load_namespace(projekt)
    assembled, _assembly = assemble(projekt, namespace, results)
    built = next(item.text for item in assembled if item.path.name == "main.md")
    assert pandoc_headings(built).count("Methods") == (2 if gap else 1)
    reported = any(
        f.code == "unclassified-number" and "'0.05'" in f.message
        for f in gate_report(project).failures
    )
    assert reported is not bool(gap)


@pytest.mark.parametrize(
    ("title", "results"),
    [("## **Results**", True), ("- Results\n---", True), ("# Results\n---", True),
     ("# Results", True), ("# Results and discussion", False)],
)  # fmt: skip
def test_a_section_is_results_only_by_its_title(project: Path, title: str, results: bool) -> None:
    """A known gap (DESIGN.md, Known gaps, "A section is Results only by its title."): a
    Results heading in bold, as a list item over a rule or hashed over a rule ends the
    Methods, and a P under a "Sensitivity analyses" below it is reported; under "Results
    and discussion" that subsection keeps the Methods rules, and the P passes as a
    threshold. The 2026-11-09 triage planned a fix (F18), which will change this test."""
    path = main_md(project)
    path.write_text(path.read_text(encoding="utf-8") + f"\n\n# Methods\n\nAlpha was set in "
                    f"advance.\n\n{title}\n\nText.\n\n### Sensitivity analyses\n\nThe excess "
                    "was significant (p < 0.001).\n", encoding="utf-8")  # fmt: skip
    found = [f for f in gate_report(project).failures
             if f.code == "unclassified-number" and "'0.001'" in f.message]  # fmt: skip
