def test_a_share_its_counts_do_not_give_in_the_results_is_a_number_that_does_not_fit(
    tmp_path: Path,
) -> None:
    """Basile, 2026-11-13, after #664: "12 of 40 patients (30%)" in the Results says nothing;
    changed to 50%, it is listed once, by its heading, with the numbers that do not fit the
    ones beside them. The same share in a table is said once, as the table's; and the
    Abstract's once, as the Abstract's."""
    from manuscript_guard.audit import audit

    paper = tmp_path / "paper.md"

    def said(abstract: str, results: str) -> list[tuple[int, str]]:
        paper.write_text(f"# Paper\n\n## Abstract\n\n{abstract}\n\n## Methods\n\nWe asked "
                         f"40.\n\n## Results\n\n{results}\n", encoding="utf-8")  # fmt: skip
        return [(d.line, d.message) for d in audit([paper], None).disagreements]

    assert said("We asked them.", "Then 12 of 40 patients (30%) had it.") == []
    assert said("We asked them.", "Then 12 of 40 patients (50%) had it.") == [
        (13, "in Results, n (%) 12 of 40 patients (50%): 12 of 40 is 30.0%, not 50; 50% is "
             "12 of 24")]  # fmt: skip
    table = "| Group | Value |\n|---|---|\n| A | 12/40 (50.0%) |"
    assert [line for line, _said in said("We asked them.", table)] == [15]
    assert [message for _line, message in said("Then 12 of 40 (50%) had it.", "It was so.")
            ] == ["in the Abstract, n (%) 12 of 40 (50%): 12 of 40 is 30.0%, not 50; 50% is "
                  "12 of 24"]  # fmt: skip


def test_a_p_smaller_than_its_statistic_gives_is_found_in_a_paper_that_adjusts(
    tmp_path: Path,
) -> None:
    """Decision 31: a paper that says its P values are Holm-adjusted has a larger P asked
    about, since an adjustment makes a P larger; a P smaller than its t gives is wrong under
    any adjustment and is still a number that does not fit."""
    from manuscript_guard.audit import audit

    paper = tmp_path / "paper.md"
    paper.write_text("# Methods\n\nAll P values were Holm-adjusted.\n\n# Results\n\nThe arms "
                     "differed, t(23) = 2.71, P = 0.002.\n", encoding="utf-8")  # fmt: skip
    report = audit([paper], None)
    assert report.arithmetic_asked == []
    (found,) = report.disagreements
    assert found.message.endswith("and the text says P = 0.002"), found


def test_g8_warns_of_a_p_smaller_than_its_statistic_in_a_manuscript_that_adjusts(
    project: Path,
) -> None:
    """The same in `check`: G8 warns, and asks nothing."""
    main = main_md(project)
    main.write_text(main.read_text(encoding="utf-8") + "\nAll P values were Holm-adjusted. "
                    "The arms differed, t(23) = 2.71, p = .002.\n", encoding="utf-8")  # fmt: skip
    found = [f for f in _recomputed(project).findings if "t(23) = 2.71" in (f.context or "")]
    assert [(f.code, f.severity, f.question) for f in found] == [("p-inconsistent", "warn",
                                                                  False)]  # fmt: skip


