def test_a_word_paper_s_share_off_its_counts_is_said_once_and_its_table_s_as_a_table_s(
    tmp_path: Path,
) -> None:
    """Round 1 of #668: in a .docx, a share off its counts in the body and in a footnote is
    said once each, with no heading in its words, since its place names its section, and a
    table cell's once, as the table reader says it."""
    import zipfile

    from manuscript_guard.audit import audit

    namespace = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'

    def para(text: str, style: str = "") -> str:
        styled = f'<w:pPr><w:pStyle w:val="{style}"/></w:pPr>' if style else ""
        return f"<w:p>{styled}<w:r><w:t>{text}</w:t></w:r></w:p>"

    def cell(text: str) -> str:
        return f"<w:tc>{para(text)}</w:tc>"

    table = (f"<w:tbl><w:tr>{cell('Group')}{cell('Value')}</w:tr>"
             f"<w:tr>{cell('A')}{cell('12/40 (50.0%)')}</w:tr></w:tbl>")  # fmt: skip
    body = (para("Methods", "Heading1") + para("We asked 40.")
            + para("Results", "Heading1")
            + '<w:p><w:r><w:t>Then 12 of 40 patients (50%) had it.</w:t></w:r><w:r>'
              '<w:footnoteReference w:id="1"/></w:r></w:p>' + table)
    notes = (f"<w:footnotes {namespace}><w:footnote w:id=\"1\"><w:p><w:r><w:t>Of them, 5 of "
             "10 (60%) were.</w:t></w:r></w:p></w:footnote></w:footnotes>")
    path = tmp_path / "paper.docx"
    with zipfile.ZipFile(path, "w") as archive:
        archive.writestr("word/document.xml", f"<w:document {namespace}><w:body>{body}"
                                              "</w:body></w:document>")  # fmt: skip
        archive.writestr("word/footnotes.xml", notes)
    said = sorted(d.message for d in audit([path], None).disagreements)
    assert said == ["n (%) 12 of 40 patients (50%): 12 of 40 is 30.0%, not 50; 50% is 12 of 24",
                    "n (%) 12/40 (50.0%): 12 of 40 is 30.00%, not 50.0; 50.0% is 12 of 24",
                    "n (%) 5 of 10 (60%): 5 of 10 is 50.0%, not 60"], said


def test_an_abstract_number_changed_under_a_section_of_its_own_name_is_not_found(
    tmp_path: Path,
) -> None:
    """A number of the Abstract reported under "Participants" is found there, which it was
    not before (the real-paper corpus, 2026-11-11); changed there, it is not found, and
    neither is one only the Discussion gives, which is asked about (decision 27, part B)."""
    from manuscript_guard.audit import audit

    paper = tmp_path / "paper.md"

    def not_found(participants: str, discussion: str) -> list[str]:
        paper.write_text("# Paper\n\n## Abstract\n\nWe enrolled 1,284 adults.\n\n"
                         f"## Participants\n\n{participants}\n\n## Results\n\nIt was so.\n\n"
                         f"## Discussion\n\n{discussion}\n", encoding="utf-8")  # fmt: skip
        read = audit([paper], None).abstract
        return [c.text for c in (*read.not_found, *(c for c, *_rest in read.only_in))]

    assert not_found("We enrolled 1,284 adults.", "It was so.") == []
    assert not_found("We enrolled 1,248 adults.", "It was so.") == ["1,284"]
    assert not_found("We enrolled them.", "We enrolled 1,284 adults.") == ["1,284"]


def test_an_abstract_number_changed_in_a_table_after_the_references_is_not_found(
    tmp_path: Path,
) -> None:
    """A number of the Abstract in a table or a caption typed after the reference list, with
    no heading after it, is found there, which it was not before (pdf-psych-B3 of the
    real-paper corpus; Basile, 2026-11-15); changed there, it is not found, in Markdown and
    in a .docx, and in a PDF, whose table is lines of text."""
    import shutil

    from test_abstract_past_the_list import _docx_body, _markdown, _pdf_lines
    from test_audit import make_docx, para
    from test_audit_pdf import write

    from manuscript_guard.audit import audit

    def not_found(paper: Path) -> list[str]:
        return [c.text for c in audit([paper], None).abstract.not_found]

    for row, wanted in (("Women 194 33.2", []), ("Women 194 33.9", ["33.2%"])):
        markdown = tmp_path / "paper.md"
        markdown.write_text(_markdown(f"Table 1. Baseline\n\n{row}\n"), encoding="utf-8")
        assert not_found(markdown) == wanted, row
        docx = make_docx(tmp_path / "paper.docx", _docx_body(para("Table 1. Baseline")
                                                             + para(row)))  # fmt: skip
        assert not_found(docx) == wanted, row
        if shutil.which("pdftotext"):
            pdf = write(tmp_path / "paper.pdf", _pdf_lines(["Table 1. Baseline", row]),
                        per_column=40)  # fmt: skip
            assert not_found(pdf) == wanted, row


def test_an_abstract_number_that_is_an_entry_s_volume_after_a_caption_is_not_found(
    tmp_path: Path,
) -> None:
    """Round 1 of #692: with a caption between a list's entries, the entry after it stood past
    the list and its volume, "393", was the Abstract's "393 patients" found. It resumes the
    list now, in Markdown and in a .docx; a row with no entry's shape there is still read."""
    from test_abstract_past_the_list import _RESUMED, _docx_body, _markdown, _said_393
    from test_audit import make_docx, para

    from manuscript_guard.audit import audit

    def not_found(paper: Path) -> list[str]:
        return [c.text for c in audit([paper], None).abstract.not_found]

    for after, wanted in ((_RESUMED, ["393", "33.2%"]), ("Women 393 12", ["33.2%"])):
        markdown = tmp_path / "paper.md"
        markdown.write_text(_said_393(_markdown(f"Table 1. Baseline\n\n{after}\n")),
                            encoding="utf-8")  # fmt: skip
        assert not_found(markdown) == wanted, after
        body = _said_393(_docx_body(para("Table 1. Baseline") + para(after)))
        assert not_found(make_docx(tmp_path / "paper.docx", body)) == wanted, after


def test_an_abstract_number_only_a_footnote_gives_is_not_found(tmp_path: Path) -> None:
    """Round 1 of #641: a .docx's footnotes are read after its body, under its last heading,
    and searched there, so the Abstract's "45 patients" beside the Results' 54 counted as
    found in a footnote's citation, "Lancet 2019;12:45-67". A note is never where the paper
    reports."""
    import zipfile

    from manuscript_guard.audit import audit

    namespace = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'

    def para(text: str, style: str = "") -> str:
        styled = f'<w:pPr><w:pStyle w:val="{style}"/></w:pPr>' if style else ""
        return f"<w:p>{styled}<w:r><w:t>{text}</w:t></w:r></w:p>"

    body = (para("Abstract", "Heading1") + para("We followed 45 patients.")
            + para("Methods", "Heading1") + para("We read the records.")
            + para("Results", "Heading1")
            + '<w:p><w:r><w:t>We followed 54 patients.</w:t></w:r><w:r>'
              '<w:footnoteReference w:id="1"/></w:r></w:p>'
            + para("References", "Heading1") + para("Doe J. A title. BMJ. 2020;1:2."))
    notes = (f"<w:footnotes {namespace}><w:footnote w:id=\"1\"><w:p><w:r><w:t>Smith J. "
             "Lancet 2019;12:45-67.</w:t></w:r></w:p></w:footnote></w:footnotes>")
    path = tmp_path / "paper.docx"
    with zipfile.ZipFile(path, "w") as archive:
        archive.writestr("word/document.xml", f"<w:document {namespace}><w:body>{body}"
                                              "</w:body></w:document>")  # fmt: skip
        archive.writestr("word/footnotes.xml", notes)
    read = audit([path], None).abstract
    assert read.compared and [c.text for c in read.not_found] == ["45"]


