def _signed_package(root: Path) -> Path:
    """A package of one script and its result, its MANIFEST.yaml and SHA256SUMS written as
    `package` writes them, over whatever the folder holds now."""
    from manuscript_guard.emit import source_digest

    def sha(path: Path) -> str:
        return hashlib.sha256(path.read_bytes()).hexdigest()

    script, result = root / "analysis" / "count.py", root / "results" / "count.json"
    if not script.exists():
        script.parent.mkdir(parents=True)
        script.write_text("print(412)\n", encoding="utf-8", newline="\n")
        result.parent.mkdir()
        result.write_text(json.dumps({"provenance": {
            "generated_by": "analysis/count.py", "generated_at": "2026-01-01",
            "generated_by_sha256": source_digest(script)}, "values": {"n": {"value": 412}}}),
            encoding="utf-8")  # fmt: skip
        write_digest(result)
    for old in ("MANIFEST.yaml", "SHA256SUMS"):
        (root / old).unlink(missing_ok=True)
    files = sorted(p for p in root.rglob("*") if p.is_file())
    entries = [{"file": p.relative_to(root).as_posix(), "bytes": p.stat().st_size,
                "sha256": sha(p)} for p in files]  # fmt: skip
    manifest = root / "MANIFEST.yaml"
    manifest.write_text(yaml.safe_dump({"schema": "manuscript-guard/package/1", "files": entries,
                                        "withheld": []}), encoding="utf-8")  # fmt: skip
    (root / "SHA256SUMS").write_text("".join(
        f"{digest}  {name}\n" for name, digest in sorted(
            [(e["file"], e["sha256"]) for e in entries] + [("MANIFEST.yaml", sha(manifest))])),
        encoding="utf-8")  # fmt: skip
    return root


def test_a_packaged_file_changed_since_its_manifest_fails_an_audit(tmp_path: Path) -> None:
    """`audit --package`: a file whose bytes are not those MANIFEST.yaml lists is counted by
    --strict (decision 8 of the editor and referee layer)."""
    from manuscript_guard.cli import main

    root = _signed_package(tmp_path / "pkg")
    assert main(["audit", "--package", str(root), "--strict"]) == 0
    (root / "analysis" / "count.py").write_text("print(421)\n", encoding="utf-8", newline="\n")
    assert main(["audit", "--package", str(root), "--strict"]) == 1


def test_a_packaged_result_not_written_by_its_script_fails_an_audit(tmp_path: Path) -> None:
    """`audit --package`: the script changed and the manifest written again to match, which
    makes the package whole as written; the result's own record of its script's digest is
    what --strict counts then."""
    from manuscript_guard.cli import main

    root = _signed_package(tmp_path / "pkg")
    assert main(["audit", "--package", str(root), "--strict"]) == 0
    (root / "analysis" / "count.py").write_text("print(421)\n", encoding="utf-8", newline="\n")
    _signed_package(root)
    assert main(["audit", "--package", str(root), "--strict"]) == 1


def test_set_moves_the_stage_and_not_the_lines_that_look_like_it(project: Path) -> None:
    """`set stage` writes the setting at the top level of paper.yaml, and the check then
    holds the paper to it: a small count fails from internal review. A regular expression
    for `stage:` would have hit the commented example above the setting, or a citekey
    named `stage` under `lookup: not_indexed:`, and left the stage where it was."""
    from manuscript_guard.cli import _run_gates

    paper = project / "paper.yaml"
    text = paper.read_text(encoding="utf-8").replace(
        "  not_indexed:\n",
        "  not_indexed:\n    # stage: where a careless edit would write\n"
        "    stage: a citekey named like the setting\n",
    )
    text += "\ncustodian:\n  minimum_cell_count: 5\n# stage: internal-review\nstage: drafting\n"
    paper.write_bytes(text.encode("utf-8"))
    _value_has(project, "case.n_serious", value=3, display="3", unit=None, label=False)
    report, _project, chosen, _deferred = _run_gates(project)
    assert chosen == "drafting" and "count-below-minimum" not in codes(report)

    assert _run_cli(["set", "stage", "internal-review", "--path", str(project)]) == 0
    report, _project, chosen, _deferred = _run_gates(project)
    assert chosen == "internal-review" and "count-below-minimum" in codes(report)
    after = paper.read_bytes().decode("utf-8")
    assert after == text.replace("\nstage: drafting\n", "\nstage: internal-review\n")
    assert yaml.safe_load(after)["lookup"]["not_indexed"]["stage"].startswith("a citekey")


@pytest.mark.parametrize("fields", [
    {"value": 3.0, "display": "3"},  # a count emitted as a float
    {"value": 3, "display": "3", "unit": "patients"},  # a count given a unit of people
])  # fmt: skip
def test_what_the_count_reading_gets_wrong_is_pinned(project: Path, fields: dict) -> None:
    """A Known gap, as DESIGN.md writes it (round 1 of #275): a small count the emitter
    recorded as a float, or with a unit naming people, is not taken for a count."""
    _custodian(project, 5)
    _value_has(project, "case.n_serious", **fields)
    assert _small(project) == []


@pytest.mark.parametrize(("display", "said"), [
    ("<2", True), ("< 3", True), ("\N{LESS-THAN OR EQUAL TO}3", True), ("<=2", True),
    ("<5", False), ("\N{LESS-THAN OR EQUAL TO}4", False), ("<=4", False), ("<10", False),
    ("<1", False),  # nought, which is no small cell
    # Round 1 of #341: a decimal or words after the bound, as the emitter takes a display.
    ("<2 patients", True), ("< 2 cases", True), ("<2.0", True), ("<5 patients", False),
    ("<4.5", False),
])  # fmt: skip
def test_a_count_held_back_by_a_bound_tighter_than_the_minimum_is_said(
    project: Path, display: str, said: bool
) -> None:
    """Round 3 of #275: a comparator display passed whatever its bound, so "<2" under a
    minimum of five, which says the count is one, printed no small count."""
    _custodian(project, 5)
    _value_has(project, "case.n_serious", value=1, display=display)
    found = _small(project)
    assert bool(found) is said, found


def _git(root: Path, *args: str) -> None:
    import subprocess

    subprocess.run(["git", "-c", "core.fsmonitor=false", *args], cwd=root, check=True,
                   capture_output=True, timeout=60)  # fmt: skip


@pytest.mark.skipif(shutil.which("git") is None, reason="git is not installed")
def test_an_input_declared_restricted_is_not_tracked_by_git(project: Path) -> None:
    """An input the custodian keeps may not be in the repository. Outside one, or
    ignored, it passes; added to git, G1 fails, from the first stage."""
    from manuscript_guard.cli import _run_gates
    from manuscript_guard.gates.custodian import check_restricted_inputs

    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    data = document["provenance"]["inputs"][0]["path"]
    document["provenance"]["inputs"][0]["restricted"] = True
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)

    def tracked() -> list[str]:
        loaded, _ = load_project(project)
        _, results, _, _ = load_namespace(loaded)
        found = check_restricted_inputs(loaded, results).findings
        return [f.message for f in found if f.severity == "fail"]

    assert tracked() == []  # no repository
    _git(project, "init", "-q")
    (project / ".gitignore").write_text(f"{data}\n", encoding="utf-8")
    _git(project, "add", ".")
    assert tracked() == []
    _git(project, "add", "-f", data)
    assert tracked() == [f"{data} is declared restricted, and git tracks it"]
    report, _project, _chosen, _deferred = _run_gates(project, stage="design")
    assert "restricted-input-tracked" in codes(report)


@pytest.mark.skipif(shutil.which("git") is None, reason="git is not installed")
def test_a_restricted_input_is_found_in_git_by_its_own_name(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Round 1 of #275: the path was a pattern, so a tracked "data1.csv" stood for an
    untracked "data[1].csv"; a path outside the work tree, or git in another language,
    was "could not say"; and a name in another case was missed where git ignores case."""
    from manuscript_guard.gates import custodian

    _git(tmp_path, "init", "-q")
    _git(tmp_path, "config", "core.ignorecase", "false")
    for name in ("data1.csv", "data[1].csv", "Kept.csv"):
        (tmp_path / name).write_text("a\n", encoding="utf-8")
    _git(tmp_path, "add", "data1.csv", "Kept.csv")
    assert custodian._tracked(tmp_path, "data1.csv") is True
    assert custodian._tracked(tmp_path, "data[1].csv") is False
    assert custodian._tracked(tmp_path, "../outside.csv") is False
    assert custodian._tracked(tmp_path, "kept.csv") is False
    _git(tmp_path, "config", "core.ignorecase", "true")
    assert custodian._tracked(tmp_path, "kept.csv") is True
    # A name in another script or with an accent is read as UTF-8 whatever the locale's
    # code page: under cp932 or cp1252 the unquoted name raised (round 1 of #341).
    for name in ("\N{KATAKANA LETTER DE}\N{KATAKANA LETTER SMALL TU}\N{KATAKANA LETTER TA}.csv",
                 "\N{LATIN CAPITAL LETTER A WITH ACUTE}baco.csv"):  # fmt: skip
        (tmp_path / name).write_text("a\n", encoding="utf-8")
        _git(tmp_path, "add", name)
        assert custodian._tracked(tmp_path, name) is True, name
    # Asked in English, whatever the user's language, since its words are read.
    seen: list[dict] = []
    run = custodian.subprocess.run

    def recorded(*args, **kwargs):
        seen.append(kwargs["env"])
        return run(*args, **kwargs)

    monkeypatch.setenv("LANGUAGE", "fr")
    monkeypatch.setattr(custodian.subprocess, "run", recorded)
    assert custodian._tracked(tmp_path, "data[1].csv") is False
    assert seen and all(env["LC_ALL"] == "C" and env["LANGUAGE"] == "C" for env in seen)


@pytest.mark.skipif(shutil.which("git") is None, reason="git is not installed")
def test_a_restricted_input_copied_elsewhere_or_removed_from_git_is_not_seen(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A small count is found where it is bound, by its
    value"): a restricted input that git ignores but that a person copies elsewhere is not
    seen, and one that was committed and then removed stays in the history, which the check
    does not read: G1 says nothing of either."""
    import subprocess

    from manuscript_guard.cli import _run_gates
    from manuscript_guard.gates.custodian import check_restricted_inputs

    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    # The list of event terms, which no other finding of G1 names (the simulated reports are
    # named by the demonstration's note that its results come from synthetic data).
    data = "data/event_terms.txt"
    for record in document["provenance"]["inputs"]:
        if record["path"] == data:
            record["restricted"] = True
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)

    def said() -> list[tuple[str, str]]:
        loaded, _ = load_project(project)
        _, results, _, _ = load_namespace(loaded)
        return [(f.code, f.message) for f in check_restricted_inputs(loaded, results).findings]

    def gates() -> list:
        report, _project, _chosen, _deferred = _run_gates(project, stage="design")
        return list(report.findings)

    _git(project, "init", "-q")
    _git(project, "config", "user.email", "a@example.org")
    _git(project, "config", "user.name", "A")
    _git(project, "add", "-A")
    _git(project, "commit", "-q", "-m", "with the data")
    # The other side: committed and still tracked, it is said.
    assert said() == [("restricted-input-tracked",
                       f"{data} is declared restricted, and git tracks it")]  # fmt: skip
    _git(project, "rm", "-q", "--cached", data)
    ignored = project / ".gitignore"
    kept = ignored.read_bytes() if ignored.is_file() else b""
    ignored.write_bytes(kept + f"\n{data}\n".encode())
    # A copy under another name, committed, and one outside the project.
    copy = project / "notes" / "copy-of-the-data.csv"
    copy.parent.mkdir(exist_ok=True)
    copy.write_bytes((project / data).read_bytes())
    (project.parent / "copy-of-the-data.csv").write_bytes((project / data).read_bytes())
    _git(project, "add", "-A")
    _git(project, "commit", "-q", "-m", "the data taken out")
    shown = subprocess.run(["git", "-c", "core.fsmonitor=false", "show", f"HEAD~1:{data}"],
                           cwd=project, capture_output=True, timeout=60)  # fmt: skip
    assert shown.returncode == 0 and shown.stdout, "the history still holds the data"
    assert said() == []
    found = gates()
    assert "restricted-input-tracked" not in {f.code for f in found}
    names = (Path(data).name, "copy-of-the-data.csv")
    assert [(f.code, f.message) for f in found if f.gate == "G1" and any(
        name in f"{f.message} {f.path}" for name in names)] == []  # fmt: skip


def test_both_emitters_record_an_input_declared_restricted(tmp_path: Path) -> None:
    """`add_input(path, restricted=True)` is written into the provenance, and an
    input not so declared carries no such field."""
    from manuscript_guard.emit import Emitter

    root = tmp_path / "paper"
    (root / "analysis").mkdir(parents=True)
    (root / "data").mkdir()
    (root / "paper.yaml").write_text("schema: manuscript-guard/paper/1\ntitle: T\n", "utf-8")
    for name in ("kept.csv", "open.csv"):
        (root / "data" / name).write_text("a,b\n1,2\n", encoding="utf-8")
    script = root / "analysis" / "a.py"
    script.write_text("# reads the data\n", encoding="utf-8")
    em = Emitter(script, root=root)
    em.add_input("data/kept.csv", restricted=True)
    em.add_input("data/open.csv")
    em.value("n", 412)
    inputs = json.loads(em.write().read_text(encoding="utf-8"))["provenance"]["inputs"]
    assert [(i["path"], i.get("restricted")) for i in inputs] == [
        ("data/kept.csv", True),
        ("data/open.csv", None),
    ]


# ------------------------------------------------------------------ results from the vault


def _from_the_vault(project: Path, tmp_path: Path, monkeypatch) -> tuple[Path, Path]:
    """The example with a vault registered beside it, and a fragment written by a script that
    read it with MANUSCRIPT_GUARD_VAULT set: the vault's folder, and the fragment."""
    from manuscript_guard.cli import main
    from manuscript_guard.emit import Emitter

    with (project / "paper.yaml").open("a", encoding="utf-8") as file:
        file.write("\ncustodian:\n  minimum_cell_count: 5\n")
    held = tmp_path / "held"
    held.mkdir()
    (held / "cohort.csv").write_text("id,age\n" + "".join(f"P{n},{n}\n" for n in range(40)),
                                     encoding="utf-8")  # fmt: skip
    assert main(["vault", "init", str(held), "cohort.csv", "--as", "Ada",
                 "--path", str(project)]) == 0  # fmt: skip
    script = project / "analysis" / "09_vault.py"
    script.write_text("# reads the vault\n", encoding="utf-8")
    monkeypatch.setenv("MANUSCRIPT_GUARD_VAULT", str(held))
    monkeypatch.setenv("MANUSCRIPT_GUARD_VAULT_RUN", "20261104-120000")
    em = Emitter(script, root=project)
    em.vault_input("cohort.csv")
    em.value("vault.n_rows", 40, quoted=False)
    written = em.write()
    monkeypatch.delenv("MANUSCRIPT_GUARD_VAULT")
    return held, written


def _vault_said(root: Path, stage: str = "internal-review") -> list[tuple[str, str]]:
    from manuscript_guard.gates.vault import check_vault_results

    loaded, _ = load_project(root)
    _, results, _, _ = load_namespace(loaded)
    return [(f.code, f.severity) for f in check_vault_results(loaded, results, stage).findings]


def _released(project: Path, fragment: Path) -> None:
    """A release's record for the fragment as it stands, as `vault release` writes one."""
    from manuscript_guard.emit import sha256_of

    record = {"schema": "manuscript-guard/vault-release/1", "run": "20261104-120000",
              "released_by": "Ada", "role": "author", "released_at": "2026-11-04T12:00:00+00:00",
              "ran_at": "2026-11-04T12:00:00+00:00", "commit": None, "scripts": [],
              "ran": ["analysis/09_vault.py"], "inputs": [], "warnings": [],
              "files": [{"path": fragment.relative_to(project).as_posix(),
                         "sha256": sha256_of(fragment), "bytes": fragment.stat().st_size,
                         "kind": "results"}]}  # fmt: skip
    folder = project / "approvals" / "vault-releases"
    folder.mkdir(parents=True, exist_ok=True)
    (folder / "20261104-120000.json").write_text(json.dumps(record), encoding="utf-8")


def test_results_from_the_vault_copied_in_by_hand_are_caught(
    project: Path, tmp_path: Path, monkeypatch
) -> None:
    """A fragment written with the vault's variable set, or copied from its outbox, that no
    person released: a warning while the paper is written, a failure from internal review.
    Freshness says nothing of its input, which is outside the project."""
    _from_the_vault(project, tmp_path, monkeypatch)
    assert _vault_said(project, "drafting") == [("vault-result-unreleased", "warn")]
    assert _vault_said(project) == [("vault-result-unreleased", "fail")]
    assert "input-missing" not in codes(gate_report(project))
    _released(project, project / "results" / "09_vault.json")
    assert _vault_said(project) == []


def test_results_from_the_vault_edited_after_their_release_are_caught(
    project: Path, tmp_path: Path, monkeypatch
) -> None:
    _held, fragment = _from_the_vault(project, tmp_path, monkeypatch)
    _released(project, fragment)
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["values"]["vault.n_rows"]["value"] = 41
    fragment.write_text(json.dumps(document, indent=2) + "\n", encoding="utf-8")
    write_digest(fragment)
    assert _vault_said(project) == [("vault-result-unreleased", "fail")]


def test_results_from_an_extract_since_replaced_are_caught(
    project: Path, tmp_path: Path, monkeypatch
) -> None:
    from manuscript_guard.cli import main

    held, fragment = _from_the_vault(project, tmp_path, monkeypatch)
    _released(project, fragment)
    assert _vault_said(project) == []
    (held / "cohort.csv").write_text("id,age\nP1,1\n", encoding="utf-8")
    assert main(["vault", "init", "--refresh", "--as", "Ada", "--path", str(project)]) == 0
    assert _vault_said(project, "design") == [("vault-input-changed", "fail")]
    registry = project / "design" / "vault.yaml"
    registry.write_text(registry.read_text(encoding="utf-8").replace("label: cohort.csv",
                                                                     "label: other.csv"),
                        encoding="utf-8")  # fmt: skip
    assert _vault_said(project, "design") == [("vault-input-unregistered", "fail")]


def _synthetic_said(root: Path, *, submission: bool = False) -> list[tuple[str, str]]:
    from manuscript_guard.gates.synthetic import check_synthetic_inputs

    loaded, _ = load_project(root)
    _, results, _, _ = load_namespace(loaded)
    found = check_synthetic_inputs(loaded, results, submission=submission).findings
    return [(f.severity, f.message) for f in found]


def _not_a_demonstration(root: Path) -> None:
    paper = root / "paper.yaml"
    text = paper.read_text(encoding="utf-8")
    assert "\ndemonstration: true\n" in text
    paper.write_text(text.replace("\ndemonstration: true\n", "\n"), encoding="utf-8")


def test_a_result_quoted_from_synthetic_data_fails_at_submission(project: Path) -> None:
    """Item 42: a binding proved where a number came from, not that the data were real, and
    a number from a simulated run passed every gate. G1 says so of each result quoted from
    a run that read an input declared synthetic: a warning while the paper is written, a
    failure at submission. The example declares its simulated data, and is a
    demonstration."""
    from manuscript_guard.cli import _run_gates

    [(severity, message)] = _synthetic_said(project)
    assert severity == "info" and message.endswith("; the paper is a demonstration")
    assert "come from a run that read synthetic data (data/reports.csv)" in message
    _not_a_demonstration(project)
    [(severity, message)] = _synthetic_said(project)
    assert severity == "warn" and "results.case.n_cases" in message
    assert [s for s, _ in _synthetic_said(project, submission=True)] == ["fail"]
    report, _project, _chosen, _deferred = _run_gates(project, submission=True)
    assert "synthetic-input-quoted" in [f.code for f in report.failures]


def test_a_synthetic_run_nothing_quotes_is_not_said(project: Path) -> None:
    """Only what the manuscript quotes: a synthetic run whose results nothing binds has put
    no number into the paper."""
    _not_a_demonstration(project)
    main = project / "manuscript" / "main.md"
    text = main.read_text(encoding="utf-8")
    import re

    main.write_text(re.sub(r"\{\{\s*(?:results|table)\.[^}]*\}\}", "[elided]", text),
                    encoding="utf-8")  # fmt: skip
    for other in (project / "manuscript").rglob("*.md"):
        if other != main:
            other.write_text(re.sub(r"\{\{\s*(?:results|table)\.[^}]*\}\}", "[elided]",
                                    other.read_text(encoding="utf-8")), encoding="utf-8")
    # The figure's alternative text quotes results too, which the build prints.
    _alt(project, None)
    assert _synthetic_said(project) == []


def test_a_simulated_control_s_own_data_make_no_other_result_synthetic(project: Path) -> None:
    """Item 5: a simulated control in the script of the real results reads data of its own,
    declared synthetic; without its mark, every result of that script read as synthetic."""
    _not_a_demonstration(project)
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    for record in document["provenance"]["inputs"]:
        record.pop("synthetic", None)
    marked = {"path": "data/simulated_control.csv", "sha256": "0" * 64, "synthetic": True,
              "control": "control.shuffled"}  # fmt: skip
    document["provenance"]["inputs"].append(marked)
    (project / "data" / "simulated_control.csv").write_text("a\n", encoding="utf-8")
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    assert _synthetic_said(project) == []
    del marked["control"]
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    [(severity, message)] = _synthetic_said(project)
    assert severity == "warn" and "(data/simulated_control.csv)" in message


def test_a_synthetic_input_is_followed_to_the_results_the_text_binds_and_no_further(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A synthetic input is followed to the results the
    text binds, and no further"): a figure drawn from a synthetic run and placed with
    `figure.` is not named, nor a result of a second script that reads the first one's
    results file as its input; and an input that is synthetic and not declared so is found by
    nothing."""
    import re

    _not_a_demonstration(project)
    main = main_md(project)
    text = main.read_text(encoding="utf-8")
    elided = re.sub(r"\{\{\s*(?:results|table)\.[^}]*\}\}", "[elided]", text)
    assert "{{figure." in elided
    for other in (project / "manuscript").rglob("*.md"):
        other.write_text(re.sub(r"\{\{\s*(?:results|table)\.[^}]*\}\}", "[elided]",
                                other.read_text(encoding="utf-8")), encoding="utf-8")
    _alt(project, None)
    assert _synthetic_said(project) == []
    first = project / "results" / "01_disproportionality.json"
    document = json.loads(first.read_text(encoding="utf-8"))
    inputs = [{"path": "results/01_disproportionality.json", "sha256": "0" * 64}]
    second = {"schema": document["schema"], "values": {"second.n_pairs": {
        "value": 12, "display": "12"}}, "provenance": {**document["provenance"], "inputs": inputs}}
    path = project / "results" / "02_second.json"
    path.write_text(json.dumps(second, indent=2), encoding="utf-8")
    write_digest(path)
    main.write_text(main.read_text(encoding="utf-8") + "\n\nThere were "
                    "{{results.second.n_pairs}} pairs.\n", encoding="utf-8")  # fmt: skip
    loaded = load_namespace(load_project(project)[0])[1]
    assert "second.n_pairs" in loaded.values, "the second script's results are read"
    assert _synthetic_said(project) == []
    # The other side: declared again in the second script, its result is named.
    second["provenance"]["inputs"] = [{**inputs[0], "synthetic": True}]
    path.write_text(json.dumps(second, indent=2), encoding="utf-8")
    write_digest(path)
    [(severity, message)] = _synthetic_said(project)
    assert severity == "warn" and "results.second.n_pairs" in message
    # Not declared at all, nothing finds it.
    main.write_text(text, encoding="utf-8")
    for record in document["provenance"]["inputs"]:
        record.pop("synthetic", None)
    first.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(first)
    path.unlink()
    path.with_name(path.name + ".sha256").unlink(missing_ok=True)
    assert _synthetic_said(project) == []
    assert "synthetic-input-quoted" not in codes(gate_report(project))


def test_a_demonstration_says_so_on_its_title_page(project: Path) -> None:
    from manuscript_guard.build.submission import title_page

    page = title_page(load_project(project)[0])
    # Round 2 of #320: "analyses" is British, whatever the paper's English.
    assert "**A demonstration.** The data of this paper are synthetic; its results" in page
    _not_a_demonstration(project)
    assert "A demonstration" not in title_page(load_project(project)[0])


# ----------------------------------- a number a summary gives that the paper reports nowhere


def _unreported(root: Path) -> list[tuple[str, str, int]]:
    """What G8 says of a summary: the key, the heading it was given under, the line."""
    from manuscript_guard.gates import check_reported

    project, _ = load_project(root)
    _, results, _, _ = load_namespace(project)
    found = check_reported(project, results).findings
    assert all(f.severity == "warn" for f in found)
    return [
        (f.message.split()[0], re.search(r"under '([^']*)'", f.message)[1], f.line) for f in found
    ]


def _swap(root: Path, old: str, new: str) -> None:
    path = main_md(root)
    text = path.read_text(encoding="utf-8")
    assert text.count(old) == 1, old
    path.write_text(text.replace(old, new), encoding="utf-8")


#: Where the example's abstract concludes, and a count of serious cases written into it.
_CONCLUDES = "synthetic data. Disproportionality"
_SERIOUS = "synthetic data, {{results.case.n_serious}} of them serious. Disproportionality"


def test_a_number_a_summary_gives_and_the_paper_reports_nowhere_is_warned(project: Path) -> None:
    """An abstract or a conclusion introduces no data. The example's abstract gives
    nothing the Methods or the Results do not, and passes; a key given in the Abstract, or
    under a "Conclusions" heading, and bound in neither, is warned of where it was given."""
    from manuscript_guard.cli import _run_gates

    assert _unreported(project) == []
    _swap(project, _CONCLUDES, _SERIOUS)
    _swap(project, "\n# Data availability", "\n## 5. Conclusions\n\nOf {{results.case.n_cases}}"
          " cases, {{results.case.n_serious}} were serious.\n\n# Data availability")  # fmt: skip
    assert _unreported(project) == []  # the Results bind both
    _swap(project, "{{results.case.n_serious}} were flagged", "some were flagged")
    said = [
        ("results.case.n_serious", "Abstract", _line_of(project, "of them serious")),
        ("results.case.n_serious", "Conclusions", _line_of(project, "were serious.")),
    ]
    assert _unreported(project) == said
    report, _project, _chosen, _deferred = _run_gates(project)
    assert sum(f.code == "summary-not-reported" for f in report.findings) == 2
    # The abstract's period is reported in the Methods, which its own Methods restate.
    _swap(project, "{{results.cohort.period_start}} to {{results.cohort.period_end}}, a period",
          "the start to the end, a period")  # fmt: skip
    line = _line_of(project, "covering {{results.cohort.period_start}}")
    assert _unreported(project) == [
        ("results.cohort.period_start", "Abstract", line),
        ("results.cohort.period_end", "Abstract", line),
        *said,
    ]


def test_a_number_the_same_quantity_as_one_reported_is_reported(project: Path) -> None:
    """A coarser form for the abstract is a second key emitted with `same_as`, as the
    emitter's docstring asks: it is reported where the key it is the same as is, either way
    round the declaration goes."""
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["values"]["case.serious_abstract"] = dict(
        document["values"]["case.n_serious"], same_as="case.n_serious"
    )
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    _swap(project, _CONCLUDES, _SERIOUS.replace("n_serious", "serious_abstract"))
    assert _unreported(project) == []
    # And the other way round: the Results bind the key that names the other.
    _swap(project, "{{results.case.n_serious}} were flagged",
          "{{results.case.serious_abstract}} were flagged")  # fmt: skip
    _swap(project, _SERIOUS.replace("n_serious", "serious_abstract"), _SERIOUS)
    assert _unreported(project) == []
    _swap(project, "{{results.case.serious_abstract}} were flagged", "some were flagged")
    assert [key for key, _, _ in _unreported(project)] == ["results.case.n_serious"]


def test_a_number_printed_in_a_table_or_a_figure_the_paper_places_is_reported(
    project: Path,
) -> None:
    """A count shown only in Table 2, and an estimate drawn only in Figure 1, are reported
    there: until the paper no longer places the table or the figure."""
    _swap(project, "Hepatic injury was reported in\n{{results.case.n_cases}} of these",
          "Hepatic injury was reported in\nsome of these")  # fmt: skip
    _swap(project, "ratio of {{results.ror.point}} (95% CI", "ratio of this (95% CI")
    assert _unreported(project) == []  # 77 is in both tables, and 3.84 in the figure
    _swap(project, "{{table.two_by_two}}", "")
    assert _unreported(project) == []
    _swap(project, "{{table.baseline}}", "")
    _swap(project, "{{figure.forest}}", "")
    cases = _line_of(project, "{{results.case.n_cases}} described")
    ratio = _line_of(project, "ratio was {{results.ror.point}}")
    assert _unreported(project) == [
        ("results.case.n_cases", "Abstract", cases),
        ("results.ror.point", "Abstract", ratio),
    ]


def test_a_number_a_summary_gives_is_looked_for_by_its_key_and_by_its_display(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A number a summary gives is looked for by its
    key, and in a table or figure by its display."): a display that stands as a number of
    its own in a placed figure's text or a table's cells reports a key by coincidence, the
    example's tick at 10 among them; a PNG alone and a table's caption report nothing. A
    title that names the Results in other words reports only where the paper has no
    Results heading, a bold "Conclusions." paragraph is no conclusion, and a `lit.` value
    is not looked for."""
    _emitted(project, extra__ten="10", extra__own="84", extra__seven="7")
    abstract = _line_of(project, _CONCLUDES)
    _swap(project, _CONCLUDES, "synthetic data, {{results.extra.ten}} of them. Disproportionality")
    assert _unreported(project) == []  # the figure draws a tick at 10
    _swap(project, "{{figure.forest}}", "")
    assert _unreported(project) == [("results.extra.ten", "Abstract", abstract)]
    _swap(project, "\n\n# Discussion", "\n\n{{figure.forest}}\n\n# Discussion")
    assert _unreported(project) == []
    svg = project / "figures" / "forest.svg"
    drawn = svg.read_bytes()
    svg.unlink()  # the PNG alone is left
    assert _unreported(project) == [("results.extra.ten", "Abstract", abstract)]
    # "84" stands in the figure only inside "3.84", which is no number of its own.
    _swap(project, "{{results.extra.ten}}", "{{results.extra.own}}")
    svg.write_bytes(drawn)
    assert _unreported(project) == [("results.extra.own", "Abstract", abstract)]
    # A table's caption is not read; its header row is.
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    baseline = document["tables"]["baseline"]
    baseline["caption"] = "Reports by drug group, in 7 kinds."
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    _swap(project, "{{results.extra.own}}", "{{results.extra.seven}}")
    assert _unreported(project) == [("results.extra.seven", "Abstract", abstract)]
    baseline["columns"][0] = "Characteristic, of 7 kinds"
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    assert _unreported(project) == []
    # A title that names the Results in other words reports only with no Results heading.
    _swap(project, "{{results.extra.seven}}", "{{results.extra.own}}")
    for title in ("Outcomes", "Main results"):
        restated = f"\n\n# {title}\n\nThey were {{{{results.extra.own}}}}.\n\n# Discussion"
        _swap(project, "\n\n# Discussion", restated)
        assert _unreported(project) == [("results.extra.own", "Abstract", abstract)], title
        _swap(project, "\n# Results\n", "\n# Reports of hepatic injury\n")
        assert _unreported(project) == [], title
        _swap(project, "\n# Reports of hepatic injury\n", "\n# Results\n")
        _swap(project, restated, "\n\n# Discussion")
    # A conclusion set as a bold paragraph is the Discussion's, and summarises nothing.
    _swap(project, "{{results.extra.own}}", "some")
    _swap(project, "\n\n# Data availability",
          "\n\n**Conclusions.** They were {{results.extra.own}}.\n\n# Data availability")
    assert _unreported(project) == []
    _swap(project, "**Conclusions.** They", "## Conclusions\n\nThey")
    assert _unreported(project) == [
        ("results.extra.own", "Conclusions", _line_of(project, "They were {{results.extra"))
    ]
    _swap(project, "## Conclusions\n\nThey were {{results.extra.own}}.", "")
    # A literature value an abstract gives is not looked for.
    _swap(project, "synthetic data, some of them.",
          "synthetic data, against {{lit.background.class_ror}} for the class.")
    assert _unreported(project) == []
    _swap(project, "against {{lit.background.class_ror}} for", "against {{results.extra.own}} for")
    assert _unreported(project) == [("results.extra.own", "Abstract", abstract)]


def test_a_section_of_a_later_file_is_not_taken_for_one_of_an_earlier() -> None:
    """Round 1 of #272: which sections report and which summarise was kept by identity, and
    once a file's sections were freed a section of the next file could be given the address
    of one of them. A section of the second file, its Discussion, was then given the
    address of the first file's Methods, now and then: about one read in twenty with forty
    Results subsections."""
    from manuscript_guard.gates.reported import Given, Walk

    subgroups = "".join(f"## Subgroup {i}\n\nz\n\n" for i in range(40))
    paper = "# Abstract\n\n{{results.a}}\n\n# Methods\n\nm\n\n# Results\n\n{{results.a}}\n\n"
    discussion = "# Discussion\n\nd\n\n## Conclusions\n\n{{results.y}}\n\n## Limitations\n\nl\n"
    for _ in range(300):
        walk = Walk(None)
        walk.read(paper + subgroups)
        assert walk.read(discussion) == ([Given("y", "Conclusions", 7)], set())


def test_a_number_the_supplement_reports_is_reported(project: Path) -> None:
    """The supplement reports what the paper has no room for, under any heading."""
    _swap(project, "{{results.case.n_serious}} were flagged", "some were flagged")
    _swap(project, _CONCLUDES, _SERIOUS)
    assert len(_unreported(project)) == 1
    supplement = project / "manuscript" / "supplementary" / "s1.md"
    supplement.parent.mkdir(exist_ok=True)
    supplement.write_text("# Table S1\n\n{{results.case.n_serious}} serious.\n", encoding="utf-8")
    assert _unreported(project) == []


def _overclaimed(root: Path) -> list:
    """What G8 says of a summary that claims more than the Results (`summary-claim-stronger`)."""
    from manuscript_guard.gates import check_reported

    loaded, _ = load_project(root)
    found = check_reported(loaded, load_namespace(loaded)[1]).findings
    return [f for f in found if f.code == "summary-claim-stronger"]


#: The example's Abstract where it gives the reporting odds ratio, and its Results.
_ABSTRACT_ROR = "example-drug. The reporting odds ratio was {{results.ror.point}}"
_RESULTS_ROR = "Reporting of hepatic injury was disproportionate for example-drug, with a"
_ASSOCIATED = "Example-drug was associated with reports of hepatic injury, with a"
#: Where the example's Results paragraph on the ratio ends.
_RESULTS_END = "so a reader\ncan reconstruct it."


def test_a_summary_that_claims_more_than_the_results_is_warned(project: Path) -> None:
    """Item 3 of the borrowed checks: an abstract that says "increased" where the Results said
    "associated with" claims more than they do, and is warned, on the Abstract's line, naming
    the Results sentence and what moved. The example's Abstract claims no more than its
    Results. A Results sentence that holds no word of the claim lists is not compared, and the
    warning is given only where the summary claims more than every Results sentence that binds
    its key (D3.2): one that says "increased" too keeps it back."""
    assert _overclaimed(project) == []
    _swap(project, _ABSTRACT_ROR,
          "example-drug. Example-drug increased these reports: the reporting odds ratio was "
          "{{results.ror.point}}")  # fmt: skip
    assert _overclaimed(project) == []  # the Results sentence states, and claims nothing
    _swap(project, _RESULTS_ROR, _ASSOCIATED)
    (found,) = _overclaimed(project)
    assert found.severity == "warn" and found.path == main_md(project)
    assert found.line == _line_of(project, "Example-drug increased these reports")
    results = _line_of(project, "ratio of {{results.ror.point}}")
    assert found.message == (
        "this sentence under 'Abstract' claims more than the Results sentence that binds "
        "results.ror.point, results.ror.ci_low and results.ror.ci_high "
        f"(main.md:{results}): 'associated' (association) is now 'increased' (effect)"
    )
    assert found.context.startswith("Example-drug increased these reports")
    _swap(project, "so a reader\ncan reconstruct it.",
          "so a reader\ncan reconstruct it. Example-drug increased these reports "
          "({{results.ror.point}}).")  # fmt: skip
    assert _overclaimed(project) == []  # not stronger than this one
    _swap(project, "Example-drug increased these reports ({{results.ror.point}}).",
          "Example-drug may have increased these reports ({{results.ror.point}}).")
    (found,) = _overclaimed(project)
    assert "each of the 2 Results sentences that bind results.ror.point" in found.message


def test_a_summary_with_no_word_of_the_claim_lists_is_held_to_the_hedges_it_dropped(
    project: Path,
) -> None:
    """The example's Abstract gives the reporting odds ratio in a sentence that holds no word
    that sets how strongly it claims. Against a Results sentence that says "may", it claims
    more, and is warned; against one that says "not", it does not turn the claim round, and
    against one that says "suggests", it claims no more (round 1 of #573): neither is warned
    (Basile, 2026-11-07). An Abstract that says "not" where the Results did not is warned."""
    said = "The ratio may be disproportionate ({{results.ror.point}})."
    _swap(project, _RESULTS_END, f"{_RESULTS_END} {said}")
    (found,) = _overclaimed(project)
    assert found.message.endswith(": 'may' is gone")
    _swap(project, said, "The ratio was not disproportionate ({{results.ror.point}}).")
    assert _overclaimed(project) == []
    _swap(project, "The ratio was not disproportionate", "The ratio suggests a signal")
    assert _overclaimed(project) == []
    _swap(project, "The ratio suggests a signal", "Example-drug was associated with the reports")
    _swap(project, _ABSTRACT_ROR,
          "example-drug. Example-drug was not associated with them: the reporting odds ratio "
          "was {{results.ror.point}}")  # fmt: skip
    (found,) = _overclaimed(project)
    assert found.message.endswith(": 'not' is new")


def test_a_results_sentence_that_gives_another_result_is_held_to_what_the_summary_adds(
    project: Path,
) -> None:
    """Round 1 of #573: a Results sentence that gives a result the summary sentence does not
    give may hedge, limit or negate that other result. Against it only a word of the ladder
    the summary moves up is read (Basile, 2026-11-07): an Abstract that keeps "associated" of
    the cases and leaves out "and not with" the serious ones is not warned, and one that says
    "increased" is."""
    _swap(project, "{{results.case.n_cases}} described\nhepatic injury with example-drug.",
          "use was associated with\nhepatic injury in {{results.case.n_cases}}.")  # fmt: skip
    _swap(project, "Hepatic injury was reported in\n{{results.case.n_cases}} of these; "
          "{{results.case.n_serious}} were flagged as serious",
          "Use was associated with hepatic injury in\n{{results.case.n_cases}} of these, and not "
          "with the {{results.case.n_serious}} flagged as serious")  # fmt: skip
    assert _overclaimed(project) == []
    _swap(project, "use was associated with\nhepatic injury", "use increased\nhepatic injury")
    (found,) = _overclaimed(project)
    assert found.message.endswith(": 'associated' (association) is now 'increased' (effect)")
    # Round 2: with its words about the other result set aside, a Results sentence that
    # holds no word of the ladder states its number, and is compared with nothing.
    _swap(project, "Use was associated with hepatic injury in\n",
          "Hepatic injury was reported in\n")
    assert _overclaimed(project) == []
    # Nor does it keep back the warning another Results sentence gives (round 3).
    _swap(project, _RESULTS_END,
          f"{_RESULTS_END} Example-drug was associated with the {{{{results.case.n_cases}}}}.")
    (found,) = _overclaimed(project)
    assert "the Results sentence that binds results.case.n_cases" in found.message


def test_a_summary_sentence_that_negates_another_result_is_warned_a_known_gap(
    project: Path,
) -> None:
    """Pinned, as DESIGN.md's Known gaps says (round 2 of #573): an Abstract sentence that
    gives two results, one of them negated, is held to each result's Results sentence, and
    its "not" is new against the first while its "associated" is new against the second. So
    it is warned, though neither result is claimed more strongly than the Results claim it."""
    _swap(project, "{{results.case.n_cases}} described\nhepatic injury with example-drug.",
          "use was associated with\nhepatic injury in {{results.case.n_cases}} but not with the "
          "{{results.case.n_serious}} serious ones.")  # fmt: skip
    _swap(project, "Hepatic injury was reported in\n{{results.case.n_cases}} of these;",
          "Use was associated with hepatic injury in\n{{results.case.n_cases}} of these.")
    _swap(project, "{{results.case.n_serious}} were flagged as serious\n"
          "({{results.case.pct_serious}}%).",
          "Seriousness did not differ: {{results.case.n_serious}} were flagged as serious.")
    (found,) = _overclaimed(project)
    assert "each of the 2 Results sentences" in found.message, found.message


def test_a_summary_is_held_to_the_supplement_s_results_and_the_same_quantity(
    project: Path,
) -> None:
    """A Results sentence of the supplement, under "Supplementary results", is held against a
    summary as one of the main text's is, named at its file and line; one under its Methods
    is not. A key declared the same quantity as the one the Results bind is held to their
    sentences, either way round the declaration goes."""
    _swap(project, _ABSTRACT_ROR,
          "example-drug. Example-drug increased these reports: the reporting odds ratio was "
          "{{results.ror.point}}")  # fmt: skip
    supplement = project / "manuscript" / "supplementary" / "s2.md"
    supplement.write_text("# Supplementary methods\n\nThe estimate, {{results.ror.point}}, may be"
                          " associated with the drug.\n", encoding="utf-8")  # fmt: skip
    assert _overclaimed(project) == []  # the supplement's Methods are no Results
    supplement.write_text("# Supplementary methods\n\nm.\n\n## eResults 1\n\nThe estimate, "
                          "{{results.ror.point}}, may be\nassociated with the drug.\n",
                          encoding="utf-8")  # fmt: skip
    (found,) = _overclaimed(project)
    assert "(supplementary/s2.md:7)" in found.message, found.message
    supplement.unlink()
    _swap(project, "Example-drug increased these reports: the", "The")
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["values"]["ror.abstract"] = dict(document["values"]["ror.point"],
                                              same_as="ror.point")  # fmt: skip
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    _swap(project, _RESULTS_ROR, _ASSOCIATED)
    _swap(project, "\n**Conclusions.**",
          " Example-drug increased these reports ({{results.ror.abstract}}).\n**Conclusions.**")
    (found,) = _overclaimed(project)
    assert "binds results.ror.abstract (main.md:" in found.message, found.message
    # And the other way round: the Results bind the key that names the other.
    _swap(project, "ratio of {{results.ror.point}}", "ratio of {{results.ror.abstract}}")
    _swap(project, "({{results.ror.abstract}}).\n**Conclusions.**",
          "({{results.ror.point}}).\n**Conclusions.**")
    (found,) = _overclaimed(project)
    assert "binds results.ror.point (main.md:" in found.message, found.message


def _held(root: Path, summary: str, results: str = "r.", supplement: str = "") -> list[str]:
    """What `summary-claim-stronger` says moved, for a paper whose Abstract is `summary` and
    whose Results are `results`; `supplement`, where given, a file of the supplement."""
    main_md(root).write_text(f"# Abstract\n\n{summary}\n\n# Methods\n\nm.\n\n# Results\n\n"
                             f"{results}\n", encoding="utf-8")  # fmt: skip
    if supplement:
        (root / "manuscript" / "supplementary" / "s9.md").write_text(supplement, "utf-8")
    return [found.message.split("): ", 1)[1] for found in _overclaimed(root)]


_A = "{{results.case.n_cases}}"
_B = "{{results.case.n_serious}}"
_HR = "{{results.ror.point}}"
_CI = "95% CI {{results.ror.ci_low}} to {{results.ror.ci_high}}"


@pytest.mark.parametrize(
    ("summary", "results", "moved"),
    [
        # Only the words of the lists: a claim made stronger in other words, or a qualifier
        # the limits do not list dropped, is not seen.
        (f"Use was associated with twice the risk ({_HR}).",
         f"Use was associated with a higher risk ({_HR}).", []),
        (f"Use was associated with harm ({_HR}).",
         f"Use was associated with harm in older women ({_HR}).", []),
        # A Results sentence that holds none of them is compared with nothing; the claim
        # beside it in a sentence of its own is not read.
        (f"Use caused the outcome ({_HR}).",
         f"Use was associated with the outcome. The adjusted HR was {_HR}.", []),
        (f"Use caused the outcome ({_HR}).",
         f"Use was associated with the outcome; the adjusted HR was {_HR}.",
         ["'associated' (association) is now 'caused' (causation)"]),
        # A summary sentence that holds none is held only to the hedges and limits it
        # dropped: not to a negation or a word of the ladder, and a hedge only where the
        # Results sentence negates nothing and its lowest word, if any, is of consistency.
        (f"The HR was {_HR}.", f"Use was not associated with the outcome ({_HR}).", []),
        (f"The HR was {_HR}.", f"The ratio suggests a signal ({_HR}).", []),
        (f"Rates were higher in men ({_HR}).", f"Rates may be higher in men ({_HR}).",
         ["'may' is gone"]),
        (f"The HR was {_HR}.", f"These may be consistent with an association ({_HR}).",
         ["'may' is gone; 'consistent with' (consistency) and 'association' (association) "
          "are gone"]),
        (f"The HR was {_HR}.", f"Use may be associated with the outcome ({_HR}).", []),
        (f"The HR was {_HR}.", f"Use may not be associated with the outcome ({_HR}).", []),
        # A negation new is claiming more, whatever it negates.
        (f"Use was associated with the outcome, and not with death ({_HR}).",
         f"Use was associated with the outcome ({_HR}).", ["'not' is new"]),
        # Against a Results sentence that binds a result the summary does not give, only a
        # word of the ladder moved up is read; the other side of each is the sentence that
        # binds nothing else.
        (f"Use was associated with A ({_A}).",
         f"Use may be associated with A ({_A}) and with B ({_B}).", []),
        (f"Use was associated with A ({_A}).", f"Use may be associated with A ({_A}).",
         ["'may' is gone"]),
        (f"Use was associated with the outcome ({_HR}).",
         f"Use may be associated with the outcome ({_HR}, {_CI}).", []),
        (f"Use was associated with the outcome ({_HR}, {_CI}).",
         f"Use may be associated with the outcome ({_HR}, {_CI}).", ["'may' is gone"]),
        (f"Use increased the outcome ({_HR}).",
         f"The adjusted HR was {_HR}, and was not raised in women ({_A}).", []),
        # A summary sentence that binds several keys: another key's sentence that claims as
        # much keeps the warning back.
        (f"Use was associated with A ({_A}) and B ({_B}).",
         f"Use may be associated with A ({_A}). Use was associated with B ({_B}).", []),
        (f"Use was associated with A ({_A}) and B ({_B}).",
         f"Use may be associated with A ({_A}). B was {_B}.", ["'may' is gone"]),
    ],
)  # fmt: skip
def test_a_summary_is_held_to_its_results_sentence_by_the_words_of_the_claim_lists(
    project: Path, summary: str, results: str, moved: list[str]
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A summary is held to the Results by the words of
    the claim lists, sentence against sentence"): each pair of the entry, the Abstract's
    sentence against the Results', and what `summary-claim-stronger` says moved, nothing
    where it passes."""
    assert _held(project, summary, results) == moved


def test_a_summary_is_held_to_results_sentences_only(project: Path) -> None:
    """A known gap (DESIGN.md, Known gaps, "A summary is held to the Results by the words of
    the claim lists, sentence against sentence"): a key bound only in the Methods, in a
    Results heading under the Methods, under a review's topical heading, or printed only in
    an emitted table or figure, is compared with nothing; under the Results it is. The
    title is not read."""
    from manuscript_guard.gates import check_reported

    caused = f"Use increased the outcome ({_HR})."
    hedged = f"Use may be associated with the outcome ({_HR})."
    moved = ["'may' is gone; 'associated' (association) is now 'increased' (effect)"]
    assert _held(project, caused, f"r.\n\n## Results of the pilot\n\n{hedged}") == moved
    # An emitted table whose caption and cell hedge beside the key's display, 3.84, and the
    # figure, which prints "no association" beside it.
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["tables"]["claimed"] = {
        "columns": ["Finding", "Ratio"],
        "rows": [["Use may be associated with the outcome", "3.84"]],
        "caption": "Use may be associated with the outcome (3.84).",
    }
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    main_md(project).write_text(f"# Abstract\n\n{caused}\n\n# Methods\n\n{hedged}\n\n## Results "
                                f"of the pilot\n\n{hedged}\n\n# Results\n\nr.\n\n"
                                "{{table.claimed}}\n\n{{figure.forest}}\n",
                                encoding="utf-8")  # fmt: skip
    assert _overclaimed(project) == []
    main_md(project).write_text(f"# Abstract\n\n{caused}\n\n# Introduction\n\ni.\n\n"
                                f"# Reports of the drug\n\n{hedged}\n", encoding="utf-8")
    assert _overclaimed(project) == []
    main_md(project).write_text(f'---\ntitle: "{caused}"\n---\n\n# Methods\n\nm.\n\n'
                                f"# Results\n\n{hedged}\n", encoding="utf-8")  # fmt: skip
    loaded, _ = load_project(project)
    assert list(check_reported(loaded, load_namespace(loaded)[1]).findings) == []


@pytest.mark.parametrize(
    ("heading", "results"),
    [("Supplementary results", True), ("Supplemental results", True),
     ("Additional findings", True), ("S3. Results", True), ("Appendix 2: Results", True),
     ("Appendix S1: Results", True), ("Supplement 1. Results", True), ("eResults 2", True),
     ("Sensitivity analyses", False), ("eTable 2", False),
     ("Supplementary methods\n\nm.\n\n## eResults 1", True),
     ("Supplementary results\n\nr.\n\n## Methods of the pilot", False)],
)  # fmt: skip
def test_a_results_section_of_the_supplement_is_known_by_its_heading(
    project: Path, heading: str, results: bool
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A summary is held to the Results by the words of
    the claim lists, sentence against sentence"): in the supplement a Results section is one
    whose heading opens with "Results" or "Findings" after one of the labels the entry
    names, the innermost heading that names the Methods or the Results deciding."""
    supplement = f"# {heading}\n\nUse may be associated with the outcome ({_HR}).\n"
    said = _held(project, f"Use was associated with the outcome ({_HR}).", supplement=supplement)
    assert said == (["'may' is gone"] if results else [])


def _interpreted(root: Path) -> list:
    """What G8 notes of the sentences that claim on neither a result nor a citation."""
    from manuscript_guard.gates import check_interpretation

    return list(check_interpretation(load_project(root)[0]).findings)


#: Where the example's Discussion turns to its limitations, and two sentences put after it:
#: one that claims on neither a result nor a citation, and one that cites.
_LIMITATIONS = "Several limitations follow from the design."
_PROBABLY = "Example-drug probably increased these reports in older patients."
_CITED = "This association was reported before [@fictionalClassSignal2019]."


def test_a_sentence_that_claims_on_neither_a_result_nor_a_citation_is_counted(
    project: Path,
) -> None:
    """Item 10 of the borrowed checks: a sentence of the Discussion that holds a word of the
    claim ladder ("increased") and neither a binding nor a citation is the paper's
    interpretation, and a note counts it, on its file and at its line (D10.1). One that
    cites, one that binds a result, one with a hedge and no word of the ladder, and one of
    the Introduction or of a conclusion (D10.2) are not counted. The example's Results and
    Discussion hold none."""
    assert _interpreted(project) == []
    _swap(project, _LIMITATIONS, f"{_LIMITATIONS} {_PROBABLY} {_CITED}")
    (note,) = _interpreted(project)
    assert (note.gate, note.code, note.severity) == ("G8", "interpretation-sentences", "info")
    assert (note.path, note.line) == (main_md(project), _line_of(project, _PROBABLY))
    assert note.message.startswith("1 of the 2 sentences of the Results and the Discussion")
    assert note.context == _PROBABLY
    assert "`manuscript-guard explain manuscript/main.md` lists them" in note.hint
    _swap(project, "in older patients.", "in older patients ({{results.ror.point}}).")
    assert _interpreted(project) == []  # it binds a result
    _swap(project, "Example-drug probably increased these reports in older patients "
          "({{results.ror.point}}).", "These reports may be more frequent in older patients.")
    assert _interpreted(project) == []  # a hedge, and no word of the ladder
    _swap(project, "# Introduction\n", "# Introduction\n\nStatins reduce events in trials.\n")
    _swap(project, "# Data availability", "## Conclusions\n\nExample-drug caused these reports."
          "\n\n# Data availability")  # fmt: skip
    assert _interpreted(project) == []  # the Introduction, and a conclusion under the Discussion
    _swap(project, "## Conclusions", "## Strengths")
    (note,) = _interpreted(project)
    assert note.context == "Example-drug caused these reports."


def test_a_citation_typed_against_a_stop_belongs_to_the_sentence_it_ends(project: Path) -> None:
    """Round 1 of #578: a citation typed after the full stop with no space, "injury.[@a] We",
    as a superscript style has it, is the sentence before's, and the sentence after it is a
    sentence of its own: the cited sentence is not counted and the one after it is. Typed
    after a space, "[@a] showed that", it opens the sentence after."""
    _swap(project, _LIMITATIONS, f"{_LIMITATIONS} This association was reported before."
          f"[@fictionalClassSignal2019] {_PROBABLY}")  # fmt: skip
    (note,) = _interpreted(project)
    assert note.context == _PROBABLY and note.message.startswith("1 of the 2"), note.message
    _swap(project, "[@fictionalClassSignal2019] Example", "[@fictionalClassSignal2019] "
          "[@fictionalHepaticCohort2021] Example")  # round 2: both groups are its
    (note,) = _interpreted(project)
    assert note.context == _PROBABLY, note.context
    # Review of 0f2aff82: a group that opens the next paragraph is that paragraph's, and a
    # group that opens a clause in lower case leaves the groups before it to their stop.
    _swap(project, "[@fictionalClassSignal2019] [@fictionalHepaticCohort2021] Example",
          "[@fictionalClassSignal2019]\n\n[@fictionalHepaticCohort2021] Example")
    assert _interpreted(project) == []
    _swap(project, "[@fictionalClassSignal2019]\n\n[@fictionalHepaticCohort2021] Example-drug",
          "[@fictionalClassSignal2019] [@fictionalHepaticCohort2021] showed that example-drug")
    _swap(project, "in older patients.", "in older patients. Example-drug caused them.")
    (note,) = _interpreted(project)
    assert note.message.startswith("1 of the 3"), note.message
    _swap(project, " Example-drug caused them.", "")
    _swap(project, "showed that example-drug", "Example-drug")
    _swap(project, " [@fictionalHepaticCohort2021]", "")
    _swap(project, "before.[@fictionalClassSignal2019] Example-drug probably increased",
          "before. [@fictionalClassSignal2019] showed that example-drug probably increased")
    (note,) = _interpreted(project)
    assert note.context == "This association was reported before.", note.context


def test_the_supplement_s_interpretation_is_counted_where_it_argues(project: Path) -> None:
    """The supplement's Results and Discussion are read as the main text's, under a heading
    of the supplement's own ("eDiscussion", "Supplementary results"), the innermost heading
    that names the Methods, the Results or the Discussion deciding; its Methods are not. The
    note is on the supplement's file."""
    supplement = project / "manuscript" / "supplementary" / "s2.md"
    supplement.write_text("# Supplementary methods\n\nAge was associated with use.\n\n"
                          "## eDiscussion 1\n\nThe drug may affect the liver.\n\n"
                          "# Supplementary results\n\nWomen were linked to more reports.\n",
                          encoding="utf-8")  # fmt: skip
    (note,) = _interpreted(project)
    assert (note.path, note.line) == (supplement, 7)
    assert note.message.startswith("2 of the 2 sentences")
    assert "`manuscript-guard explain manuscript/supplementary/s2.md`" in note.hint


def _counted(root: Path) -> list[str]:
    """The sentences of main.md G8's interpretation note counts, as `explain` lists them;
    the note's count is held to the list."""
    from manuscript_guard.gates.interpretation import listed

    found = listed(load_project(root)[0], main_md(root))
    notes = [note for note in _interpreted(root) if note.path == main_md(root)]
    assert [note.message.split()[0] for note in notes] == ([str(len(found))] if found else [])
    return [one.sentence for one in found]


@pytest.mark.parametrize(
    ("typed", "counted"),
    [
        # A claim with no word of the ladder is not counted; one with a word of it that
        # claims nothing of this paper's results is.
        ("The drug is hepatotoxic.", []),
        ("Older patients are at higher risk.", []),
        ("The class is associated with liver injury in other cohorts.",
         ["The class is associated with liver injury in other cohorts."]),
        # A binding stands it on a result, whatever it claims of it.
        ("The risk increased with dose ({{results.ror.point}}).", []),
        # A narrative citation is a citation; an author and year typed are none, nor is a
        # citation in the footnote the sentence calls, nor the one the sentence before has.
        ("@fictionalClassSignal2019 showed that the class increased injury.", []),
        ("Smith (2019) showed that the class increased injury.",
         ["Smith (2019) showed that the class increased injury."]),
        ("The class increased injury.[^1]\n\n[^1]: As reported before "
         "[@fictionalClassSignal2019].", ["The class increased injury.[^1]"]),
        ("This was reported before [@fictionalClassSignal2019]. It increased injury.",
         ["It increased injury."]),
        ("Figure 1 suggests that use increased the reports.",
         ["Figure 1 suggests that use increased the reports."]),
        # A table typed by hand, its caption line and an image's alternative text.
        ("Figure 1 shows the reports.\n\n| Finding | Seen |\n|---|---|\n"
         "| Use increased injury | yes |\n\nTable: Use increased the reports.\n\n"
         "![Use increased the reports.](figures/forest.png)\n",
         ["| Use increased injury | yes |", "Table: Use increased the reports.",
          "![Use increased the reports.](figures/forest.png) Spontaneous reports are subject "
          "to notoriety bias, and the denominator is unknown."]),
    ],
)  # fmt: skip
def test_the_interpretation_is_found_by_the_words_of_the_ladder_and_what_it_rests_on(
    project: Path, typed: str, counted: list[str]
) -> None:
    """A known gap (DESIGN.md, Known gaps, "The paper's interpretation is found by the words
    of the claim ladder alone"): each sentence of the entry, typed in the Discussion, and
    whether the note counts it."""
    _swap(project, _LIMITATIONS, f"{_LIMITATIONS} {typed}")
    assert _counted(project) == counted


def test_a_placed_display_is_not_read_and_without_results_only_the_discussion_is(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "The paper's interpretation is found by the words
    of the claim ladder alone"): an emitted table's caption that claims, placed by its
    binding, is not read; in a paper with no Results heading only the Discussion is read,
    and a topical section's claim is not counted."""
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["tables"]["two_by_two"]["caption"] = "Use increased these reports."
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    assert _counted(project) == []
    main_md(project).write_text("# Abstract\n\na.\n\n# Reports of the drug\n\nUse increased "
                                "injury.\n\n# Discussion\n\nUse increased the reports.\n",
                                encoding="utf-8")  # fmt: skip
    assert _counted(project) == ["Use increased the reports."]
    # The other side: with a Results heading, the same claim there is counted.
    main_md(project).write_text("# Abstract\n\na.\n\n# Results\n\nUse increased injury.\n\n"
                                "# Discussion\n\nUse increased the reports.\n", encoding="utf-8")
    assert _counted(project) == ["Use increased injury.", "Use increased the reports."]


def test_explain_lists_the_sentences_the_interpretation_note_counts(
    project: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    """`explain` of a file lists, after its numbers, each sentence G8's note counts there,
    at its line: what an interpretation reader of the panel is sent. A file with none says
    nothing more than before."""
    from manuscript_guard.cli import main

    assert main(["explain", str(main_md(project))]) == 0
    assert "interpretation-sentences" not in capsys.readouterr().out
    _swap(project, _LIMITATIONS, f"{_LIMITATIONS} {_PROBABLY} {_CITED}")
    assert main(["explain", str(main_md(project))]) == 0
    said = capsys.readouterr().out.splitlines()
    at = said.index("1 sentence of the Results and the Discussion that claim and rest on "
                    "neither a result nor a citation (G8's interpretation-sentences):")
    assert said[at + 1:] == [f"{_line_of(project, _PROBABLY):>5}  {_PROBABLY}"]


#: A narrative review of made-up reports, which reports under headings of its own and has no
#: section called Results, as a review or a case report has none.
_REVIEW = """# Abstract

Of {{results.cohort.n_reports}} reports, {{results.case.n_cases}} described hepatic injury,
{{results.case.n_serious}} of them serious; the reporting odds ratio was {{results.ror.point}}.

# Introduction

Hepatic injury is a common reason for regulatory action.

# Reports of hepatic injury

The database held {{results.cohort.n_reports}} reports.

## Serious reports: a smaller group

Of them, {{results.case.n_cases}} described hepatic injury, {{results.case.n_serious}} serious.

# Regulatory responses

Against all other drugs, the reporting odds ratio was {{results.ror.point}}.

# Discussion

Reporting is not incidence.

# Conclusions

A reporting odds ratio of {{results.ror.point}} is a signal and no more.

# Funding

None.
"""


def test_a_paper_with_no_results_section_reports_under_its_own_headings(project: Path) -> None:
    """A narrative review reports under topical headings, and every number its abstract and
    its conclusions bound and its body gave again was warned: none of those headings opened
    with "Results". Where the paper has no Results section, every section but the summaries,
    the Introduction, the Discussion and the back matter reports. A number bound in the
    abstract alone is still warned, and so is one the Introduction, the Discussion or a
    statement gives again, with a message that says where the paper was read. Once the paper
    has a Results section, the topical sections report nothing again."""
    from manuscript_guard.gates import check_reported

    def said(text: str) -> list[tuple[str, str, int, str]]:
        main_md(project).write_text(text, encoding="utf-8")
        loaded, _ = load_project(project)
        found = check_reported(loaded, load_namespace(loaded)[1]).findings
        return [(f.message.split()[0], re.search(r"under '([^']*)'", f.message)[1], f.line,
                 f.message) for f in found]  # fmt: skip

    assert said(_REVIEW) == []
    alone = _REVIEW.replace(", {{results.case.n_serious}} serious.", ".")
    for where in ("# Introduction\n\n", "# Discussion\n\n", "# Funding\n\n"):
        text = alone.replace(where, f"{where}Of them, {{{{results.case.n_serious}}}} serious. ")
        (found,) = said(text)
        assert found[:3] == ("results.case.n_serious", "Abstract", 4), where
        assert "with no Results section" in found[3], found
        assert "the Methods, the Results" not in found[3], found
    # With a Results section, a topical heading is read as before.
    found = said(_REVIEW.replace("# Regulatory responses", "# Results"))
    assert [(key, heading) for key, heading, _line, _message in found] == [
        ("results.cohort.n_reports", "Abstract"),
        ("results.case.n_cases", "Abstract"),
        ("results.case.n_serious", "Abstract"),
    ]
    assert all("nowhere in the Methods, the Results, a table or a figure" in one[3]
               for one in found)  # fmt: skip


def _reported_said(project: Path, text: str) -> list:
    """What G8's check of the abstract says of `text` as the whole manuscript."""
    from manuscript_guard.gates import check_reported

    main_md(project).write_text(text, encoding="utf-8")
    loaded, _ = load_project(project)
    return list(check_reported(loaded, load_namespace(loaded)[1]).findings)


#: `_REVIEW` with the reporting odds ratio given again nowhere but in the abstract.
_REVIEW_ROR_ALONE = _REVIEW.replace(
    "Against all other drugs, the reporting odds ratio was {{results.ror.point}}.",
    "Against all other drugs, the signal held.",
).replace(
    "A reporting odds ratio of {{results.ror.point}} is a signal and no more.",
    "A reporting odds ratio is a signal and no more.",
)


@pytest.mark.parametrize(
    "heading",
    ["Highlights", "Key points", "Strengths and limitations", "Future directions",
     "Implications for practice"],  # fmt: skip
)
def test_a_heading_that_reports_nothing_reports_where_the_paper_has_no_results(
    project: Path, heading: str
) -> None:
    """Known gaps (round 1 of #508, note 2): with no Results heading, a section reports
    unless its whole title names a part that reports nothing. A number the abstract gives
    and only a section under one of these headings gives again is not warned of; the
    journal's profile declares no box by any of them."""
    assert [f.message.split()[0] for f in _reported_said(project, _REVIEW_ROR_ALONE)] == [
        "results.ror.point"
    ]
    text = _REVIEW_ROR_ALONE.replace(
        "# Discussion\n", f"# {heading}\n\nThe reporting odds ratio was "
        "{{results.ror.point}}.\n\n# Discussion\n",
    )  # fmt: skip
    assert _reported_said(project, text) == []


def test_a_number_restated_only_under_the_limitations_is_told_a_list_without_them(
    project: Path,
) -> None:
    """Known gaps (round 1 of #508, note 3): the limitations report nothing, and a number
    the abstract gives and only they give again is warned of; the message lists the parts
    that report nothing without the limitations, the reference list, or a heading under one
    of them."""
    text = _REVIEW_ROR_ALONE.replace(
        "# Discussion\n", "# Limitations\n\nThe reporting odds ratio was "
        "{{results.ror.point}}.\n\n# Discussion\n",
    )  # fmt: skip
    [found] = _reported_said(project, text)
    assert found.message.split()[0] == "results.ror.point"
    assert ("every section reports but the abstract, a box, the Introduction, the "
            "Discussion, a conclusion and the back matter") in found.message  # fmt: skip
    assert "limitation" not in found.message.lower()
    assert "reference" not in found.message.lower()


def test_a_findings_subheading_under_a_topical_section_is_read_as_the_results(
    project: Path,
) -> None:
    """Known gaps (round 1 of #508, note 4): a heading that opens with "Findings" is read as
    the Results at any level. Under a review's own section, "## Findings in context" gives
    the paper a Results heading, its topical sections report nothing, and the abstract's
    numbers they give again are warned of, as where a section is called "Results"."""
    text = _REVIEW.replace(
        "# Regulatory responses\n",
        "## Findings in context\n\nEarlier series found the same.\n\n# Regulatory responses\n",
    )
    found = [(f.message.split()[0], re.search(r"under '([^']*)'", f.message)[1])
             for f in _reported_said(project, text)]  # fmt: skip
    assert found == [
        ("results.cohort.n_reports", "Abstract"),
        ("results.case.n_cases", "Abstract"),
        ("results.case.n_serious", "Abstract"),
        ("results.ror.point", "Abstract"),
        ("results.ror.point", "Conclusions"),
    ]


@pytest.mark.parametrize(
    "heading", ["The problem of arrests", "What this means for regulators", "The signal in short"]
)
def test_a_review_s_own_introduction_discussion_or_summary_reports_where_it_has_no_results(
    project: Path, heading: str
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A paper with no Results heading reports under
    every heading that names no part."): a section of a review's own that is really an
    introduction, a discussion or a summary reports, so the abstract's number it restates
    passes; under the paper's Introduction it would be warned of."""
    said = [f.message.split()[0] for f in _reported_said(project, _REVIEW_ROR_ALONE)]
    assert said == ["results.ror.point"]
    restated = f"# {heading}\n\nThe reporting odds ratio was {{{{results.ror.point}}}}.\n\n"
    assert _reported_said(project, _REVIEW_ROR_ALONE.replace(
        "# Discussion\n", restated + "# Discussion\n")) == []  # fmt: skip
    # The other side: under a heading that names the Introduction, it reports nothing.
    introduction = _REVIEW_ROR_ALONE.replace(
        "Hepatic injury is a common reason for regulatory action.\n",
        "Hepatic injury is a common reason for regulatory action.\n\n#" + restated,
    )
    assert [f.message.split()[0] for f in _reported_said(project, introduction)] == [
        "results.ror.point"
    ]


def test_what_a_paper_with_no_results_heading_reads_as_its_results_and_its_title(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A paper with no Results heading reports under
    every heading that names no part."): a heading that opens with "Results", at any level,
    gives a review a Results heading, and its topical sections then report nothing; a
    topical section over a subsection called "Background" is the paper's title, and the
    text directly under it reports nothing; and an abstract that no heading names,
    "Overview", is a section of the paper's own, whose "Results" heading is a Results
    heading."""

    def said(text: str) -> list[tuple[str, str]]:
        return [(f.message.split()[0], re.search(r"under '([^']*)'", f.message)[1])
                for f in _reported_said(project, text)]  # fmt: skip

    search = _REVIEW.replace("## Serious reports: a smaller group\n",
                             "## Results of the search\n")  # fmt: skip
    assert said(search) == [
        ("results.cohort.n_reports", "Abstract"),
        ("results.ror.point", "Abstract"),
        ("results.ror.point", "Conclusions"),
    ]
    # The other side: a subheading that does not open with "Results" leaves the paper
    # without one, and every topical section reports.
    assert said(_REVIEW.replace("## Serious reports: a smaller group\n",
                                "## The search and its results\n")) == []  # fmt: skip
    ratio = "Against all other drugs, the reporting odds ratio was {{results.ror.point}}.\n"
    background = _REVIEW.replace(
        "# Regulatory responses\n\n" + ratio,
        "# Regulatory responses\n\n" + ratio + "\n## Background\n\nIt was asked before.\n",
    )
    assert said(background) == [
        ("results.ror.point", "Abstract"),
        ("results.ror.point", "Conclusions"),
    ]
    # The other side: under a subsection of any other name the same text reports.
    assert said(background.replace("## Background\n", "## Earlier questions\n")) == []
    # An "Overview" is no abstract: its "Results" heading is the paper's, which then has
    # Results, and the topical sections report nothing.
    # A key the Conclusions give and only a topical section gives again.
    topical = _REVIEW.replace(
        "# Conclusions\n\n", "# Conclusions\n\nIt held {{results.cohort.n_drug_reports}}. "
    ).replace("# Regulatory responses\n\n",
              "# Regulatory responses\n\nOf {{results.cohort.n_drug_reports}}. ")  # fmt: skip
    overview = topical.replace("# Abstract\n\n", "# Overview\n\n## Results\n\n")
    assert said(overview) == [("results.cohort.n_drug_reports", "Conclusions")]
    # The other side: under "Abstract", its "Results" summarise, the paper has no Results
    # heading, and the topical section reports.
    assert said(topical.replace("# Abstract\n\n", "# Abstract\n\n## Results\n\n")) == []


def test_a_latex_paper_with_no_results_section_reports_under_its_own_headings(
    project: Path,
) -> None:
    """The same in LaTeX, read in the printed view: a key the abstract gives and a section of
    the review's own gives again is reported, and one the abstract alone gives is not."""
    from manuscript_guard.gates import check_reported

    folder = project / "manuscript"
    for path in folder.rglob("*.md"):
        path.unlink()

    def said(abstract: str) -> list[str]:
        (folder / "main.tex").write_text(
            "\\documentclass{article}\n\\begin{document}\n\\begin{abstract}\n" + abstract
            + "\n\\end{abstract}\n\\section{Introduction}\nx\n\\section{Regulatory responses}\n"
            "The ROR was \\mg{results.ror.point}.\n\\section{Discussion}\n"
            "Of \\mg{results.case.n_cases}.\n\\end{document}\n",
            encoding="utf-8",
        )
        loaded, _ = load_project(project)
        return [f.message.split()[0] for f in
                check_reported(loaded, load_namespace(loaded)[1]).findings]  # fmt: skip

    assert said("The ROR was \\mg{results.ror.point}.") == []
    assert said("Of \\mg{results.case.n_cases}.") == ["results.case.n_cases"]


def test_a_latex_paper_s_unheaded_opening_reports_where_it_has_no_results(
    project: Path,
) -> None:
    """Known gaps (round 1 of #508, note 1): the printed view closes the abstract with a
    heading of no title, so the text after it, an introduction with no heading of its own
    as Nature's and PNAS's papers open, reports where the paper has no Results. A number
    the abstract gives and only that text gives again is not warned of; with
    `\\section{Introduction}` over the same text, it is."""
    from manuscript_guard.gates import check_reported

    folder = project / "manuscript"
    for path in folder.rglob("*.md"):
        path.unlink()

    def said(opening: str) -> list[str]:
        (folder / "main.tex").write_text(
            "\\documentclass{article}\n\\begin{document}\n\\begin{abstract}\n"
            "The ROR was \\mg{results.ror.point}.\n\\end{abstract}\n" + opening
            + "The ROR was \\mg{results.ror.point}.\n\\section{Regulatory responses}\nx\n"
            "\\section{Discussion}\nd\n\\end{document}\n",
            encoding="utf-8",
        )
        loaded, _ = load_project(project)
        return [f.message.split()[0] for f in
                check_reported(loaded, load_namespace(loaded)[1]).findings]  # fmt: skip

    assert said("") == []
    assert said("\\section{Introduction}\n") == ["results.ror.point"]


# ----------------------------- a trial's table of baseline characteristics with P values, G8

#: A table typed in Markdown with a column of P values, its caption pandoc's after it. Its
#: cells hold words, so that G2 says nothing of them.
_TYPED_BASELINE = (
    "\n\n| Characteristic | Drug | Placebo | {header} |\n|---|---|---|---|\n"
    "| Female | half | half | low |\n\nTable: {caption}\n"
)


def _baseline_said(root: Path) -> list[tuple[str, int | None]]:
    """Where G8 warns of a table of baseline characteristics with P values: each file, from
    the project's folder, and line."""
    from manuscript_guard.gates.baseline import CODE, check_baseline

    project, _report = load_project(root)
    results = load_namespace(project)[1]
    found = check_baseline(project, results).findings
    assert all(f.code == CODE and f.severity == "warn" for f in found), found
    return [(f.path.relative_to(root).as_posix(), f.line) for f in found]


def _emit_baseline(root: Path, caption: str, header: str = "P value") -> None:
    """The example's table of reports by group, emitted with `caption` and a column headed
    `header` whose cells are empty."""
    fragment = root / "results" / "01_disproportionality.json"
    document = json.loads(fragment.read_text(encoding="utf-8"))
    table = document["tables"]["baseline"]
    table["caption"] = caption
    table["columns"].append(header)
    table["align"].append("right")
    for row in table["rows"]:
        row.append("")
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)


def _type_into(path: Path, caption: str, header: str = "P value") -> None:
    with path.open("a", encoding="utf-8") as typed:
        typed.write(_TYPED_BASELINE.format(caption=caption, header=header))


def test_an_emitted_baseline_table_with_p_values_in_a_trial_warns_at_every_stage(
    project: Path,
) -> None:
    """CONSORT 2010 (item 15) and 2025 (item 25): a test of a baseline difference in a
    randomised trial tests what the randomisation made true. A warning, never a failure."""
    from manuscript_guard.cli import _run_gates

    _paper_field(project, "study_type", "trial")
    _emit_baseline(project, "Baseline characteristics of the reports, by group.")
    assert _baseline_said(project) == [("results/01_disproportionality.json", None)]
    for stage in ("drafting", "submission"):
        report, _project, _stage, _deferred = _run_gates(project, stage=stage)
        (found,) = [f for f in report.findings if f.code == "baseline-p-values"]
        assert found.severity == "warn" and found not in report.failures, stage
        assert "item 15" in found.message and "item 25" in found.message, found.message
        assert "'P value'" in found.message and "randomised trial" in found.message
        assert found.hint.startswith("emit the table without the P column")
        assert "prognostic covariates" in found.hint


@pytest.mark.parametrize("header", ["P", "p-value", "*P*", "P value^a^", "P\N{DAGGER}"])
def test_a_typed_baseline_table_with_p_values_in_a_trial_warns(
    project: Path, header: str
) -> None:
    _paper_field(project, "study_type", "trial")
    main = main_md(project)
    _type_into(main, "Baseline characteristics of the participants", header)
    line = main.read_text(encoding="utf-8").split("\n").index(
        f"| Characteristic | Drug | Placebo | {header} |") + 1
    assert _baseline_said(project) == [("manuscript/main.md", line)]


def test_a_baseline_table_with_p_values_in_the_supplement_warns(project: Path) -> None:
    """The supplement is read as the main text is, a grid table as a pipe table is."""
    _paper_field(project, "study_type", "trial")
    (project / "manuscript" / "supplementary" / "S3_baseline.md").write_text(
        "# Baseline\n\n: Characteristics at BASELINE\n\n"
        "+---------+---------+---------+\n| Item    | Drug    | p       |\n"
        "+=========+=========+=========+\n| Female  | half    | low     |\n"
        "+---------+---------+---------+\n",
        encoding="utf-8",
    )
    assert _baseline_said(project) == [("manuscript/supplementary/S3_baseline.md", 6)]


def test_a_latex_baseline_table_with_p_values_in_a_trial_warns(project: Path) -> None:
    """The LaTeX twin: a `tabular` in a `table` float, its caption the float's, in the main
    text and in the supplement."""
    _paper_field(project, "study_type", "trial")
    entry = _as_latex(project)
    float_ = ("\\begin{table}\n\\caption{Baseline characteristics}\n\\begin{tabular}{lll}\n"
              "Item & Drug & $p$ \\\\\n\\hline\nFemale & half & low \\\\\n\\end{tabular}\n"
              "\\end{table}\n")
    entry.write_text(entry.read_text(encoding="utf-8").replace(
        "\\end{document}", float_ + "\\end{document}"), encoding="utf-8")
    supplement = project / "manuscript" / "supplementary" / "main.tex"
    supplement.parent.mkdir(exist_ok=True)
    supplement.write_text("\\documentclass{article}\n\\begin{document}\n" + float_
                          + "\\end{document}\n", encoding="utf-8")  # fmt: skip
    assert _baseline_said(project) == [("manuscript/main.tex", 7),
                                       ("manuscript/supplementary/main.tex", 6)]


@pytest.mark.parametrize(
    ("study_type", "caption", "header"),
    [
        # The same table in a cohort study, and in a paper that names no design.
        ("cohort", "Baseline characteristics of the participants", "P value"),
        (None, "Baseline characteristics of the participants", "P value"),
        # A trial's table of outcomes, of a change from baseline, of what follows it.
        ("trial", "Outcomes at 12 weeks", "P value"),
        ("trial", "Change from baseline in the score at 12 weeks", "P value"),
        ("trial", "Postbaseline events", "P value"),
        # A header that holds a P and is none.
        ("trial", "Baseline characteristics of the participants", "Ptype"),
        ("trial", "Baseline characteristics of the participants", "P Value"),
    ],
)  # fmt: skip
def test_what_is_no_trials_baseline_table_with_p_values_passes(
    project: Path, study_type: str | None, caption: str, header: str
) -> None:
    if study_type is not None:
        _paper_field(project, "study_type", study_type)
    _emit_baseline(project, caption, header)
    _type_into(main_md(project), caption, header)
    assert _baseline_said(project) == []


#: Captions of a trial's tables of outcomes that hold the word and name no table of baseline
#: characteristics (round 1 of #657).
_OUTCOMES_NAMING_BASELINE = (
    "Primary outcome at baseline and 12 weeks",
    "Primary outcome by baseline risk",
    "Outcomes at 12 weeks, adjusted for age, sex and baseline score",
    "Outcomes adjusting for baseline values",
    "Post-baseline adverse events",
    # The phrase after what qualifies an outcome (round 2 of #657).
    "Primary and secondary outcomes, adjusted for baseline characteristics",
    "Subgroup analysis of the primary outcome by baseline characteristics",
    # Words between the qualifier and the phrase, a time inside it, and "features"
    # (round 3 of #657).
    "Outcomes at 12 weeks, adjusted for age, sex and baseline characteristics",
    "Outcomes at 12 weeks, adjusted for prespecified baseline characteristics",
    "Outcomes at 12 weeks by selected baseline characteristics",
    "Outcomes based on baseline characteristics",
    "Changes between baseline and follow-up in clinical characteristics",
    "Comparison of baseline and follow-up characteristics",
    "Baseline MRI features associated with response",
    "Patients with or without baseline high-risk features",
    "Comparison of baseline and follow up characteristics",
    "Baseline and six-month characteristics",
)


