def test_tables_first_cited_out_of_order_are_said(project: Path) -> None:
    _add_to_results(project, "Table 2 has the counts.")
    main = main_md(project)
    text = main.read_text(encoding="utf-8")
    main.write_text(
        text.replace("Baseline characteristics are shown in Table 1. Table 2 has the counts.",
                     "Table 2 has the counts. Baseline characteristics are shown in Table 1.", 1),
        encoding="utf-8",
    )  # fmt: skip
    assert [code for code, _ in _pointer_findings(project)] == ["cited-out-of-order"]


def test_a_table_cited_nowhere_is_said(project: Path) -> None:
    main = main_md(project)
    text = main.read_text(encoding="utf-8")
    main.write_text(text.replace("in Table 2, so", "below, so", 1), encoding="utf-8")
    said = _pointer_findings(project)
    assert [code for code, _ in said] == ["display-not-cited"], said
    assert said[0][1].startswith("Table 2 ")


def test_a_typed_pointer_is_held_to_a_number_and_not_to_the_table_it_means(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A typed pointer is held to the number of a
    placement"): with the example's two tables swapped, its "in Table 2" names the other
    table and still passes; only a number past the count is said."""
    main = main_md(project)
    text = main.read_text(encoding="utf-8")
    swapped = (
        text.replace("{{table.baseline}}", "{{table.swapped}}", 1)
        .replace("{{table.two_by_two}}", "{{table.baseline}}", 1)
        .replace("{{table.swapped}}", "{{table.two_by_two}}", 1)
    )
    assert swapped != text
    main.write_text(swapped, encoding="utf-8")
    assert _pointer_findings(project) == []
    # The other side of the rule: a number the count does not reach.
    _add_to_results(project, "As Table 3 shows.")
    assert [code for code, _ in _pointer_findings(project)] == ["pointer-to-nothing"]


def test_a_pointer_in_a_heading_is_checked_for_a_target_and_cites_nothing(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A typed pointer is held to the number of a
    placement"): a heading's "Table 9" points at nothing and is said, and a heading's
    "Table 2" is no citation of Table 2; nor is a caption typed above its table, which is
    checked for a target as well."""
    main = main_md(project)
    text = main.read_text(encoding="utf-8").replace("in Table 2, so", "below, so", 1)
    main.write_text(text.replace("# Discussion", "## Table 9 and the rest\n\n# Discussion", 1),
                    encoding="utf-8")  # fmt: skip
    said = _pointer_findings(project)
    assert sorted(code for code, _ in said) == ["display-not-cited", "pointer-to-nothing"], said
    main.write_text(text.replace("# Discussion", "## Table 2 and the rest\n\n# Discussion", 1),
                    encoding="utf-8")  # fmt: skip
    said = _pointer_findings(project)
    assert [code for code, _ in said] == ["display-not-cited"], said
    assert said[0][1].startswith("Table 2 ")
    main.write_text(
        text.replace("{{table.two_by_two}}", "**Table 9.** Counts\n\n{{table.two_by_two}}", 1),
        encoding="utf-8",
    )
    said = _pointer_findings(project)
    assert sorted(code for code, _ in said) == ["display-not-cited", "pointer-to-nothing"], said


def test_another_paper_s_table_is_read_as_the_paper_s_own(project: Path) -> None:
    """A known gap (DESIGN.md, Known gaps, "A typed pointer is held to the number of a
    placement"): "Table 3 of Smith et al." points at this paper's Table 3, which it does
    not have; "Table 2 of Smith et al." passes as a citation of this paper's Table 2, which
    the paper cites nowhere else."""
    from manuscript_guard.gates.pointers import pointers_in

    said = pointers_in("Table 3 of Smith et al. gave the same.", Path("x"))
    assert [(p.kind, p.number, p.supplementary) for p in said] == [("table", 3, False)]
    _add_to_results(project, "Table 3 of Smith et al. gave the same.")
    said = _pointer_findings(project)
    assert [code for code, _ in said] == ["pointer-to-nothing"], said
    assert "points at table 3," in said[0][1]
    _rewrite(project, ("Table 3 of Smith", "Table 2 of Smith"), ("in Table 2, so", "below, so"))
    assert _pointer_findings(project) == []


def test_a_box_a_section_and_an_equation_are_no_pointers_the_check_counts(
    project: Path,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A typed pointer is held to the number of a
    placement"): "Box 9", "Section 9" and "Equation 9" point at nothing the check counts,
    where "Table 9" is held to the tables placed."""
    from manuscript_guard.gates.pointers import pointers_in

    assert pointers_in("See Box 9, Section 9 and Equation 9.", Path("x")) == []
    assert [p.number for p in pointers_in("See Table 9.", Path("x"))] == [9]
    _add_to_results(project, "See Box 9, Section 9 and Equation 9.")
    assert _pointer_findings(project) == []


# ------------------------------------------------------------ a pointer the build numbers
# `{{ref.table.<key>}}` prints the number the document gives the table placed by
# `{{table.<key>}}`, and `{{num.table.<key>}}` the number alone, for a list the author writes
# (Basile's choices of 2026-10-20). Typed, "Table 2" went on naming the second table after
# the first moved, and only G2 said so.

#: Every finding about a pointer, typed or printed by a binding.
_REF_CODES = (
    "pointer-to-nothing", "cited-out-of-order", "display-not-cited", "unresolved-binding",
    "ref-number-unknown", "pointer-word-mismatch", "pointer-form-unread",
    "caption-names-another",
)  # fmt: skip


def _ref_findings(root: Path) -> list[tuple[str, str]]:
    return [(f.code, f.message) for f in gate_report(root).findings if f.code in _REF_CODES]


def _rewrite(root: Path, *changes: tuple[str, str], file: Path | None = None) -> None:
    path = file or main_md(root)
    text = path.read_text(encoding="utf-8")
    for was, now in changes:
        assert was in text, was
        text = text.replace(was, now, 1)
    path.write_text(text, encoding="utf-8")


def _assembled_main(root: Path) -> str:
    """The main text as the build assembles it, every binding substituted."""
    from manuscript_guard.build.assemble import assemble

    project, _ = load_project(root)
    namespace, results, _literature, _ = load_namespace(project)
    assembled, report = assemble(project, namespace, results)
    assert report.ok, report.findings
    return next(item.text for item in assembled if item.path.name == "main.md")


#: The example's two typed pointers to its main text's tables, as refs.
_BY_REF = (
    ("shown in Table 1.", "shown in {{ref.table.baseline}}."),
    ("in Table 2, so", "in {{ref.table.two_by_two}}, so"),
)


def test_a_ref_prints_the_number_the_document_gives(project: Path) -> None:
    _rewrite(project, *_BY_REF)
    assert _ref_findings(project) == []
    printed = _assembled_main(project)
    assert "shown in Table 1." in printed
    assert "in Table 2, so" in printed


def test_a_moved_table_renumbers_every_ref_and_its_order_is_said(project: Path) -> None:
    """The two tables swapped: each ref prints its table's new number, where the typed
    pointers would go on naming the old one with nothing said. The first citation is now of
    Table 2, which ICMJE's order refuses."""
    _rewrite(project, *_BY_REF)
    _rewrite(
        project,
        ("{{table.baseline}}", "{{table.swapped}}"),
        ("{{table.two_by_two}}", "{{table.baseline}}"),
        ("{{table.swapped}}", "{{table.two_by_two}}"),
    )
    printed = _assembled_main(project)
    assert "shown in Table 2." in printed
    assert "in Table 1, so" in printed
    assert [code for code, _ in _ref_findings(project)] == ["cited-out-of-order"]


def test_a_ref_counts_as_a_citation(project: Path) -> None:
    """Table 2 cited nowhere, then cited by its ref."""
    _rewrite(project, ("in Table 2, so", "below, so"))
    assert [code for code, _ in _ref_findings(project)] == ["display-not-cited"]
    _rewrite(project, ("below, so", "in {{ref.table.two_by_two}}, so"))
    assert _ref_findings(project) == []


def test_a_ref_in_a_listing_is_printed_and_cites_nothing(project: Path) -> None:
    """A known gap (DESIGN.md, Known gaps, "A ref G2 does not see is still printed"): a
    table cited only by a ref in a listing is `display-not-cited`, and the build prints
    the ref there. One the count cannot number is refused by the build, and G2 says
    nothing of it."""
    from manuscript_guard.build.assemble import assemble

    listing = "\n" + "`" * 3 + "\nsee {{ref.table.two_by_two}}\n" + "`" * 3 + "\n"
    _rewrite(project, ("in Table 2, so", "below, so"), ("# Discussion", f"{listing}\n# Discussion"))
    said = _ref_findings(project)
    assert [code for code, _ in said] == ["display-not-cited"], said
    assert said[0][1].startswith("Table 2 ")
    assert "\nsee Table 2\n" in _assembled_main(project)
    # Placed twice, the baseline table has no number for a ref to print.
    _rewrite(
        project,
        ("see {{ref.table.two_by_two}}", "see {{ref.table.baseline}}"),
        ("{{table.two_by_two}}", "{{table.two_by_two}}\n\n{{table.baseline}}"),
    )
    assert "ref-number-unknown" not in codes(gate_report(project))
    projekt, _ = load_project(project)
    namespace, results, _literature, _ = load_namespace(projekt)
    _assembled, report = assemble(projekt, namespace, results)
    assert [f.code for f in report.failures] == ["ref-number-unknown"]


@pytest.mark.parametrize(
    ("ref", "named"),
    [
        ("{{ref.table.nothing}}", "names a table nothing places"),
        ("{{num.figure.nothing}}", "names a figure nothing places"),
        ("{{ref.baseline}}", "names no table and no figure"),
        ("{{ref.model.baseline}}", "names no table and no figure"),
    ],
)
def test_a_ref_to_a_key_nothing_places_is_unresolved(
    project: Path, ref: str, named: str
) -> None:
    """In `check` and in the build: printed, it would be the binding's own text."""
    from manuscript_guard.build.assemble import assemble

    _rewrite(project, ("shown in Table 1.", f"shown in Table 1 and {ref}."))
    said = _ref_findings(project)
    assert [code for code, _ in said] == ["unresolved-binding"], said
    assert named in said[0][1]
    projekt, _ = load_project(project)
    namespace, results, _literature, _ = load_namespace(projekt)
    _assembled, report = assemble(projekt, namespace, results)
    assert [f.code for f in report.failures] == ["unresolved-binding"]


def _journal_forms(root: Path, forms: str) -> None:
    profile = root / "profiles" / "journals" / "demo-journal.yaml"
    profile.write_text(
        profile.read_text(encoding="utf-8") + f"\npointers: {forms}\n", encoding="utf-8"
    )


@pytest.mark.parametrize(
    ("forms", "whole", "alone"),
    [
        (None, "Table S1", "S1"),
        ('{supplementary_table: "eTable {n}"}', "eTable 1", "1"),
        ('{supplementary_table: "Supplementary Table {n}"}', "Supplementary Table 1", "1"),
        ('{supplementary_table: "Table {n} in the Supplement"}', "Table 1 in the Supplement",
         "1"),
        ('{supplementary_table: "eTable {n} in Supplement 1"}', "eTable 1 in Supplement 1",
         "1"),
    ],
)  # fmt: skip
def test_a_ref_to_the_supplement_prints_the_journal_s_form(
    project: Path, forms: str | None, whole: str, alone: str
) -> None:
    if forms:
        _journal_forms(project, forms)
    _rewrite(project, ("shown in Table 1.", "shown in Table 1 and {{ref.table.outcome_codes}}."))
    assert _ref_findings(project) == []
    assert f"shown in Table 1 and {whole}." in _assembled_main(project)
    _rewrite(project, ("{{ref.table.outcome_codes}}", "{{num.table.outcome_codes}}"))
    printed = _assembled_main(project)
    assert f"shown in Table 1 and {alone}." in printed


def test_a_form_g2_does_not_read_is_refused(project: Path) -> None:
    """"Tab. 2" is no pointer G2 reads, so a ref printed in it could not be held to anything."""
    _journal_forms(project, '{table: "Tab. {n}"}')
    said = _ref_findings(project)
    assert [code for code, _ in said] == ["pointer-form-unread"], said
    assert "'Tab. {n}'" in said[0][1]


def test_a_form_without_its_number_breaks_the_profile(project: Path) -> None:
    _journal_forms(project, '{figure: "Figure"}')
    from manuscript_guard.cli import _run_gates

    assert "schema-violation" in codes(_run_gates(project)[0])


def test_a_list_of_nums_is_read_whole(project: Path) -> None:
    _rewrite(
        project,
        ("shown in Table 1.", "shown in Tables {{num.table.baseline}} and "
         "{{num.table.two_by_two}}."),
        ("in Table 2, so", "below, so"),
    )  # fmt: skip
    assert _ref_findings(project) == []
    assert "shown in Tables 1 and 2." in _assembled_main(project)


def _emit_copy(root: Path, key: str, copy: str) -> None:
    """The example's analysis as if it had emitted table `key` a second time, as `copy`."""
    fragment = root / "results" / "01_disproportionality.json"
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["tables"][copy] = json.loads(json.dumps(document["tables"][key]))
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)


def test_a_range_between_two_nums_takes_in_what_is_placed_between_them(project: Path) -> None:
    """A known gap (DESIGN.md, Known gaps, "A range between two nums covers what the build
    numbers between them"): "Tables 1-2", written with two nums, prints "Tables 1-3" once a
    table is placed between its ends, and nothing is said. Written with two refs, the range
    is two pointers, and the table between them is cited by neither. The 2026-11-09 triage
    planned a fix (F08), which will change this test."""
    _emit_copy(project, "baseline", "extra")
    _rewrite(
        project,
        ("shown in Table 1.", "shown in Tables {{num.table.baseline}}-{{num.table.two_by_two}}."),
        ("in Table 2, so", "below, so"),
    )
    assert _ref_findings(project) == []
    assert "shown in Tables 1-2." in _assembled_main(project)
    _rewrite(project, ("{{table.baseline}}", "{{table.baseline}}\n\n{{table.extra}}"))
    assert "shown in Tables 1-3." in _assembled_main(project)
    assert _ref_findings(project) == []
    # The other side: two refs are two pointers, and Table 2 is cited by neither.
    _rewrite(
        project,
        ("Tables {{num.table.baseline}}-{{num.table.two_by_two}}",
         "{{ref.table.baseline}}-{{ref.table.two_by_two}}"),
    )  # fmt: skip
    assert "shown in Table 1-Table 3." in _assembled_main(project)
    said = dict(_ref_findings(project))
    assert sorted(said) == ["cited-out-of-order", "display-not-cited"], said
    assert said["display-not-cited"].startswith("Table 2 ")


@pytest.mark.parametrize(
    ("written", "read_as"),
    [
        # the word names a figure
        ("Figure {{num.table.baseline}}", "a figure of the main text"),
        # the words name the supplement
        ("Supplementary Table {{num.table.baseline}}", "a table of the supplement"),
        ("{{ref.table.baseline}} in the Supplement", "a table of the supplement"),
        ("Supplementary {{ref.table.baseline}}", "a table of the supplement"),
        # no word at all
        ("number {{num.table.baseline}}", "no word before it"),
    ],
)
def test_words_around_a_bound_pointer_that_point_elsewhere_are_said(
    project: Path, written: str, read_as: str
) -> None:
    _rewrite(project, ("shown in Table 1.", f"shown in {written}."))
    # Read as pointing elsewhere, it cites nothing, so Table 1 is cited nowhere, and Table 2
    # first.
    consequences = ("display-not-cited", "cited-out-of-order")
    said = [s for s in _ref_findings(project) if s[0] not in consequences]
    assert [code for code, _ in said] == ["pointer-word-mismatch"], said
    assert read_as in said[0][1], said


def test_a_word_mismatch_fails_from_the_internal_review(project: Path) -> None:
    """Like a typed pointer that names the wrong table: the words go stale as tables move."""
    from manuscript_guard.cli import _run_gates

    _rewrite(project, ("shown in Table 1.", "shown in Figure {{num.table.baseline}}."))
    drafting, *_ = _run_gates(project, stage="drafting")
    assert [f.severity for f in drafting.findings if f.code == "pointer-word-mismatch"] == [
        "info"
    ]
    reviewing, *_ = _run_gates(project, stage="internal-review")
    assert "pointer-word-mismatch" in codes(reviewing)


def _assembled_all(root: Path) -> dict[str, str]:
    from manuscript_guard.build.assemble import assemble

    project, _ = load_project(root)
    namespace, results, _literature, _ = load_namespace(project)
    assembled, _report = assemble(project, namespace, results)
    # Spaces as pandoc reads them: "Table\nS2" bound is "{{ref...}}" on one line.
    return {item.path.name: " ".join(item.text.split()) for item in assembled}


def test_bind_pointers_binds_each_typed_pointer_and_prints_the_same(
    project: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    """`bind --pointers --apply` on the example: every typed pointer becomes the binding that
    prints it, a list's numbers each a num, and the build prints what it printed before,
    word for word, with nothing for G2 to say."""
    from manuscript_guard.cli import main

    _rewrite(project, ("in Table 2, so", "in Tables 1 and 2, so"))
    before = _assembled_all(project)
    assert main(["bind", str(project), "--pointers"]) == 0
    assert "{{ref.table.baseline}}" in capsys.readouterr().out
    assert main(["bind", str(project), "--pointers", "--apply"]) == 0
    text = main_md(project).read_text(encoding="utf-8")
    for bound in ("shown in {{ref.table.baseline}}.", "{{ref.figure.forest}}",
                  "Tables {{num.table.baseline}} and {{num.table.two_by_two}}, so",
                  "published in\n{{ref.table.outcome_codes}},", "{{ref.table.model_adjusted}}"):
        assert bound in text, bound
    supplement = project / "manuscript" / "supplementary" / "S1_code_lists.md"
    assert "## {{ref.table.outcome_codes}}. Code lists" in supplement.read_text(encoding="utf-8")
    assert _assembled_all(project) == before
    assert _ref_findings(project) == []
    capsys.readouterr()
    assert main(["bind", str(project), "--pointers"]) == 0
    assert "no typed pointer" in capsys.readouterr().out


def test_bind_pointers_offers_nothing_that_would_print_otherwise(project: Path) -> None:
    """"Supplementary Table 1" under the default form would print "Table S1": not offered.
    Nor is a range that names a table it does not write, "Tables 1-3", nor a figure sent as
    a file. The supplement's headings, "## Table S1. Code lists", are."""
    from manuscript_guard.binding import typed_pointers

    _rewrite(
        project,
        ("Table S1, emitted", "Supplementary Table 1, emitted"),
        ("in Table 2, so", "in Tables 1\N{EN DASH}3, so"),
    )
    _declare(project, "displays: {figures_as_files: 1}")
    offered = sorted(item.text for item in typed_pointers(load_project(project)[0]))
    assert offered == sorted(["Table 1", "Table S1", "Table S2", "Table\nS2"]), offered


def test_bind_pointers_offers_another_paper_s_table_and_a_count_after_a_list(
    project: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    """A known gap (DESIGN.md, Known gaps, "`bind --pointers` offers what G2 reads as a
    pointer"): "Table 2 of Smith et al." is offered as this paper's Table 2, and the 2 of
    "in Tables 1, 2 patients" as a table's number. The list is printed and nothing written
    before `--apply`; `--only` takes one line; applied, either prints as typed, and another
    number once the tables move."""
    from manuscript_guard.binding import label, typed_pointers
    from manuscript_guard.cli import main

    _rewrite(
        project,
        ("can reconstruct it.", "can reconstruct it. Table 2 of Smith et al. gave the same."),
        ("# Discussion", "In Tables 1, 2 patients were excluded.\n\n# Discussion"),
    )
    items = typed_pointers(load_project(project)[0])
    lines = main_md(project).read_text(encoding="utf-8").split("\n")
    smith = [i for i in items if "Smith" in lines[i.line - 1]]
    listed = [i for i in items if "patients were excluded" in lines[i.line - 1]]
    assert [(i.text, i.certain) for i in smith] == [("Table 2", "ref.table.two_by_two")]
    assert [(i.text, i.certain) for i in listed] == [
        ("1", "num.table.baseline"), ("2", "num.table.two_by_two")
    ]
    before = main_md(project).read_text(encoding="utf-8")
    printed = _assembled_all(project)["main.md"]
    capsys.readouterr()
    assert main(["bind", str(project), "--pointers"]) == 0
    out = capsys.readouterr().out
    assert label(smith[0], project) in out and label(listed[1], project) in out
    assert main_md(project).read_text(encoding="utf-8") == before
    assert main(["bind", str(project), "--pointers", "--apply", "--only",
                 label(smith[0], project)]) == 0  # fmt: skip
    text = main_md(project).read_text(encoding="utf-8")
    assert "{{ref.table.two_by_two}} of Smith et al." in text
    assert "In Tables 1, 2 patients were excluded." in text
    assert _assembled_all(project)["main.md"] == printed
    assert main(["bind", str(project), "--pointers", "--apply", "--only",
                 label(listed[1], project)]) == 0  # fmt: skip
    text = main_md(project).read_text(encoding="utf-8")
    assert "In Tables {{num.table.baseline}}, {{num.table.two_by_two}} patients" in text
    assert "In Tables 1, 2 patients were excluded." in _assembled_all(project)["main.md"]
    assert _assembled_all(project)["main.md"] == printed
    _rewrite(
        project,
        ("{{table.baseline}}", "{{table.swapped}}"),
        ("{{table.two_by_two}}\n", "{{table.baseline}}\n"),
        ("{{table.swapped}}", "{{table.two_by_two}}"),
    )
    moved = _assembled_all(project)["main.md"]
    assert "Table 1 of Smith et al." in moved
    assert "In Tables 2, 1 patients were excluded." in moved


# ---------------------------------------------------------------------- captions numbered
# The build prints an emitted table's caption after the table's number, "Table 2. ...", and
# G2 refuses a caption beside a display that names another (Basile's choice, 2026-10-20).


def _assembled_raw(root: Path) -> dict[str, str]:
    from manuscript_guard.build.assemble import assemble

    project, _ = load_project(root)
    namespace, results, _literature, _ = load_namespace(project)
    assembled, report = assemble(project, namespace, results)
    assert report.ok, report.findings
    return {item.path.name: item.text for item in assembled}


def _emit_caption(root: Path, key: str, caption: str | None) -> None:
    """The example's analysis as if it had emitted this caption for table `key`."""
    fragment = root / "results" / "01_disproportionality.json"
    document = json.loads(fragment.read_text(encoding="utf-8"))
    if caption is None:
        document["tables"][key].pop("caption", None)
    else:
        document["tables"][key]["caption"] = caption
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)


def test_the_build_numbers_an_emitted_table_caption(project: Path) -> None:
    printed = _assembled_raw(project)
    assert ": Table 1. Reports by drug group." in printed["main.md"]
    assert ": Table 2. Contingency table underlying" in printed["main.md"]
    assert ": Table S1. Terms used to identify" in printed["S1_code_lists.md"]
    assert ": Table S2. Adjusted model." in printed["S1_code_lists.md"]
    _journal_forms(project, '{supplementary_table: "eTable {n}"}')
    assert ": eTable 1. Terms used to identify" in _assembled_raw(project)["S1_code_lists.md"]
    _emit_caption(project, "baseline", None)
    assert "\n: Table 1\n" in _assembled_raw(project)["main.md"] + "\n"


@pytest.mark.parametrize(
    ("caption", "said"),
    [
        ("Table 1. Reports by drug group.", False),
        ("Table 3. Reports by drug group.", True),
        ("Table S1: Reports by drug group.", True),
    ],
)
def test_an_emitted_caption_that_numbers_itself_is_printed_once_and_held(
    project: Path, caption: str, said: bool
) -> None:
    """A caption the analysis numbered already is printed as it is, not "Table 1. Table 1.",
    and G2 holds its number to the table's."""
    _emit_caption(project, "baseline", caption)
    assert f"\n: {caption}\n" in _assembled_raw(project)["main.md"] + "\n"
    found = [s for s in _ref_findings(project) if s[0] == "caption-names-another"]
    assert bool(found) == said, found


@pytest.mark.parametrize(
    ("change", "said"),
    [
        # typed above a table, naming another
        (("{{table.two_by_two}}", "**Table 1.** Counts\n\n{{table.two_by_two}}"), True),
        # typed above it, naming it
        (("{{table.two_by_two}}", "**Table 2.** Counts\n\n{{table.two_by_two}}"), False),
        # typed below a table
        (("{{table.two_by_two}}", "{{table.two_by_two}}\n\nTable 1: counts by group."), True),
        # under a figure
        (("{{figure.forest}}", "{{figure.forest}}\n\nFigure 2. The estimate."), True),
        (("{{figure.forest}}", "{{figure.forest}}\n\nFigure 1. The estimate."), False),
        # a ref in the caption, to another figure or to this one
        (("{{figure.forest}}", "{{figure.forest}}\n\n{{ref.figure.forest}}. The estimate."),
         False),
        # a heading straight above a table
        (("{{table.baseline}}", "## Table 2. Characteristics\n\n{{table.baseline}}"), True),
        # prose between a heading and its table: no caption of it
        (("{{table.baseline}}", "## Table 2. Characteristics\n\nAs below.\n\n{{table.baseline}}"),
         False),
    ],
)  # fmt: skip
def test_a_caption_beside_a_display_that_names_another_is_said(
    project: Path, change: tuple[str, str], said: bool
) -> None:
    _rewrite(project, change)
    found = [s for s in _ref_findings(project) if s[0] == "caption-names-another"]
    assert bool(found) == said, _ref_findings(project)


