def test_a_field_named_type_leaves_the_entry_s_type(tmp_path: Path) -> None:
    """Round 2 of #261: `type = {chapter}` took the place of `@inbook`, and the entry was
    read as a type nothing requires anything of."""
    from manuscript_guard.literature.bibfile import read_entries

    bib = tmp_path / "references.bib"
    bib.write_text("@inbook{k,\n  type = {Chapter},\n  author = {A},\n}\n", encoding="utf-8")
    assert read_entries(bib)["k"]["type"] == "inbook"
    # Round 1 of #345: the field is kept beside it, for the readers that want it.
    assert read_entries(bib)["k"]["type_field"] == "Chapter"


# One work cited under two keys: the reference list prints it twice.


def _both_have(
    root: Path, first: dict[str, str], second: dict[str, str], types: tuple[str, str] = ("", "")
) -> None:
    """Give each of the example's two references the fields named, and the entry type. Their
    volumes go, so that a volume is only the one a test gives."""
    bib = root / "literature" / "references.bib"
    text = bib.read_text(encoding="utf-8")
    text = text.replace("  volume  = {12},\n", "").replace("  volume  = {7},\n", "")
    keys = ("fictionalHepaticCohort2021", "fictionalClassSignal2019")
    for key, fields, kind in zip(keys, (first, second), types, strict=True):
        opening = f"@article{{{key},\n"
        added = "".join(f"  {name} = {{{value}}},\n" for name, value in fields.items())
        text = text.replace(opening, "@" + (kind or "article") + opening[8:] + added, 1)
    bib.write_text(text, encoding="utf-8")


def _duplicate_findings(root: Path) -> list[tuple[str, str, str]]:
    return [
        (f.code, f.severity, f.message)
        for f in _g7(root).findings
        if f.code in ("reference-duplicate", "reference-title-duplicate")
    ]


@pytest.mark.parametrize(
    ("first", "second", "named"),
    [
        ({"doi": "10.5555/x.1"}, {"doi": "https://doi.org/10.5555/X.1."}, "DOI"),
        ({"pmid": "31000001"}, {"pmid": "031000001"}, "PMID"),
        ({"pmcid": "PMC1234"}, {"pmcid": "pmc1234"}, "PMCID"),
        ({"isbn": "0-306-40615-2"}, {"isbn": "978-0-306-40615-7"}, "ISBN"),
        # Round 2 of #261: one volume written with its word and without.
        ({"isbn": "0-306-40615-2", "volume": "1"},
         {"isbn": "978-0-306-40615-7", "volume": "Vol. 1"}, "ISBN"),
        # Round 1 of #249: a resolver with `www.`, and a scheme with no colon.
        ({"doi": "10.5555/x.1"}, {"doi": "https://www.doi.org/10.5555/x.1"}, "DOI"),
        ({"doi": "10.5555/x.1"}, {"doi": "DOI 10.5555/X.1"}, "DOI"),
    ],
)  # fmt: skip
def test_one_work_cited_under_two_keys_fails(
    project: Path, first: dict, second: dict, named: str
) -> None:
    _both_have(project, first, second, ("book", "collection") if named == "ISBN" else ("", ""))
    said = _duplicate_findings(project)
    assert [(code, severity) for code, severity, _ in said] == [("reference-duplicate", "fail")]
    assert f"by the same {named}" in said[0][2]


def test_one_work_under_two_keys_fails_from_internal_review(project: Path) -> None:
    from manuscript_guard.policy import DRAFTING, INTERNAL_REVIEW, apply_stage

    _both_have(project, {"doi": "10.5555/x.1"}, {"doi": "10.5555/x.1"})
    report = _g7(project)
    drafting, _ = apply_stage(report, DRAFTING)
    assert "reference-duplicate" not in {f.code for f in drafting.failures}
    reviewed, _ = apply_stage(report, INTERNAL_REVIEW)
    assert "reference-duplicate" in {f.code for f in reviewed.failures}


def test_two_entries_with_one_title_are_a_warning(project: Path) -> None:
    bib = project / "literature" / "references.bib"
    bib.write_text(
        bib.read_text(encoding="utf-8").replace(
            "A disproportionality signal for a fictional drug class",
            "HEPATIC INJURY IN A FICTIONAL NATIONAL COHORT, 2010--2019",
            1,
        ),
        encoding="utf-8",
    )
    said = _duplicate_findings(project)
    assert [(code, severity) for code, severity, _ in said] == [
        ("reference-title-duplicate", "warn")
    ]  # fmt: skip


_ISBN = "978-0-306-40615-7"


@pytest.mark.parametrize(
    ("types", "first", "second"),
    [
        # Two chapters of one book carry its ISBN, or its DOI.
        (("incollection", "incollection"), {"isbn": _ISBN}, {"isbn": "0-306-40615-2"}),
        (("inbook", "inbook"), {"doi": "10.5555/book.1"}, {"doi": "10.5555/book.1"}),
        # Two papers of one proceedings volume.
        (("inproceedings", "inproceedings"), {"isbn": _ISBN}, {"isbn": _ISBN}),
        # A book cited beside one of its chapters.
        (
            ("book", "incollection"),
            {"isbn": _ISBN, "doi": "10.5555/book.1"},
            {"isbn": _ISBN, "doi": "10.5555/book.1"},
        ),
        # Two volumes of one set, under the set's ISBN.
        (("book", "book"), {"isbn": _ISBN, "volume": "1"}, {"isbn": _ISBN, "volume": "2"}),
        # An ISBN on an article or a misc entry names no book that is cited.
        (("article", "misc"), {"isbn": _ISBN}, {"isbn": _ISBN}),
    ],
)
def test_parts_of_one_book_are_two_works(
    project: Path, types: tuple[str, str], first: dict, second: dict
) -> None:
    _both_have(project, first, second, types)
    assert _duplicate_findings(project) == []


_FAIL = [("reference-duplicate", "fail")]
_WARN = [("reference-title-duplicate", "warn")]


@pytest.mark.parametrize(
    ("types", "first", "second", "title", "said"),
    [
        # A preprint and its article: no identifier in common, titles that differ.
        (("", ""), {"doi": "10.5555/pre.1"}, {"doi": "10.5555/art.1"}, None, []),
        # A title of fewer than four words is not compared; one of four is.
        (("", ""), {}, {}, "Hepatic injury reported", []),
        (("", ""), {}, {}, "Hepatic injury in cohorts", _WARN),
        # A chapter cited twice, by its DOI: found by its title only, and a warning.
        (("incollection", "incollection"), {"doi": "10.5555/ch.1"}, {"doi": "10.5555/ch.1"},
         None, []),
        (("incollection", "incollection"), {"doi": "10.5555/ch.1"}, {"doi": "10.5555/ch.1"},
         "A chapter on hepatic injury", _WARN),
        # A conference paper cited twice, by its DOI: likewise.
        (("inproceedings", "inproceedings"), {"doi": "10.5555/cp.1"}, {"doi": "10.5555/cp.1"},
         None, []),
        (("inproceedings", "inproceedings"), {"doi": "10.5555/cp.1"}, {"doi": "10.5555/cp.1"},
         "A conference paper on hepatic injury", _WARN),
        # A work and its translation: no identifier, and a title in another language.
        (("", ""), {}, {}, ("Hepatic injury in a national cohort",
                            "Les atteintes hépatiques dans une cohorte nationale"), []),
        # A book cited twice with a volume in one entry only, or "I" and "1".
        (("book", "book"), {"isbn": _ISBN, "volume": "1"}, {"isbn": _ISBN}, None, []),
        (("book", "book"), {"isbn": _ISBN, "volume": "I"}, {"isbn": _ISBN, "volume": "1"},
         None, []),
        (("book", "book"), {"isbn": _ISBN, "volume": "Vol. 1"}, {"isbn": _ISBN, "volume": "1"},
         None, _FAIL),
        # A `%` and two hex digits of a printable character are read as that character.
        (("", ""), {"doi": "10.5555/x%2Ey"}, {"doi": "10.5555/x.y"}, None, _FAIL),
    ],
    ids=["preprint-and-article", "title-of-three-words", "title-of-four-words",
         "chapter-by-doi", "chapter-by-title", "conference-paper-by-doi",
         "conference-paper-by-title", "a-translation", "volume-in-one", "volume-i-and-1",
         "volume-with-its-word", "percent-escape"],
)  # fmt: skip
def test_two_keys_for_one_work_are_found_by_an_identifier_or_a_title_alone(
    project: Path, types: tuple[str, str], first: dict, second: dict,
    title: str | tuple[str, str] | None, said: list,
) -> None:
    """A known gap (DESIGN.md, Known gaps, "Two keys for one work are found by an identifier
    or a title, and only among what is cited"): two entries of one work with no identifier
    in common and titles that differ, a preprint and its article or a translation, are not
    found, nor a title of fewer than four words; a chapter or a conference paper is found by
    its title alone, a warning; a volume is compared without its word and otherwise as
    written; and a DOI's `%2E` is read as a full stop."""
    _both_have(project, first, second, types)
    if title is not None:
        bib = project / "literature" / "references.bib"
        text = bib.read_text(encoding="utf-8")
        titles = (title, title) if isinstance(title, str) else title
        for written, new in zip(("Hepatic injury in a fictional national cohort, 2010--2019",
                                 "A disproportionality signal for a fictional drug class"),
                                titles, strict=True):  # fmt: skip
            text = text.replace(written, new, 1)
        bib.write_text(text, encoding="utf-8")
    assert [(code, severity) for code, severity, _ in _duplicate_findings(project)] == said


def test_different_works_and_an_uncited_duplicate_say_nothing(project: Path) -> None:
    _both_have(project, {"doi": "10.5555/x.1"}, {"doi": "10.5555/x.2"})
    assert _duplicate_findings(project) == []
    bib = project / "literature" / "references.bib"
    bib.write_text(
        bib.read_text(encoding="utf-8")
        + "\n@article{uncitedCopy2021,\n  doi = {10.5555/x.1},\n  title = {T},\n}\n",
        encoding="utf-8",
    )
    assert _duplicate_findings(project) == []


def _zotero(monkeypatch, items: list[dict], better_bibtex: str = "6.7.140") -> None:
    from test_zotero import FakeBBT

    from manuscript_guard.zotero import client, reset_cache

    reset_cache()
    monkeypatch.setattr(client, "rpc", FakeBBT(items, better_bibtex=better_bibtex))
    monkeypatch.setattr("manuscript_guard.gates.citations.available", lambda: True)


def test_a_key_better_bibtex_8_keeps_is_pinned_and_one_before_it_is_not(
    project: Path, monkeypatch
) -> None:
    """From Better BibTeX 8 every key is kept in Zotero's own Citation Key field and Extra
    carries no pin (the athlete-leakage study, Zotero 9 with 9.0.77): G7 failed every key it
    cited, pinned or not. Before 8, a key with no pin in Extra still fails."""
    from test_zotero import CLASS, HEPATIC, csl

    _zotero(monkeypatch, [csl(HEPATIC, False), csl(CLASS, False)], better_bibtex="9.0.77")
    assert "citation-key-unpinned" not in codes(_g7(project, closed=False))
    _zotero(monkeypatch, [csl(HEPATIC, False), csl(CLASS, False)], better_bibtex="7.0.5")
    unpinned = [f for f in _g7(project, closed=False).failures
                if f.code == "citation-key-unpinned"]  # fmt: skip
    assert len(unpinned) == 2 and "Better BibTeX before 8" in unpinned[0].hint, unpinned


def test_an_unpinned_cited_key_is_caught(project: Path, monkeypatch) -> None:
    from test_zotero import CLASS, HEPATIC, csl

    _zotero(monkeypatch, [csl(HEPATIC, True), csl(CLASS, False)])
    report = _g7(project, closed=False)
    unpinned = [f for f in report.failures if f.code == "citation-key-unpinned"]
    assert [f.message for f in unpinned] == [f"@{CLASS} is not pinned in Zotero"]
    assert f"Citation Key: {CLASS}" in unpinned[0].hint


def test_a_cited_key_carried_by_two_items_is_caught(project: Path, monkeypatch) -> None:
    """The duplicate that made Better BibTeX refuse the whole export in a real project."""
    from test_zotero import CLASS, HEPATIC, csl

    _zotero(monkeypatch, [csl(HEPATIC, True), csl(CLASS, True), csl(CLASS, False)])
    report = _g7(project, closed=False)
    assert "citation-key-ambiguous" in codes(report)
    assert "citation-unresolved" not in codes(report)


def test_a_wrapped_citation_to_a_missing_item_is_caught(project: Path, monkeypatch) -> None:
    """The first key of a group that wraps onto a new line was invisible to G7 and to
    sync-bib (neither the bracketed nor the narrative pattern found it)."""
    from test_zotero import CLASS, HEPATIC, csl

    main = main_md(project)
    wrapped = f"\nA wrapped claim [@ghostKey2020;\n@{HEPATIC}].\n"
    main.write_text(main.read_text(encoding="utf-8") + wrapped, encoding="utf-8")
    _zotero(monkeypatch, [csl(HEPATIC, True), csl(CLASS, True)])
    report = _g7(project, closed=False)
    assert any(
        f.code == "citation-unresolved" and "ghostKey2020" in f.message for f in report.failures
    )


def test_g7_names_a_cited_work_as_the_manuscript_cites_it(project: Path, monkeypatch) -> None:
    """A LaTeX paper of the corpus round (2026-10-23) was told of `@key`, which its author
    never typed: G7 names a work with the command it is cited by, `\\citep{key}`, and the
    keys it may have meant so too, as it names a Markdown paper's `@key`."""
    from test_zotero import CLASS, HEPATIC, csl

    near = "fictionalHepaticCohort2012"
    main = main_md(project)
    main.write_text(main.read_text(encoding="utf-8") + f"\nA claim [@{near}].\n",
                    encoding="utf-8")  # fmt: skip
    (found,) = [f for f in _g7(project).failures if f.code == "citation-unresolved"]
    assert found.message == f"@{near} matches nothing in the library", found.message
    assert found.hint.startswith(f"did you mean @{HEPATIC}"), found.hint

    entry = _twin(project)
    _into_results(entry, f"A claim \\citep[p.~2]{{{near}}}.")
    (found,) = [f for f in _g7(project).failures if f.code == "citation-unresolved"]
    assert found.message == f"\\citep{{{near}}} matches nothing in the library", found.message
    assert found.hint.startswith(f"did you mean \\citep{{{HEPATIC}}}"), found.hint
    assert "@" not in found.message + found.hint

    _zotero(monkeypatch, [csl(HEPATIC, True), csl(CLASS, False)])
    report = _g7(project, closed=False)
    unpinned = [f.message for f in report.failures if f.code == "citation-key-unpinned"]
    assert unpinned == [f"\\cite{{{CLASS}}} is not pinned in Zotero"], unpinned


def test_an_e_mail_address_is_no_citation_and_a_key_beside_one_still_is(project: Path) -> None:
    """A corresponding author's address, in a mailto link as Word writes one and in a span:
    `check` read the host of each as a key, "@gmail.com matches nothing in the library",
    and failed the submission on it. Pandoc reads neither as a citation. A key the library
    does not hold, in a group beside an address, is still caught."""
    main = main_md(project)
    addresses = (
        "\n*Corresponding author*:\n[*first.last@gmail.com*](mailto:first.last@gmail.com)\n\n"
        "1\\. [Research Centre. someone@centre.org.gt]{.mark}\n\n"
        "Write to someone@centre.org.gt or [name@example.org].\n"
    )
    main.write_text(main.read_text(encoding="utf-8") + addresses, encoding="utf-8")
    assert "citation-unresolved" not in codes(_g7(project))

    main.write_text(main.read_text(encoding="utf-8") + "\nAs shown [name@example.org; "
                    "@ghostKey2020].\n", encoding="utf-8")  # fmt: skip
    unresolved = [f.message for f in _g7(project).failures if f.code == "citation-unresolved"]
    assert unresolved == ["@ghostKey2020 matches nothing in the library"]


# An entry of `references.bib` a Word paper cites only as typed text. `init --from` makes a
# group a key only if each of its parts names an entry, so one unknown author leaves the
# rest typed, and G7 said of them that nothing cites them (the real-paper corpus, window C:
# 24 false findings in 8 papers against 4 true). The author's decisions of 2026-11-23 and
# 2026-11-24: a note that says so and what `sync-bib` would do, for a citation in brackets
# whose whole part is the entry's names and year; every other entry stays a warning.

_TYPED_ONLY_BIB = """
@article{imaginary2018,
  author = {Imaginary, Anne}, title = {One}, journal = {J}, year = {2018},
}
@article{dupont2019,
  author = {Dupont, Anne and Second, Bea}, title = {Two}, journal = {J}, year = {2019},
}
@article{walker2020,
  author = {Walker, Anne and Second, Bea and Third, Cleo}, title = {Three}, journal = {J},
  year = {2020},
}
@article{vanderberg2014,
  author = {{van der Berg}, Anne and Second, Bea and Third, Cleo}, title = {Four},
  journal = {J}, year = {2014},
}
@article{who2020,
  author = {{World Health Organization}}, title = {Five}, journal = {J}, year = {2020},
}
"""


def _uncited(root: Path, typed: str, bib: str = _TYPED_ONLY_BIB) -> dict:
    """G7's `reference-uncited` findings by key, the manuscript holding `typed` and
    `references.bib` the entries of `bib` beside its own."""
    path = root / "literature" / "references.bib"
    path.write_text(path.read_text(encoding="utf-8") + bib, encoding="utf-8")
    main = main_md(root)
    main.write_text(main.read_text(encoding="utf-8") + f"\n{typed}\n", encoding="utf-8")
    found = [f for f in _g7(root).findings if f.code == "reference-uncited"]
    return {re.search(r"@(\w+)", f.message).group(1): f for f in found}


def _one_entry(key: str, author: str, year: int = 2020, title: str = "T") -> str:
    return (f"\n@article{{{key},\n  author = {{{author}}}, title = {{{title}}},\n"
            f"  year = {{{year}}},\n}}\n")  # fmt: skip


@pytest.mark.parametrize(
    ("typed", "key", "shown"),
    [
        ("A claim (Imaginary, 2018).", "imaginary2018", "Imaginary, 2018"),
        ("A claim (Dupont & Second, 2019).", "dupont2019", "Dupont & Second, 2019"),
        ("A claim (Dupont and Second, 2019).", "dupont2019", "Dupont and Second, 2019"),
        ("A claim (Walker et al., 2020).", "walker2020", "Walker et al., 2020"),
        ("A claim (Walker, Second, & Third, 2020).", "walker2020",
         "Walker, Second, & Third, 2020"),
        ("A claim (Walker, Second, and Third, 2020).", "walker2020",
         "Walker, Second, and Third, 2020"),
        ("A claim (van der Berg et al., 2014).", "vanderberg2014",
         "van der Berg et al., 2014"),
        # A group with a work the list lacks: why the import left it typed.
        ("A claim (Nobody, 2001; Imaginary, 2018).", "imaginary2018", "Imaginary, 2018"),
        ("A claim (Imaginary, 2018; Nobody, 2001).", "imaginary2018", "Imaginary, 2018"),
        # After the year, a page or further years.
        ("A claim (Imaginary, 2018, p. 45).", "imaginary2018", "Imaginary, 2018, p. 45"),
        ("A claim (Imaginary, 2018, pp. 57-58).", "imaginary2018",
         "Imaginary, 2018, pp. 57-58"),
        ("A claim (Imaginary, 2011, 2014, 2018).", "imaginary2018",
         "Imaginary, 2011, 2014, 2018"),
        ("A claim (Imaginary, 2018, 2021).", "imaginary2018", "Imaginary, 2018, 2021"),
    ],
)
def test_an_entry_cited_only_as_typed_text_is_a_note_with_what_sync_bib_would_do(
    project: Path, typed: str, key: str, shown: str
) -> None:
    """The entry is cited, so G7 no longer says nothing cites it: it is a note that names the
    words that cite it and says that `sync-bib`, which writes the file from the citation keys
    alone, would drop it. The code is the same, and so is the key: a verdict on the old
    finding pairs with this one."""
    from manuscript_guard.findings import INFO, WARN, Finding

    found = _uncited(project, typed)[key]
    assert found.severity == INFO, found
    assert f'cites only as typed text ("{shown}")' in found.message, found.message
    assert "no citation key points to it" in found.message, found.message
    assert "`sync-bib` would drop it" in found.message, found.message
    assert f"[@{key}]" in found.hint and "Zotero" in found.hint, found.hint
    was = Finding(gate="G7", code="reference-uncited", severity=WARN, path=found.path,
                  message=f"references.bib holds @{key}, which nothing cites")  # fmt: skip
    assert was.keyed().from_context and found.key == was.key, (found.key, was.key)
    said = found.as_dict()
    assert said["key"] == was.as_dict()["key"] and said["key_from"] == "context", said
    assert set(said) == set(was.as_dict()), said


@pytest.mark.parametrize(
    ("typed", "key"),
    [
        ("Nothing names it.", "imaginary2018"),
        ("A claim (Imaginary, 2017).", "imaginary2018"),
        ("A claim (Fictional, 2018).", "imaginary2018"),
        # The first author is the entry's and the citation is of another work.
        ("A claim (Imaginary & Other, 2018).", "imaginary2018"),
        ("A claim (Imaginary et al., 2018).", "imaginary2018"),
        ("A claim (Dupont, 2019).", "dupont2019"),
        ("A claim (Dupont & Other, 2019).", "dupont2019"),
        ("A claim (Dupont et al., 2019).", "dupont2019"),
        ("A claim (Walker, 2020).", "walker2020"),
        ("A claim (Walker & Second, 2020).", "walker2020"),
        ("A claim (Walker, Second, & Other, 2020).", "walker2020"),
        ("A claim (Berg et al., 2014).", "vanderberg2014"),
        ("A claim (Van der Berg et al., 2014).", "vanderberg2014"),
        # A citation in the sentence is not read.
        ("Imaginary (2018) wrote.", "imaginary2018"),
        ("As Imaginary (2018) wrote.", "imaginary2018"),
        ("As Imaginary (2011, 2018) wrote.", "imaginary2018"),
        ("As Dupont and Second (2019) wrote.", "dupont2019"),
        ("Dupont and Second's (2019) work.", "dupont2019"),
        ("As Walker et al. (2020) wrote.", "walker2020"),
        ("Recently, Walker and colleagues (2020) wrote.", "walker2020"),
        ("As Brown and Imaginary (2018) wrote.", "imaginary2018"),
        ("Professor Imaginary (2018) wrote.", "imaginary2018"),
        ("Earlier work differs. Garcia Imaginary (2018) found this.", "imaginary2018"),
        ("As al-Rashid, Imaginary (2018) wrote.", "imaginary2018"),
        ("As Brown (ed.) and Imaginary (2018) wrote.", "imaginary2018"),
        # Anything before or between the names, or no comma before the year.
        ("A claim (e.g., Imaginary, 2018).", "imaginary2018"),
        ("A claim (see also Imaginary, 2018).", "imaginary2018"),
        ("A claim (A. Imaginary, 2018).", "imaginary2018"),
        ("A claim (B. Imaginary, 2018).", "imaginary2018"),
        ("A claim (Garcia Imaginary, 2018).", "imaginary2018"),
        ("A claim (Brown, Imaginary, 2018).", "imaginary2018"),
        ("A claim (Walker and colleagues, 2020).", "walker2020"),
        ("A claim (Imaginary 2018).", "imaginary2018"),
        # A piece of a bracket beside one that is no citation with its own year.
        ("A claim (Silva; Imaginary, 2018).", "imaginary2018"),
        ("A claim (*d* = 0.17; Imaginary, 2018).", "imaginary2018"),
        ("A claim (Imaginary, 2018; see the text).", "imaginary2018"),
        # A month, a letter the entry does not have, and what is not a page after the year.
        ("In (March, 2018) it rained.", "imaginary2018"),
        ("A claim (Imaginary, 2018a).", "imaginary2018"),
        ("A claim (Imaginary, 2018, Table 2).", "imaginary2018"),
        ("A claim (Imaginary, 2018, p. 4, Table 2).", "imaginary2018"),
        # In a comment, in code, around code, or in the typed reference list itself.
        ("<!-- A claim (Imaginary, 2018). -->", "imaginary2018"),
        ("`(Imaginary, 2018)`", "imaginary2018"),
        ("A claim (Imaginary, `x` 2018).", "imaginary2018"),
        ("# References\n\nImaginary, A. (2018). One. *J*, *1*, 1--2.", "imaginary2018"),
        ("# References\n\nOther, A. (2001). On (Imaginary, 2018). *J*, *1*, 1--2.",
         "imaginary2018"),
    ],
)
def test_an_entry_nothing_cites_even_as_typed_text_stays_a_warning(
    project: Path, typed: str, key: str
) -> None:
    """A citation counts only in brackets, and only where its whole part is the entry's names
    and year, by the rule `init --from` makes a key by."""
    from manuscript_guard.findings import WARN

    found = _uncited(project, typed)[key]
    assert found.severity == WARN, found
    assert found.message == f"references.bib holds @{key}, which nothing cites", found.message


