# A literature value with a blank field. `source_file: ""` was passed over by both gates:
# `check --stage drafting` added no finding, and the value was simply not counted as
# verified, so the run claimed every value it had checked was verified.

_BLANK_FIELDS = [
    ("ledger", "source_file", ""),
    ("ledger", "source_file", "   "),
    ("ledger", "locator", ""),
    ("ledger", "locator", " "),
    ("ledger", "quote", " "),
    ("attested", "attested_by", " "),
    ("attested", "statement", "\t"),
    ("attested", "source", " "),
    ("attested", "locator", " "),
]


@pytest.mark.parametrize(
    ("file", "field", "blank"),
    _BLANK_FIELDS,
    ids=[f"{file}-{field}-{len(blank)}" for file, field, blank in _BLANK_FIELDS],
)
def test_a_literature_value_with_a_blank_field_fails(
    project: Path, file: str, field: str, blank: str
) -> None:
    from manuscript_guard.cli import _run_gates

    path = project / "literature" / f"{file}.yaml"
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    document["entries"][0][field] = blank
    path.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")

    report, _project, _stage, _deferred = _run_gates(project, stage="drafting")
    assert any(
        f.code == "schema-violation" and f"entries/0/{field}" in f.message
        for f in report.failures
    ), report.render(project)


@pytest.mark.parametrize(
    ("signature", "refused"),
    [(chr(0x200B), False), (chr(0xFEFF), False), (" ", True)],
    ids=["zero-width-space", "byte-order-mark", "a-space"],
)
def test_an_attestation_signed_with_an_invisible_character_passes(
    project: Path, signature: str, refused: bool
) -> None:
    """A known gap (DESIGN.md, Known gaps, "A field the literature schemas call blank is one
    of white space only"): the schemas' `\\S` takes a zero-width space or a byte-order mark
    for a character, so `attested_by` made of either passes the schema and G7 as a
    signature that shows nothing, where one of white space fails."""
    from manuscript_guard.cli import _run_gates

    path = project / "literature" / "attested.yaml"
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    document["entries"][0]["attested_by"] = signature
    path.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")

    report, _project, _stage, _deferred = _run_gates(project, stage="drafting")
    about = [(f.code, f.message) for f in report.failures
             if "attested" in f.message or "agency.withdrawn_estimate" in f.message]  # fmt: skip
    if refused:
        # Refused, the value is not loaded, and the sentence binding it is unresolved too.
        assert [code for code, _message in about][0] == "schema-violation", about
        assert "entries/0/attested_by" in about[0][1]
    else:
        assert about == []
        assert _literature_report(project).ok


def _literature_report(root: Path, change=None):
    """G7's two literature checks, run as `check` runs them; `change` edits the loaded
    values first, to reach the gates with what the schema would have refused."""
    from manuscript_guard.gates import check_citations, check_literature_chain

    project, _ = load_project(root)
    _namespace, _results, literature, load_report = load_namespace(project)
    if change is not None:
        literature = change(literature)
    return merge_all(
        [
            load_report,
            check_citations(project, literature),
            check_literature_chain(project, literature),
        ]
    )


def _without_source(literature):
    from dataclasses import replace

    from manuscript_guard.contracts.literature import Literature

    key = "background.reported_incidence"
    value = literature.values[key]
    changed = replace(value, detail={**value.detail, "source_file": " "})
    return Literature({**literature.values, key: changed}, literature.root)


def _source_removed(root: Path) -> None:
    (root / "literature" / "sources" / "fictionalHepaticCohort2021.txt").unlink()


def _misquoted(root: Path) -> None:
    source = root / "literature" / "sources" / "fictionalHepaticCohort2021.txt"
    source.write_text("A different paper entirely.\n", encoding="utf-8")


def _value_not_quoted(root: Path) -> None:
    path = root / "literature" / "ledger.yaml"
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    document["entries"][0].update(value=17.0, display="17")
    path.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")


def _unreadable(root: Path) -> None:
    path = root / "literature" / "ledger.yaml"
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    document["entries"][0]["source_file"] = "sources/fictionalHepaticCohort2021.docx"
    path.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")
    (root / "literature" / "sources" / "fictionalHepaticCohort2021.docx").write_bytes(b"PK")


@pytest.mark.parametrize(
    ("edit", "change", "verdict", "code"),
    [
        (None, None, "literature_verified", None),
        (None, _without_source, "literature_failed", "literature-source-missing"),
        (_source_removed, None, "literature_failed", "literature-source-missing"),
        (_misquoted, None, "literature_failed", "quote-not-in-source"),
        (_value_not_quoted, None, "literature_failed", "value-not-in-quote"),
        (_unreadable, None, "literature_unverifiable", None),
    ],
    ids=["clean", "no source named", "source gone", "quote", "value", "unreadable"],
)
def test_every_literature_value_ends_in_one_verdict(
    project: Path, edit, change, verdict: str, code: str | None
) -> None:
    """Verified, unverifiable, failed or attested: one of the four for every value, so a
    value the gates passed over shows as a count that does not add up."""
    if edit is not None:
        edit(project)
    report = _literature_report(project, change)
    counts = report.counts
    verdicts = ("verified", "unverifiable", "failed", "attested")
    assert sum(counts[f"literature_{name}"] for name in verdicts) == counts[
        "literature_values"
    ], counts
    # The edited value, the first of the two ledger entries, is the one that moved.
    expected = {"literature_verified": 2, "literature_unverifiable": 0, "literature_failed": 0}
    if verdict != "literature_verified":
        expected["literature_verified"] = 1
        expected[verdict] = 1
    assert {name: counts[name] for name in expected} == expected, counts
    if code is not None:
        assert code in codes(report), report.render(project)


# ------------------------------------------- a recorded source that is not on this computer
# New projects keep literature/sources/ out of git, and literature/sources.yaml in it (Basile,
# 2026-10-20, confirmed 2026-11-05). On a fresh clone or in CI a source the record lists is
# then missing for a reason that is not a fault: G7 notes it, and the quote is unverifiable
# rather than failed. A copy counts as kept out of git only where git says its path is
# ignored (Basile, 2026-11-05): a tracked copy, one git does not ignore, and any copy where
# git cannot be asked fail as before. A project that commits its copies asks for the failure
# back in paper.yaml.

_HEPATIC = "fictionalHepaticCohort2021.txt"


def _recorded_then_gone(root: Path, *, sources_in_git: bool | None = None, **away) -> None:
    from kept_away import keep_away

    keep_away(root, _HEPATIC, "fictionalHepaticCohort2021", **away)
    if sources_in_git is not None:
        paper = root / "paper.yaml"
        document = yaml.safe_load(paper.read_text(encoding="utf-8"))
        document["literature"] = {"sources_in_git": sources_in_git}
        paper.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")


def test_a_recorded_source_not_on_this_computer_is_noted_and_unverifiable(project: Path) -> None:
    from manuscript_guard.cli import _run_gates
    from manuscript_guard.findings import INFO

    _recorded_then_gone(project)
    report = _literature_report(project)
    assert report.ok, report.render(project)
    (note,) = [f for f in report.findings if f.code == "literature-source-not-here"]
    assert note.severity == INFO
    assert "not on this computer" in note.message and "sources.yaml" in note.message
    assert "literature-source-missing" not in codes(report)
    counts = report.counts
    assert (counts["literature_verified"], counts["literature_unverifiable"],
            counts["literature_failed"]) == (1, 1, 0), counts  # fmt: skip
    # `check`, at every stage, says the same: a note, not a failure.
    gated, _project, _stage, _deferred = _run_gates(project, stage="submission")
    assert "literature-source-not-here" in {f.code for f in gated.findings}
    assert "literature-source-missing" not in {f.code for f in gated.failures}


@pytest.mark.parametrize("taken_from", ["author", "zotero", "folder", "inbox", "open"])
def test_a_recorded_source_not_here_says_where_it_comes_back_from(
    project: Path, taken_from: str
) -> None:
    """`sync-sources` takes again a copy it took, from Zotero, or with `--from` from a folder
    (round 1 of #534), and never writes into the name of a file the author saved: the note
    says that file comes from whoever saved it (round 2 of #525: it said `sync-sources` put
    every copy back)."""
    from manuscript_guard.literature import copies

    _recorded_then_gone(project)
    path = project / "literature" / copies.RECORD
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    document["files"][_HEPATIC]["from"] = taken_from
    if taken_from == "folder":
        document["files"][_HEPATIC]["doi"] = "10.5555/hepatic.2021"
    if taken_from in ("inbox", "open"):
        # A PDF the user saved comes back only from the folder it was saved to; one the web
        # gave is fetched again by `sync-sources` as it is.
        document["files"][_HEPATIC]["matched"] = "doi"
    if taken_from == "open":
        document["files"][_HEPATIC]["url"] = "https://repository.test/hepatic.pdf"
    path.write_text(yaml.safe_dump(document), encoding="utf-8")
    (note,) = [f for f in _literature_report(project).findings
               if f.code == "literature-source-not-here"]  # fmt: skip
    run = "run `manuscript-guard sync-sources"
    if taken_from == "author":
        assert "whoever saved it" in note.hint and run not in note.hint, note.hint
    elif taken_from == "folder":
        assert f"{run} --from" in note.hint and "whoever saved it" not in note.hint, note.hint
    elif taken_from == "inbox":
        assert f"{run} --inbox" in note.hint and "whoever saved it" not in note.hint, note.hint
    else:
        assert f"{run}`" in note.hint and "--from" not in note.hint, note.hint


