# ------------------------------------------------------- a P worked out from its statistic
# A statistic and a P that the analysis did not make agree: typed, quoted from a source, or
# bound from two keys. G2 sees two numbers, each of which passed.


def _recomputed(root: Path):
    from manuscript_guard.gates import check_recomputed

    project, _ = load_project(root)
    namespace, results, _literature, _ = load_namespace(project)
    return check_recomputed(project, namespace, results)


def _recomputed_codes(root: Path, sentence: str) -> list[str]:
    main = main_md(root)
    main.write_text(main.read_text(encoding="utf-8") + "\n" + sentence + "\n", encoding="utf-8")
    return [f.code for f in _recomputed(root).findings]


def _emitted(root: Path, **displays: str) -> None:
    """Values in the example's results, each with the display given, as an analysis would
    emit them."""
    fragment = next((root / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    for key, display in displays.items():
        digits = len(display.partition(".")[2])
        value = {"value": float(display), "display": display, "digits": digits}
        document["values"][key.replace("__", ".")] = value
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)


@pytest.mark.parametrize(
    ("sentence", "found"),
    [
        ("Earlier work found t(23) = 2.45, p = .022 [@fictionalHepaticCohort2021].", []),
        ("Earlier work found t(23) = 2.45, p = .041 [@fictionalHepaticCohort2021].",
         ["p-inconsistent"]),
        ("Earlier work found t(23) = 2.45, p = .40 [@fictionalHepaticCohort2021].",
         ["p-decision-error"]),
        ("The arms differed, *F*(2, 45) = 3.21, *P* = 0.30.", ["p-decision-error"]),
        ("The arms differed, \N{GREEK SMALL LETTER CHI}^2^(1) = 0.5, *P* \\< 0.05.",
         ["p-decision-error"]),
        ("The arms differed, z = 3.30, P = 0.01.", ["p-inconsistent"]),
        ("A one-sided t(23) = 2.45, p = .011, as planned.", []),
        ("<!-- t(23) = 2.45, p = .40 -->", []),
        # A middle dot for the point, as the Lancet sets it, was read as no number, so a
        # paper set that way had none of its tests judged; and degrees of freedom with a
        # thousands' comma were read as two.
        ("Earlier work found t(23) = 2\N{MIDDLE DOT}45, p = 0\N{MIDDLE DOT}40 "
         "[@fictionalHepaticCohort2021].", ["p-decision-error"]),
        ("Earlier work found t(23) = 2\N{MIDDLE DOT}45, p = 0\N{MIDDLE DOT}022 "
         "[@fictionalHepaticCohort2021].", []),
        ("The arms differed, z = 4\N{MIDDLE DOT}50, P = 6\N{MIDDLE DOT}8\N{MIDDLE DOT}10^-4^.",
         ["p-inconsistent"]),
        ("The arms differed, *F*(1, 1,234) = 4.50, *P* = 0.30.", ["p-decision-error"]),
        ("The arms differed, t = 2.45, df = 1,234, P = 0.30.", ["p-decision-error"]),
    ],
)
def test_a_p_that_does_not_follow_from_its_statistic_is_found(
    project: Path, sentence: str, found: list[str]
) -> None:
    assert _recomputed_codes(project, sentence) == found


def test_a_statistic_and_a_p_bound_from_two_analyses_are_found(project: Path) -> None:
    """The crude t beside the adjusted P: each bound, each passed by G2, and no gate saw
    that they disagree."""
    _emitted(project, crude__t="2.45", adjusted__p="0.30")
    sentence = "The groups differed, t(23) = {{results.crude.t}}, p = {{results.adjusted.p}}."
    assert _recomputed_codes(project, sentence) == ["p-decision-error"]


def test_a_p_is_judged_at_the_alpha_the_analysis_emits(project: Path) -> None:
    """t(23) = 1.90 gives 0.070: below an alpha of 0.10, as the P of .03 printed beside it
    is, so the two disagree and no decision does."""
    sentence = "The groups differed, t(23) = 1.90, p = .03."
    assert _recomputed_codes(project, sentence) == ["p-decision-error"]
    _emitted(project, param__alpha="0.10")
    assert [f.code for f in _recomputed(project).findings] == ["p-inconsistent"]


@pytest.mark.parametrize("comment", ["", "<!-- one -->\n\n", "<!--\none\n\ntwo\n-->\n\n"])
def test_g8_names_the_line_of_a_p_after_a_comment_of_several_lines(
    project: Path, comment: str
) -> None:
    """The mask turned a comment's line breaks to NUL, and G8 counted its lines in the masked
    text, so a P after a comment of several lines was said that many lines too early (found
    with the audit's, below)."""
    main = main_md(project)
    sentence = "Earlier work found t(23) = 2.45, p = .041 [@fictionalHepaticCohort2021]."
    text = f"{main.read_text(encoding='utf-8')}\n{comment}{sentence}\n"
    main.write_bytes(text.encode("utf-8"))
    found = [f.line for f in _recomputed(project).findings if f.code == "p-inconsistent"]
    assert found == [text.count("\n", 0, text.index(sentence)) + 1]


@pytest.mark.parametrize(
    ("sentence", "codes"),
    [
        ("Earlier work found t(23) = 2.45 <!-- see\n\nnotes --> p = .041 "
         "[@fictionalHepaticCohort2021].", ["p-inconsistent"]),
        ("Earlier work found Welch's <!-- see\n\nnotes --> t(23) = 2.45, p = .041 "
         "[@fictionalHepaticCohort2021].", []),
    ],
)  # fmt: skip
def test_g8_reads_a_sentence_across_a_comment_holding_a_blank_line(
    project: Path, sentence: str, codes: list[str]
) -> None:
    """Round 1 of #693: with a comment's line breaks kept in what G8 reads, a blank line in
    a comment inside a sentence ended it, so a P after the comment was no P of the
    statistic before it, and a quiet word before it, "Welch's", was no word of the test
    after it. Both are read across the comment, and the finding is at its line."""
    main = main_md(project)
    text = f"{main.read_text(encoding='utf-8')}\n{sentence}\n"
    main.write_bytes(text.encode("utf-8"))
    found = [(f.code, f.line) for f in _recomputed(project).findings
             if f.code in ("p-inconsistent", "p-decision-error")]  # fmt: skip
    line = text.count("\n", 0, text.index(sentence)) + 1
    assert found == [(code, line) for code in codes]


def test_an_abstract_number_unlike_the_results_after_a_comment_is_reported(
    tmp_path: Path,
) -> None:
    """The paper `init --from` writes, its cover in a comment of several lines over an
    Abstract and no Methods: the Abstract's numbers were placed the comment's height too
    early, outside it, and none was compared (found building #691). With the lines kept, the
    Results matching them hides each; one changed in the Results is still reported, at the
    Abstract's own line."""
    from manuscript_guard.audit import audit

    paper = tmp_path / "main.md"

    def not_found(reported: str) -> list[tuple[str, int]]:
        text = ("<!--\nAbstract\nIntroduction\n-->\n\n# Abstract\n\nOf 412 nurses, 77 fell.\n\n"
                f"# Introduction\n\nFalls harm nurses.\n\n# Results\n\n{reported}\n\n"
                "# Discussion\n\nFalls are common.\n")  # fmt: skip
        paper.write_bytes(text.encode("utf-8"))
        read = audit([paper], None).abstract
        assert read.compared and read.numbers == 2, text
        return [(c.text, c.line) for c in read.not_found]

    assert not_found("Of 412 nurses, 77 fell.") == []
    assert not_found("Of 412 nurses, 71 fell.") == [("77", 8)]
    assert not_found("Of 421 nurses, 77 fell.") == [("412", 8)]


