def _cell(text: str, *, span: int = 1) -> str:
    props = f'<w:tcPr><w:gridSpan w:val="{span}"/></w:tcPr>' if span > 1 else ""
    return f"<w:tc>{props}<w:p>{text}</w:p></w:tc>"


@pytest.mark.parametrize(("value", "span"), [("3", 3), ("63", 63), ("999999999", 63),
                                              ("0", 1), ("x", 1)])  # fmt: skip
def test_a_cell_spans_no_more_columns_than_word_allows(value: str, span: int) -> None:
    """Round 1 of #314: a span had no upper bound, and a crafted gridSpan of 999999999 built
    a string of marks of about a gigabyte. Word allows a table 63 columns."""
    import xml.etree.ElementTree as ET

    from manuscript_guard.text import docx

    namespace = docx.W.strip("{}")
    cell = ET.fromstring(f'<w:tc xmlns:w="{namespace}"><w:tcPr><w:gridSpan w:val="{value}"/>'
                         f"</w:tcPr></w:tc>")  # fmt: skip
    assert docx._span(cell) == span


def _run(text: str, *, raised: bool = False) -> str:
    props = '<w:rPr><w:vertAlign w:val="superscript"/></w:rPr>' if raised else ""
    return f'<w:r>{props}<w:t xml:space="preserve">{text}</w:t></w:r>'


def test_an_n_percent_in_a_word_table_is_read_by_its_row_and_column(tmp_path: Path) -> None:
    """Item 19.4: in a .docx each cell is a line of its own, so a table is read as Word lays
    it out, rows of cells, a header cell spanning two columns counted as each. A footnote
    marker typed as superscript, or a footnote's own reference, makes the row uncertain.
    The text the rest of the audit reads is what it was: the marks go."""
    from manuscript_guard.audit import audit
    from manuscript_guard.text.docx import read_docx_text

    def row(*cells: str) -> str:
        return "<w:tr>" + "".join(cells) + "</w:tr>"

    def plain(*texts: str) -> list[str]:
        return [_cell(_run(text)) for text in texts]

    table = "<w:tbl>" + "".join([
        row(_cell(""), _cell(_run("Arms (n = 900)"), span=2)),
        row(*plain("Characteristic", "Exposed", "Unexposed")),
        row(*plain("Diabetes, n (%)", "300 (33.3)", "100 (11.0)")),
        row(_cell(_run("Smoking") + _run("a", raised=True) + _run(", n (%)")),
            *plain("90 (10.0)", "95 (11.0)")),
        row(_cell(_run("Stroke, n (%)") + '<w:r><w:footnoteReference w:id="2"/></w:r>'),
            *plain("9 (1.0)", "18 (3.0)")),
    ]) + "</w:tbl>"  # fmt: skip
    paper = _docx(tmp_path / "paper.docx", _p("Results") + table + _p("After the table."))
    said = audit([paper], []).disagreements
    assert [d.message.split(";")[0] for d in said] == [
        "n (%) 100 (11.0): 100 of 900 is 11.11%, not 11.0",
        "n (%) 95 (11.0): 95 of 900 is 10.56%, not 11.0",
        "n (%) 18 (3.0): 18 of 900 is 2.00%, not 3.0",
    ]
    assert ["uncertain" in d.message for d in said] == [False, True, True]
    assert said[1].context == "Smoking^a^, n (%) | 90 (10.0) | 95 (11.0)"
    body = read_docx_text(paper).body
    assert "\nSmokinga, n (%) | \n90 (10.0) | \n" in body
    assert not any(chr(mark) in body for mark in range(0x19, 0x20))


@pytest.mark.parametrize(
    "written",
    [
        # No denominator anywhere in the table.
        "| Characteristic | Exposed | Unexposed |\n|---|---|---|\n"
        "| Diabetes, n (%) | 300 (26.0) | 7 (2.0) |\n",
        # A label that names a median, although it says %.
        "| | A (n = 100) |\n|---|---|\n| Ejection fraction, %, median (IQR) | 55 (15) |\n",
        # A column whose header names a mean, although it says n (%).
        "| | Mean (SD) or n (%), n = 100 |\n|---|---|\n| Visits | 4 (2) |\n",
        # Nothing says the numbers in brackets are shares, and they do not add up to 100.
        "| | A (n = 50) |\n|---|---|\n| Visits | 3 (2) |\n| Calls | 5 (1) |\n",
        # Shares of the row's own total.
        "| | A (n = 100) | B (n = 200) |\n|---|---|---|\n"
        "| Exposed, n (%) | 30 (60.0) | 20 (40.0) |\n",
        # A "%" that is a unit, its mean (SD) printed as whole numbers (round 1 of #314).
        "| | A (n = 1200) | B (n = 3400) |\n|---|---|---|\n"
        "| Oxygen saturation, % | 96 (3) | 95 (4) |\n| LVEF, % | 55 (10) | 54 (11) |\n",
        # A unit in percent under a header that says n (%): a measure all the same.
        "| | A (n = 1200), n (%) |\n|---|---|\n| HbA1c (%) | 7 (1) |\n"
        "| Diabetes, n (%) | 300 (25.0) |\n",
        # A whole-number mean whose running sum with the shares passes through 100, under
        # a section label and a header that does not say n (%) (round 3 of #314).
        "| | Overall (n = 1200) |\n|---|---|\n| Baseline | |\n| Age, years | 62 (11) |\n"
        "| Female sex | 540 (45.0) |\n| Hypertension | 528 (44.0) |\n"
        "| Diabetes | 216 (18.0) |\n",
        # The subtypes again, the next characteristic straight after them (round 2).
        "| | A (n = 1200), n (%) | B (n = 3400), n (%) |\n|---|---|---|\n"
        "| Diabetes, n (%) | 300 (25.0) | 700 (20.6) |\n| Diabetes type | | |\n"
        "| Type 1 | 30 (10.0) | 70 (10.0) |\n| Type 2 | 270 (90.0) | 630 (90.0) |\n"
        "| Hypertension, n (%) | 500 (41.7) | 1400 (41.2) |\n",
        # And with a P value beside their label (round 2).
        "| | A (n = 1200) | B (n = 3400) | P |\n|---|---|---|---|\n"
        "| Diabetes, n (%) | 300 (25.0) | 700 (20.6) | 0.01 |\n"
        "| Diabetes type | | | 0.40 |\n| Type 1 | 30 (10.0) | 70 (10.0) | |\n"
        "| Type 2 | 270 (90.0) | 630 (90.0) | |\n",
        # The subtypes of another row, shares of it and not of the column (round 1 of #314).
        "| | A (n = 1200) | B (n = 3400) |\n|---|---|---|\n"
        "| Diabetes, n (%) | 300 (25.0) | 700 (20.6) |\n| Diabetes type | | |\n"
        "| Type 1 | 30 (10.0) | 70 (10.0) |\n| Type 2 | 270 (90.0) | 630 (90.0) |\n",
        # In a fenced listing.
        "```\n| | A (n = 1200) |\n|---|---|\n| Diabetes, n (%) | 300 (26.0) |\n```\n",
        # In the reference list.
        "Text.\n\n# References\n\n| | A (n = 1200) |\n|---|---|\n"
        "| Diabetes, n (%) | 300 (26.0) |\n",
        # In a sentence.
        "Diabetes was present in 300 (26.0%) of the 1200 exposed patients (n = 1200).\n",
    ],
)  # fmt: skip
def test_an_n_percent_held_to_nothing_is_not_listed(tmp_path: Path, written: str) -> None:
    """Item 19.4: only a column of shares with a denominator is held to it. Mean (SD) and
    median (IQR) never fire, a share of the row is not wrong, and a table that is not one,
    or not the paper's, is not read."""
    from manuscript_guard.audit import audit

    paper = tmp_path / "paper.md"
    paper.write_text(written, encoding="utf-8")
    assert audit([paper], []).disagreements == []


@pytest.mark.parametrize(
    ("written", "said"),
    [
        ("drug-induced hepatic\n12\ninjury",
         "the source has '12' between 'hepatic' and 'injury' (line 13): numbers"),
        ("drug-induced hepa-\ntic injury", "'hepa' and 'tic' are one word, split by a hyphen"),
        ("hepatic injury", "the source has 'drug-induced' between 'of' and 'hepatic' (line 12)"),
        ("drug-induced liver injury",
         "after 'induced' the quote has 'hepatic', where the source has 'liver injury was'"),
        ("per 100\N{MIDDLE DOT}000",
         "between '100' and '000' (line 12) the source has '\N{MIDDLE DOT}' where the quote "
         "has ' '"),
    ],
)  # fmt: skip
def test_a_quote_not_in_its_source_says_what_stands_in_the_way(
    project: Path, written: str, said: str
) -> None:
    """Item 19: G7 fails a quote that is not in the source exactly, and used to say only
    that. The quote's words in order, with line numbers, a hyphen or a symbol between, are
    put right in a minute once that is named. The verdict is the same."""
    source = project / "literature" / "sources" / "fictionalHepaticCohort2021.txt"
    text = source.read_text(encoding="utf-8")
    plain = "drug-induced hepatic injury" if "induced" in written else "per 100 000"
    if written == "hepatic injury":
        # The quote leaves a word out, rather than the source putting one in.
        path = project / "literature" / "ledger.yaml"
        ledger = path.read_text(encoding="utf-8")
        path.write_text(ledger.replace("of drug-induced hepatic", "of hepatic", 1), "utf-8")
    else:
        source.write_text(text.replace(plain, written, 1), encoding="utf-8")
    report = _literature_report(project)
    found = [f for f in report.findings if f.code == "quote-not-in-source"]
    assert len(found) == 1 and found[0].severity == "fail", report.render(project)
    assert said in found[0].message, found[0].message
    assert report.counts["literature_failed"] == 1


@pytest.mark.parametrize(
    ("quote", "short"),
    [
        ("A signal was detected for the class as a whole (ROR 2.6, 95% CI 2.1-3.2).", False),
        ("the class as a whole (ROR 2.6", False),
        # Round 1 of #278: the threshold itself, four words beside the value and three.
        ("as a whole (ROR 2.6", False),
        ("a whole (ROR 2.6", True),
        ("whole (ROR 2.6", True),
        ("ROR 2.6", True),
        ("2.6", True),
    ],
)
def test_a_quote_that_holds_little_more_than_its_value_is_said(
    project: Path, quote: str, short: bool
) -> None:
    """G7 holds the quote to the source and the value to the quote, so "2.6" quoted alone
    passed both: it proves only that those digits are somewhere in the source. A quote with
    fewer than four words beside its value is said; the value is still verified."""
    path = project / "literature" / "ledger.yaml"
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    entry = next(e for e in document["entries"] if e.get("display") == "2.6")
    entry["quote"] = quote
    path.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")
    report = _literature_report(project)
    said = [f for f in report.findings if f.code == "quote-too-short"]
    assert [f.severity for f in said] == (["warn"] if short else []), report.render(project)
    assert report.counts["literature_verified"] == 2


@pytest.mark.parametrize(
    ("quote", "short"),
    [
        # Made-up sentences, in the source's words: the class's signal, its ROR and its year.
        ("2019年の調査では、薬剤群全体で報告オッズ比2.6の信号が検出された。", False),
        ("2019年的调查显示，该类药物整体的报告比值比为2.6。", False),
        ("พบสัญญาณของยากลุ่มนี้โดยรวม (ROR 2.6)", False),
        # Japanese and Latin in one quote: three words of the one and one of the other.
        ("薬剤群全体のROR 2.6", False),
        # Chinese set with spaces around numbers and Latin words: a piece between spaces is
        # a word, a single letter as well, as it was before (round 1 of #505).
        ("纳入 120 例, ROR 为 2.6", False),
        ("群全体のROR 2.6", True),
        ("報告オッズ比2.6", True),
        ("倍率2.6", True),
        ("2.6倍", True),
        ("ROR 2.6 เท่า", True),
    ],
)
def test_a_quote_in_a_script_written_without_spaces_is_counted_by_its_letters(
    project: Path, quote: str, short: bool
) -> None:
    """A quote in Japanese, Chinese or Thai has no spaces between its words, so a whole
    sentence was two words beside its value and warned of as a value quoted alone. Han,
    Hiragana and Katakana count a word for every two letters in a row, Thai for every four;
    a value with a unit or a label of a few letters is still said."""
    source = project / "literature" / "sources" / "fictionalClassSignal2019.txt"
    source.write_text(source.read_text(encoding="utf-8") + f"\n{quote}\n", encoding="utf-8")
    path = project / "literature" / "ledger.yaml"
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    entry = next(e for e in document["entries"] if e.get("display") == "2.6")
    entry["quote"] = quote
    path.write_text(yaml.safe_dump(document, sort_keys=False, allow_unicode=True), "utf-8")
    report = _literature_report(project)
    said = [f for f in report.findings if f.code == "quote-too-short"]
    assert [f.severity for f in said] == (["warn"] if short else []), report.render(project)
    assert report.counts["literature_verified"] == 2


@pytest.mark.parametrize(
    ("quote", "value", "beside"),
    [
        # A number quoted twice, or inside a word that holds it, counts as it should.
        ("ROR 2.6 rose to 2.6", "2.6", ["ROR", "rose", "to"]),
        ("CYP3A14 rose 14 times", "14", ["CYP3A", "rose", "times"]),
        # A value with letters is taken out once: quoted again, its letters are a word.
        ("IgG4 rose and IgG4 fell", "IgG4", ["rose", "and", "IgG4", "fell"]),
        ("1 in 4 rose, 1 in 4 fell", "1 in 4", ["rose,", "in", "fell"]),
        # Found first inside a longer word, that word is cut and the value itself counts.
        ("anti-IgG4 rose with IgG4", "IgG4", ["anti-", "rose", "with", "IgG4"]),
    ],
)
def test_a_ledger_value_is_taken_out_of_its_quote_once(
    quote: str, value: str, beside: list[str]
) -> None:
    """Known gaps, "A ledger value is taken out of its quote once": the words beside a value
    are counted with its first match alone taken out, so a value with letters quoted again,
    or first matched inside a word, has its letters counted as a word beside it."""
    from manuscript_guard.literature.sources import words_beside

    assert words_beside(quote, value) == beside


# ------------------------------------------------- what the audit reads of a LaTeX paper
# `audit` refused a `.tex` named: a LaTeX paper's numbers, its tables and its references were
# checked by nothing outside a project. Each corruption below changes what it reports.

_LATEX_PAPER = (
    "!documentclass{article}\n!begin{document}\n!section{Results}\n"
    "Of 412 reports, the odds ratio was 2.10 !cite{smith}.\n"
    "!begin{tabular}{lr}\n& Cases (n = 40) !!\nMale & 12 (30.0!%) !!\n"
    "Female & 28 (70.0!%) !!\n!end{tabular}\n"
    "!begin{thebibliography}{9}\n!bibitem{smith} Smith J. Lancet. 2019;393:100-10.\n"
    "!end{thebibliography}\n!end{document}\n"
)


@pytest.mark.parametrize(
    ("typed", "unmatched", "off", "listed"),
    [
        ((), [], [], []),
        ((("2.10", "2.01"),), ["2.01"], [], []),
        ((("12 (30.0", "12 (35.0"),), ["35.0%"], [7], []),
        ((("cite{smith}", "cite{smyth}"),), [], [],
         ["citation-not-listed", "entry-never-cited"]),
    ],
    ids=["as written", "an estimate changed", "a share changed", "a citation's key changed"],
)
def test_an_audited_latex_paper_is_held_as_a_markdown_one_is(
    tmp_path: Path, typed, unmatched, off, listed
) -> None:
    from manuscript_guard.audit import audit
    from manuscript_guard.cli import main

    text = _LATEX_PAPER
    for old, new in typed:
        text = text.replace(old, new)
    paper = tmp_path / "paper.tex"
    paper.write_text(text.replace("!", chr(92)), encoding="utf-8")
    outputs = tmp_path / "outputs.csv"
    outputs.write_text("n,or,male,female,pm,pf\n412,2.10,12,28,30.0,70.0\n40,0,0,0,0,0\n",
                       encoding="utf-8")  # fmt: skip
    report = audit([paper], [outputs])
    assert [c.text for c in report.unmatched] == unmatched
    assert [d.line for d in report.disagreements] == off
    assert [p.code for c in report.references for p in c.problems] == listed
    assert main(["audit", str(paper), "--against", str(outputs), "--strict"]) == (
        1 if unmatched else 0
    )


def test_a_word_entry_styled_as_a_heading_is_held_as_an_entry(tmp_path: Path) -> None:
    """A Word paper styled two of its entries as headings, so the list ended at the first of
    them and every entry after it was read as text, its number a citation of an entry the
    list did not hold: eight false findings in one paper (window C of the real-paper
    corpus). Each is an entry now, and the list ends at the next section's title, under
    which "[6]" cites what the list does not hold."""
    import zipfile

    from manuscript_guard.audit import audit

    ns = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'
    paragraphs = [
        ("Results", True), ("The rate rose [1, 2] and fell [3-5].", False),
        ("REFERENCES", False),
        ("[1] Dataset - https://example.org/data", False),
        ("[2] Face detection: a review - https://example.org/review", True),
        ("[3] A cohort of masks - https://example.org/cohort", False),
        ("[4] A network for masks - https://example.org/network", False),
        ("[5] A tiny network for masks - https://example.org/tiny", True),
        ("Appendix", True), ("The rate in the appendix rose [6].", False),
    ]  # fmt: skip
    styled = '<w:pPr><w:pStyle w:val="Heading1"/></w:pPr>'
    body = "".join(f'<w:p>{styled if heading else ""}<w:r><w:t xml:space="preserve">{text}'
                   "</w:t></w:r></w:p>" for text, heading in paragraphs)  # fmt: skip
    paper = tmp_path / "paper.docx"
    with zipfile.ZipFile(paper, "w") as archive:
        archive.writestr("word/document.xml",
                         f"<w:document {ns}><w:body>{body}</w:body></w:document>")
        archive.writestr("word/styles.xml", f'<w:styles {ns}><w:style w:type="paragraph" '
                         'w:styleId="Heading1"><w:name w:val="heading 1"/></w:style></w:styles>')
    [census] = audit([paper], None).references
    assert len(census.entries) == 5, [entry.label for entry in census.entries]
    assert [(p.code, p.subject) for p in census.problems] == [("citation-beyond-list", "[6]")]


@pytest.mark.parametrize(("marker", "listed"), [("[3]", []), ("[4]", ["citation-beyond-list"])])
def test_an_audited_paper_s_numbered_citation_is_held_to_its_list(
    tmp_path: Path, marker: str, listed: list[str]
) -> None:
    """A citation by number of an entry the list does not hold, which no gate read in a
    paper outside a project: `audit` counted no reference list."""
    from manuscript_guard.audit import audit

    paper = tmp_path / "paper.md"
    paper.write_text(f"# Results\n\nIt rose [1, 2] and fell {marker}.\n\n# References\n\n"
                     "1. Smith J. A. J Ex. 2019;1:1-2.\n2. Jones K. B. J Ex. 2020;2:3-4.\n"
                     "3. Brown L. C. J Ex. 2021;3:5-6.\n", encoding="utf-8")  # fmt: skip
    [census] = audit([paper], None).references
    never = [] if marker == "[3]" else ["entry-never-cited"]
    assert [p.code for p in census.problems] == listed + never


@pytest.mark.parametrize(("marker", "listed"), [("[3]", []), ("[4]", ["citation-beyond-list"])])
@pytest.mark.parametrize("stop", ["1.", "1" + chr(92) + "."])
def test_an_audited_list_numbered_1_on_every_entry_is_held_as_pandoc_prints_it(
    tmp_path: Path, marker: str, listed: list[str], stop: str
) -> None:
    """Round 1 of #463: a list typed "1." on every entry was held as one entry, so a
    citation of entry 3 was beyond it; pandoc prints it 1, 2, 3, and [4] is beyond that. A
    number pandoc escaped, `1\\.`, prints as typed, and such a list was not held at all."""
    from manuscript_guard.audit import audit

    numbers = ("1", "1", "1") if stop == "1." else ("1", "2", "3")
    escape = "" if stop == "1." else chr(92)
    entries = "".join(f"{n}{escape}. Author {n}. J Ex. 2019;1:1-2.\n" for n in numbers)
    paper = tmp_path / "paper.md"
    paper.write_text(f"# Results\n\nIt rose [1, 2] and fell {marker}.\n\n# References\n\n"
                     f"{entries}", encoding="utf-8")  # fmt: skip
    [census] = audit([paper], None).references
    never = [] if marker == "[3]" else ["entry-never-cited"]
    assert [p.code for p in census.problems] == listed + never


@pytest.mark.parametrize(("cited", "listed"), [("a,x", []), ("a", [("refs.tex", 3)])])
def test_an_audited_bibitem_never_cited_is_reported_in_its_own_file(
    tmp_path: Path, cited: str, listed: list
) -> None:
    """Round 1 of #463: an uncited `\\bibitem` in a file the paper inputs was reported at
    the line of the paper's main file."""
    from manuscript_guard.audit import audit

    slash = chr(92)
    (tmp_path / "main.tex").write_text(
        f"{slash}documentclass{{article}}\n{slash}begin{{document}}\nSee {slash}cite{{{cited}}}"
        f".\n{slash}input{{refs}}\n{slash}end{{document}}\n", encoding="utf-8")  # fmt: skip
    (tmp_path / "refs.tex").write_text(
        f"{slash}begin{{thebibliography}}{{9}}\n{slash}bibitem{{a}} A.\n{slash}bibitem{{x}} X."
        f"\n{slash}end{{thebibliography}}\n", encoding="utf-8")  # fmt: skip
    [census] = audit([tmp_path / "main.tex"], None).references
    assert [(p.path.name, p.line) for p in census.problems
            if p.code == "entry-never-cited"] == listed  # fmt: skip


@pytest.mark.parametrize(("share", "off"), [("30.0", []), ("35.0", [6])])
def test_an_audited_share_in_a_coloured_latex_cell_is_held_to_its_denominator(
    tmp_path: Path, share: str, off: list[int]
) -> None:
    """Round 1 of #463: a `\\cellcolor[rgb]{0.9,0.9,0.9}` printed its values into the cell,
    "0.9,0.9,0.912 (35.0%)", and the share in it was held to nothing."""
    from manuscript_guard.audit import audit

    text = (
        "!documentclass{article}\n!begin{document}\n!begin{tabular}{lr}\n"
        "& Cases (n = 40) !!\n!rowcolor{gray!20} Female & 28 (70.0!%) !!\n"
        f"Male & !cellcolor[rgb]{{0.9,0.9,0.9}}12 ({share}!%) !!\n"
        "!end{tabular}\n!end{document}\n"
    ).replace("!", chr(92)).replace("gray" + chr(92), "gray!")
    paper = tmp_path / "paper.tex"
    paper.write_text(text, encoding="utf-8")
    report = audit([paper], None)
    assert [d.line for d in report.disagreements] == off


@pytest.mark.parametrize(("second", "strict"), [(True, 0), (False, 1)])
def test_a_second_latex_document_in_an_audited_folder_is_read_as_a_paper(
    tmp_path: Path, second: bool, strict: int
) -> None:
    """Round 1 of #463: a folder's supplement, a document of its own, was refused as a
    second document inside the main one, and `--strict` failed though both were read. A
    file with no document of its own that the main one inputs, and that the reader refuses
    in part, still fails `--strict`."""
    from manuscript_guard.cli import main

    slash = chr(92)
    (tmp_path / "main.tex").write_text(
        f"{slash}documentclass{{article}}\n{slash}begin{{document}}\nOf 412.\n"
        + ("" if second else f"{slash}input{{supplement}}\n") + f"{slash}end{{document}}\n",
        encoding="utf-8",
    )  # fmt: skip
    supplement = (f"{slash}documentclass{{article}}\n{slash}begin{{document}}\nOf 40.\n"
                  f"{slash}end{{document}}\n") if second else f"{slash}catcode`@=11 Of 40.\n"
    (tmp_path / "supplement.tex").write_text(supplement, encoding="utf-8")
    assert main(["audit", str(tmp_path), "--strict"]) == strict


@pytest.mark.parametrize("where", ["data.txt", "anc/data.txt", "anc/readme.md",
                                   "anc/deeper/notes.markdown"])  # fmt: skip
def test_a_text_file_in_a_latex_paper_s_folder_is_not_audited_as_a_paper(
    tmp_path: Path, where: str
) -> None:
    """The robustness sweep of 2026-11-21: in an arXiv bundle `audit` read the data
    transcript under `anc/` as a paper beside the LaTeX one, its numbers were in no output,
    and `--strict` failed on numbers the paper never printed. A `.txt` or a Markdown file in
    a LaTeX paper's folder, or under it, is passed over (Basile, 2026-11-22)."""
    from manuscript_guard.cli import main

    slash = chr(92)
    bundle = tmp_path / "bundle"
    bundle.mkdir()
    (bundle / "main.tex").write_text(
        f"{slash}documentclass{{article}}\n{slash}begin{{document}}\nOf 412.\n"
        f"{slash}end{{document}}\n", encoding="utf-8")  # fmt: skip
    data = bundle / where
    data.parent.mkdir(parents=True, exist_ok=True)
    data.write_text("0.125 0.250 999\n", encoding="utf-8")
    (tmp_path / "out.csv").write_text("n\n412\n", encoding="utf-8")
    assert main(["audit", str(bundle), "--against", str(tmp_path / "out.csv"), "--strict"]) == 0


@pytest.mark.parametrize(
    "defined",
    ["!let!toprule!hline", "!def!toprule{!hline}", "!newcommand{!midrule}{!hline}",
     "!renewcommand{!bottomrule}{!hline}"],
    ids=["let", "def", "newcommand", "renewcommand"],
)
@pytest.mark.parametrize(("printed", "unmatched"), [("412", []), ("413", ["413"])])
def test_an_author_s_own_rule_command_leaves_the_paper_read(
    tmp_path: Path, defined: str, printed: str, unmatched: list[str]
) -> None:
    """Round 2 of #463: the mask knew booktabs' rules, and refused an author's own
    definition of one as defined again, so the rest of the file was read as typed and
    `--strict` failed, in `audit` and in every gate of `check`. A number changed after it is
    still found."""
    from manuscript_guard.audit import audit

    paper = tmp_path / "paper.tex"
    paper.write_text(
        (f"!documentclass{{article}}\n{defined}\n!begin{{document}}\nOf {printed} reports.\n"
         "!end{document}\n").replace("!", chr(92)), encoding="utf-8",
    )  # fmt: skip
    outputs = tmp_path / "outputs.csv"
    outputs.write_text("n\n412\n", encoding="utf-8")
    report = audit([paper], [outputs])
    assert (report.unreadable, [c.text for c in report.unmatched]) == ([], unmatched)


_SICI = "10.1002/(SICI)1097-0258(19980430)17:8<857::AID-SIM777>3.0.CO;2-E"


@pytest.mark.parametrize(("cited", "listed"), [("2", []), ("3", ["citation-beyond-list"])])
def test_an_audited_escaped_interval_is_no_citation(
    tmp_path: Path, cited: str, listed: list[str]
) -> None:
    """Fix-only round of #463: pandoc escapes an interval's brackets as it escapes a
    citation's, `64 \\[55-72\\]`, and once escaped citations were read, the interval was one,
    beyond a list of two. A citation beyond it is still reported."""
    from manuscript_guard.audit import audit

    slash = chr(92)
    paper = tmp_path / "paper.md"
    paper.write_text(f"# Results\n\nMedian 64 {slash}[55-72{slash}] days {slash}[1{slash}], "
                     f"{slash}[{cited}{slash}].\n\n# References\n\n1. A. J Ex. 2019;1:1-2.\n"
                     "2. B. J Ex. 2019;1:1-2.\n", encoding="utf-8")  # fmt: skip
    [census] = audit([paper], None).references
    never = ["entry-never-cited"] if cited == "3" else []
