@pytest.mark.parametrize(("written", "listed"), [(_SICI, []),
                                                 ("10.1002/sim.857", ["doi-unregistered"])])
def test_an_audited_sici_doi_is_looked_up_whole(
    tmp_path: Path, written: str, listed: list[str]
) -> None:
    """Round 2 of #463: a SICI DOI was cut at its `<`, and the registries, asked of the
    part before it, had no such DOI: the audit said no registry had a real work's DOI."""
    import json

    from manuscript_guard.audit import audit
    from manuscript_guard.auditing.references import look_up
    from manuscript_guard.lookup import run
    from manuscript_guard.lookup.http import Response

    def registry(request, timeout):
        known = "aid-sim777" in request.base.lower()
        if "crossref" in request.base and known:
            body = {"status": "ok", "message-type": "work", "message": {
                "DOI": _SICI.lower(), "type": "journal-article", "title": ["A trial"]}}
            return Response(200, {"Content-Type": "application/json"}, json.dumps(body).encode())
        if "openalex" in request.base and known:
            body = {"id": "W1", "is_retracted": False, "title": "A trial"}
            return Response(200, {"Content-Type": "application/json"}, json.dumps(body).encode())
        return Response(404, {"Content-Type": "application/json"},
                        json.dumps({"responseCode": 100}).encode())  # fmt: skip

    paper = tmp_path / "paper.md"
    paper.write_text(f"# Results\n\nIt rose [1].\n\n# References\n\n1. Smith J. A trial. "
                     f"Stat Med. 1998;17:857-72. doi:{written}.\n", encoding="utf-8")  # fmt: skip
    looked = look_up(audit([paper], None).references, transport=registry,
                     pacer=run.Pacer(sleep=lambda seconds: None))  # fmt: skip
    assert [p.code for one in looked for p in one.problems] == listed


# --------------------------------------------------------------------- the journal gate
# A journal's limits, sections and statements are about the document the editor receives,
# and the build strips every file's front matter before printing it.


def _journal(root: Path):
    from manuscript_guard.gates import check_journal

    project, _ = load_project(root)
    return check_journal(project)


# ---------------------------------------------------- the journal shortlist (item 49)


def _shortlist_said(root: Path) -> list[tuple[str, str]]:
    from manuscript_guard.gates.shortlist import check_shortlist

    project, _ = load_project(root)
    return [(f.code, f.severity) for f in check_shortlist(project).findings]


def _target_said(root: Path, table=None, **candidate) -> list[tuple[str, str]]:
    """G4 of the example's journal, shortlisted with these fields and looked up."""
    from test_journal_lookup import look_up_journals, write_shortlist

    write_shortlist(root, **candidate)
    look_up_journals(root, table)
    return _shortlist_said(root)


def test_a_shortlist_is_held_to_its_schema_as_a_warning(project: Path) -> None:
    from test_journal_lookup import write_shortlist

    assert _shortlist_said(project) == []
    write_shortlist(project, issn=["1111-111"])
    assert _shortlist_said(project) == [("shortlist-schema", "warn")]


def test_a_journal_chosen_from_outside_the_shortlist_is_said(project: Path) -> None:
    from test_journal_lookup import write_shortlist

    write_shortlist(project)
    path = project / "journals" / "shortlist.yaml"
    document = yaml.safe_load(path.read_text(encoding="utf-8"))
    document["decision"]["journal"] = "A Journal Nobody Considered"
    path.write_text(yaml.safe_dump(document, sort_keys=False), encoding="utf-8")
    assert ("shortlist-unknown-journal", "warn") in _shortlist_said(project)


def test_a_target_journal_not_indexed_for_medline_is_said(project: Path) -> None:
    """Item 49: a predatory journal is in neither MEDLINE nor DOAJ. The shortlist chose the
    example's journal, and the NLM Catalog said it is not currently indexed."""
    from test_journal_lookup import Table, esearch, esummary

    assert _target_said(project) == []
    assert _target_said(project, Table(esummary=esummary("N"))) == [
        ("journal-not-in-medline", "warn")
    ]
    assert _target_said(project, Table(esearch=esearch())) == [("journal-not-in-medline", "warn")]
    # The author's reason makes it a note that quotes them.
    said = _target_said(project, Table(esummary=esummary("N")),
                        outside_medline="A society journal of the field, indexed in Embase.")
    assert said == [("journal-not-in-medline", "info")]


def test_an_open_access_target_journal_not_in_doaj_is_said(project: Path) -> None:
    from test_journal_lookup import Table, listed

    assert _target_said(project, Table(doaj=listed(total=0))) == []
    assert _target_said(project, Table(doaj=listed(total=0)), open_access=True) == [
        ("journal-not-in-doaj", "warn")
    ]
    assert _target_said(project, open_access=True) == []


def test_what_is_not_known_of_the_target_journal_is_a_note(project: Path) -> None:
    """An answer that did not come, or a record missing or edited, is no evidence that the
    journal is outside MEDLINE: a note, and no warning."""
    from test_journal_lookup import ONLINE, Table, _json, esummary, write_shortlist

    said = _target_said(project, Table(esearch=_json(500, {})), open_access=True)
    assert said == [("journal-not-looked-up", "info")]
    write_shortlist(project)
    for record in (project / "journals" / "lookups").glob("*.yaml"):
        record.unlink()
    assert _shortlist_said(project) == [("journal-not-looked-up", "info")]
    _target_said(project, Table(esummary=esummary("N")))
    edited = project / "journals" / "lookups" / f"{ONLINE}.yaml"
    edited.write_text(edited.read_text(encoding="utf-8").replace("2026-10-17", "2026-10-18"),
                      encoding="utf-8")  # fmt: skip
    assert _shortlist_said(project) == [("journal-not-looked-up", "info")]


def test_the_target_journal_is_found_by_its_profile_its_name_or_the_decision(
    project: Path,
) -> None:
    from test_journal_lookup import Table, esummary

    no = Table(esummary=esummary("N"))
    assert _target_said(project, no, profile="another-profile") == [
        ("journal-not-in-medline", "warn")
    ]  # by the profile's name, "Journal of Demonstrative Pharmacoepidemiology"
    paper = project / "paper.yaml"
    paper.write_text(paper.read_text(encoding="utf-8").replace("target_journal: demo-journal\n",
                                                               ""), encoding="utf-8")  # fmt: skip
    assert _target_said(project, no) == [("journal-not-in-medline", "warn")]


def test_a_target_journal_none_of_the_candidates_is_said(project: Path) -> None:
    """Round 1 of #321: a candidate named otherwise than the target's profile, with no
    `profile:`, was not found, and G4 said nothing at all of whether the journal is indexed.
    The decision is not taken for the target: it may name another journal."""
    from test_journal_lookup import Table, esummary

    said = _target_said(project, Table(esummary=esummary("N")), journal="J Demonstr Pharm",
                        profile="another-profile")  # fmt: skip
    assert said == [("shortlist-unknown-journal", "warn"),
                    ("journal-target-not-shortlisted", "info")]  # fmt: skip


def test_the_warning_says_what_a_listing_is_evidence_of(project: Path) -> None:
    """Round 1 of #321: the hint said a predatory journal is never listed, which is not so,
    and called the target "the journal chosen" where the decision chose another."""
    from test_journal_lookup import Table, esummary

    from manuscript_guard.gates.shortlist import check_shortlist

    _target_said(project, Table(esummary=esummary("N")))
    [found] = [f for f in check_shortlist(load_project(project)[0]).findings
               if f.code == "journal-not-in-medline"]  # fmt: skip
    assert "the target journal" in found.message and "chosen" not in found.message
    assert "never" not in found.hint and "evidence" in found.hint


# ---------------------------------------------- the datasets considered, and the one chosen


def _sources_said(root: Path, document=None, *, stage: str = "drafting", pages: bool = True):
    """What G12 and G4 say of the record of data sources, by code and severity, with the
    record written as `document` (the whole one of tests/test_data_sources.py by default)."""
    from test_data_sources import write_record

    from manuscript_guard.gates.data_sources import check_data_sources, check_statement_sources

    write_record(root, document, pages=pages)
    project, _ = load_project(root)
    said = check_data_sources(project, stage).merge(check_statement_sources(project))
    return [(f.code, f.severity) for f in said.findings]


def _named_everywhere(root: Path, name: str = "Open Reports Archive") -> None:
    from test_data_sources import name_in_plan, set_statement

    name_in_plan(root, f"All reports in the {name}, quarterly extracts 2015 to 2025.")
    set_statement(root, f"The {name} is publicly available at https://ora.invalid/ "
                        "(doi:10.5555/ora.2026).")  # fmt: skip


def test_a_record_whole_sourced_and_followed_says_nothing(project: Path) -> None:
    """The baseline: every claim sourced and on its page, the chosen source named in the plan
    and the statement, paper.yaml asked nothing of it. And no record, nothing at all."""
    from manuscript_guard.gates.data_sources import check_data_sources, check_statement_sources

    loaded, _ = load_project(project)
    assert not check_data_sources(loaded, "submission").findings
    assert not check_statement_sources(loaded).findings
    _named_everywhere(project)
    assert _sources_said(project) == []
    assert _sources_said(project, stage="submission") == []


def test_a_record_out_of_shape_is_a_warning(project: Path) -> None:
    from test_data_sources import record

    document = record()
    document["candidates"][0]["access"]["route"] = "ask nicely"
    assert set(_sources_said(project, document)) == {("data-sources-schema", "warn")}
    (project / "design" / "data_sources.yaml").write_bytes(b"candidates: [\n")
    loaded, _ = load_project(project)
    from manuscript_guard.gates.data_sources import check_data_sources

    said = [(f.code, f.severity) for f in check_data_sources(loaded, "drafting").findings]
    assert said == [("data-sources-schema", "warn")]


def test_a_source_the_record_names_and_does_not_consider_is_said(project: Path) -> None:
    from test_data_sources import record

    _named_everywhere(project)
    for where in ("ranking", "rejected", "history", "chosen"):
        document = record()
        if where == "ranking":
            document["ranking"][1]["source"] = "faers"
        elif where == "rejected":
            document["decision"]["rejected"] = [{"source": "faers", "why": "too slow"}]
        elif where == "history":
            document["history"] = [{"source": "faers", "event": "applied", "date": "2026-10-22"}]
        else:
            document["decision"]["chosen"] = ["ora", "faers"]
        assert _sources_said(project, document) == [("data-source-unknown", "warn")], where
    document = record()
    document["candidates"][1]["id"] = "ora"
    assert ("data-source-id-repeated", "warn") in _sources_said(project, document)


def test_a_model_named_where_a_person_states_chooses_or_sends_is_said(project: Path) -> None:
    from test_data_sources import record

    _named_everywhere(project)
    for change in (
        lambda d: d["question"].update(stated_by="Claude"),
        lambda d: d["decision"].update(decided_by="GPT-5 assistant"),
        lambda d: d["candidates"][1]["claims"][4].update(stated_by="an AI"),
        lambda d: d["candidates"][1].update(messages=[{
            "to": "the committee", "file": "encd.md", "drafted_on": "2026-10-21",
            "sent_on": "2026-10-22", "sent_by": "Copilot"}]),
    ):  # fmt: skip
        document = record()
        change(document)
        assert _sources_said(project, document) == [("data-source-not-a-person", "warn")]
    document = record()
    document["decision"]["decided_by"] = "Ai Tanaka"  # a name, not a machine
    assert _sources_said(project, document) == []


def test_an_access_claim_with_nothing_behind_it_is_said(project: Path) -> None:
    from test_data_sources import record

    _named_everywhere(project)
    document = record()
    del document["candidates"][1]["claims"][2]  # the minimum cell count's
    document["candidates"][0]["access"]["steps"] = "download the zip files"
    said = _sources_said(project, document)
    assert said == [("data-source-unsourced", "warn")] * 2
    loaded, _ = load_project(project)
    from manuscript_guard.gates.data_sources import check_data_sources

    messages = sorted(f.message for f in check_data_sources(loaded, "drafting").findings)
    assert messages == ["Example National Claims Database: no claim backs minimum_cell_count",
                        "Open Reports Archive: no claim backs steps"]  # fmt: skip


def test_a_quote_not_on_its_stored_page_is_said(project: Path) -> None:
    from test_data_sources import record

    _named_everywhere(project)
    document = record()
    # "fewer than 11" read as "fewer than 10": the quote is not what the page says.
    claim = document["candidates"][1]["claims"][2]
    claim["quote"] = claim["quote"].replace("11", "10")
    assert _sources_said(project, document) == [("data-source-quote-not-on-page", "warn")]
    # A quote is folded for case, spacing, a line break and curly quotes, as G7 folds one.
    document = record()
    document["candidates"][0]["claims"][2]["quote"] = (
        "new extracts appear  within three months of each quarter’s end"
    )
    assert _sources_said(project, document) == []
    # A quote that is the end of a longer number on the page is not on it.
    document = record()
    document["candidates"][1]["claims"][1]["quote"] = "00 EUR is charged"
    assert _sources_said(project, document) == [("data-source-quote-not-on-page", "warn")]


