# ------------------------------------------- a figure the paper places the ordinary way

#: What G10 and G3 say of a figure, whose stages are compared.
_SAID_OF_A_FIGURE = ("figure-unreviewed", "figure-review-", "figure-alt-", "figure-colours-",
                     "figure-greyscale-")  # fmt: skip


def _drawn(path: Path, *marks: str) -> None:
    """A figure of lines in the colours `marks`, as `_painted` draws one, at `path`: an SVG
    or a PDF by its suffix."""
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.suffix == ".svg":
        body = "".join(f'<path d="M0 {10 * n}L90 {10 * n}" style="fill: none; stroke: {m}"/>'
                       for n, m in enumerate(marks))  # fmt: skip
        path.write_text('<svg xmlns="http://www.w3.org/2000/svg" width="100pt" height="80pt" '
                        f'viewBox="0 0 100 80"><rect width="100" height="80" fill="#ffffff"/>'
                        f"{body}</svg>", encoding="utf-8")  # fmt: skip
        return
    from generated import pdf_document

    def rgb(code: str) -> bytes:
        return b" ".join(b"%.4f" % (int(code[i : i + 2], 16) / 255) for i in (1, 3, 5))

    ops = [b"%s RG 0 %d m 90 %d l S" % (rgb(m), 10 * n, 10 * n) for n, m in enumerate(marks)]
    path.write_bytes(pdf_document(b"\n".join(ops)))


def _said_of(root: Path, stem: str, stage: str) -> list[tuple[str, str]]:
    """What `check` says at `stage`, its policy applied, of the figure whose files are named
    `stem`, by G10 and G3's alternative text and colours."""
    from manuscript_guard.cli import _run_gates

    report, *_ = _run_gates(root, stage=stage)
    return sorted((f.code, f.severity) for f in report.findings
                  if f.code.startswith(_SAID_OF_A_FIGURE) and f.path is not None
                  and Path(f.path).name.split(".")[0] == stem)  # fmt: skip


def _emitted_unread(root: Path, svg: bool) -> None:
    """The example's emitted figure in red and green, with no review and no alternative
    text: what an emitted figure is told, for a placed one to be told the same."""
    _painted(root, _RED, _GREEN, svg=svg)
    (root / "figures" / "forest.review.yaml").unlink()
    _alt(root, None)


def _latex_placing(root: Path) -> None:
    """The twin with a results figure placed as arXiv 2409.10841 places its four: in a float,
    `\\includegraphics` of a name with no extension, found through `\\graphicspath`."""
    entry = _twin(root)
    text = entry.read_text(encoding="utf-8")
    entry.write_text(
        text.replace("\\begin{document}", "\\graphicspath{{figs/}}\n\\begin{document}", 1)
        .replace("\\section{Discussion}", "\\begin{figure}\\centering\n"
                 "\\includegraphics[width=0.9\\linewidth]{chart}\n\\caption{Counts by year.}\n"
                 "\\end{figure}\n\n\\section{Discussion}", 1),
        encoding="utf-8",
    )  # fmt: skip
    _drawn(root / "manuscript" / "figs" / "chart.pdf", _RED, _GREEN)


def _markdown_placing(root: Path) -> None:
    """The example's main text with a figure typed as an image, its path from the project's
    root, as pandoc reads it."""
    path = main_md(root)
    text = path.read_text(encoding="utf-8")
    path.write_text(text.replace("{{figure.forest}}\n", "{{figure.forest}}\n\n"
                                 "![Counts by year.](manuscript/figs/chart.svg)\n", 1),
                    encoding="utf-8")  # fmt: skip
    _drawn(root / "manuscript" / "figs" / "chart.svg", _RED, _GREEN)


@pytest.mark.parametrize("stage", ["drafting", "internal-review", "submission"])
@pytest.mark.parametrize("latex", [True, False], ids=["latex", "markdown"])
def test_a_placed_figure_is_told_what_an_emitted_one_is_at_each_stage(
    project: Path, tmp_path: Path, latex: bool, stage: str
) -> None:
    """The real-paper corpus, arXiv 2409.10841: a LaTeX paper's four results figures placed
    with `\\includegraphics` were never reviewed, given alternative text or read for their
    colours, since G10 and G3 read only a figure the analysis emits and a binding places.
    Basile, 2026-11-11: every figure file the paper places is read, at the stages an emitted
    one is, with its severities."""
    emitted = tmp_path / "emitted"
    shutil.copytree(project, emitted)
    if latex:
        _twin(emitted)
    _emitted_unread(emitted, svg=not latex)
    expected = _said_of(emitted, "forest", stage)
    assert ("figure-unreviewed", "info" if stage == "drafting" else "fail") in expected
    assert any(code == "figure-alt-missing" for code, _ in expected)
    assert ("figure-colours-confused", "warn") in expected

    if latex:
        _twin(project)
    before = _said_of(project, "forest", stage)
    (_latex_placing if latex else _markdown_placing)(project)
    assert _said_of(project, "chart", stage) == expected
    # The emitted figure is told what it was told before.
    assert _said_of(project, "forest", stage) == before


def test_a_placed_figure_reviewed_and_described_is_told_nothing(project: Path) -> None:
    """Its review and its alternative text are recorded as an emitted figure's are, beside
    the file: `review --record-figure` with its path, and `alt:` in its guard file."""
    from manuscript_guard.record import write_figure_review

    _latex_placing(project)
    written = write_figure_review(load_project(project)[0], "manuscript/figs/chart.pdf",
                                  verdict="pass", reviewed_by="A. Reader")  # fmt: skip
    assert written.path == project / "manuscript" / "figs" / "chart.review.yaml"
    record = yaml.safe_load(written.path.read_text(encoding="utf-8"))
    for check in record["checks"]:
        check["ok"] = True
    written.path.write_text(yaml.safe_dump(record, sort_keys=False), encoding="utf-8")
    (project / "manuscript" / "figs" / "chart.guard.yaml").write_text(
        "alt: Two lines, one rising and one falling.\n"
        "allow_colours:\n  - value: '#d62728 #2ca02c'\n    why: each line is labelled\n",
        encoding="utf-8",
    )
    said = _said_of(project, "chart", "submission")
    assert [code for code, severity in said if severity != "info"] == [], said


def test_the_numbers_of_a_placed_figure_are_said_once_to_be_untraced(project: Path) -> None:
    """What a placed figure draws is not traced to the results, and `check` says so in one
    note naming each such figure, and no more."""
    from manuscript_guard.cli import _run_gates

    report, *_ = _run_gates(project, stage="submission")
    assert "figure-untraced" not in codes(report)
    _latex_placing(project)
    report, *_ = _run_gates(project, stage="submission")
    [found] = [f for f in report.findings if f.code == "figure-untraced"]
    assert found.severity == "info" and "manuscript/figs/chart.pdf" in found.message


def test_a_placed_raster_is_said_to_be_unread_for_its_colours(project: Path) -> None:
    """A raster's colours are blended at every edge and are not guessed at: a placed PNG, as
    `init --from` writes a Word paper's pictures into `manuscript/media/`, is a note, as an
    emitted figure with no SVG or PDF is, and is still asked for its review and its text."""
    path = main_md(project)
    text = path.read_text(encoding="utf-8")
    path.write_text(text.replace("{{figure.forest}}\n", "{{figure.forest}}\n\n"
                                 "![](manuscript/media/image1.png)\n", 1),
                    encoding="utf-8")  # fmt: skip
    media = project / "manuscript" / "media"
    media.mkdir()
    shutil.copyfile(project / "figures" / "forest.png", media / "image1.png")
    said = _said_of(project, "image1", "internal-review")
    assert said == [("figure-alt-missing", "warn"), ("figure-colours-unread", "info"),
                    ("figure-unreviewed", "fail")]  # fmt: skip


# ------------------------------------------------- the journal's citation style (item 51)


def _style_said(root: Path) -> list[tuple[str, str]]:
    return [(f.code, f.severity) for f in _journal(root).findings
            if f.code.startswith("journal-style")]  # fmt: skip


def test_a_journal_style_the_project_does_not_keep_is_said(project: Path) -> None:
    """The offline build formatted in pandoc's default style, whatever the profile named, and
    nothing said so."""
    from test_style import DEPENDENT, keep_style, name_style

    assert _style_said(project) == []
    name_style(project, DEPENDENT)
    assert _style_said(project) == [("journal-style-not-stored", "warn")]
    name_style(project, "https://example.org/styles/elsewhere")
    assert _style_said(project) == [("journal-style-not-stored", "warn")]
    keep_style(project, DEPENDENT)
    assert _style_said(project) == []
    # Round 1 of #322: a file's name is said to be one (round 1 of #349: untested).
    name_style(project, f"{DEPENDENT}.csl")
    [said] = [f for f in _journal(project).findings if f.code == "journal-style-not-stored"]
    assert "a name with `.csl` is a file's" in said.message


def test_a_kept_style_edited_since_is_said_and_not_used(project: Path) -> None:
    from test_style import DEPENDENT, PARENT, keep_style

    from manuscript_guard.journal_style import stored

    keep_style(project, DEPENDENT)
    parent = project / "profiles" / "journals" / "styles" / DEPENDENT / f"{PARENT}.csl"
    parent.write_bytes(parent.read_bytes() + b"<!-- edited -->")
    assert _style_said(project) == [("journal-style-changed", "warn")]
    assert stored(load_project(project)[0], DEPENDENT) is None
    parent.unlink()
    [said] = [f for f in _journal(project).findings if f.code == "journal-style-changed"]
    assert f"{PARENT}.csl (missing)" in said.message


@pytest.mark.parametrize(
    ("found", "numbered", "said"),
    [
        ("numeric", True, []),
        ("numeric", False, [("journal-style-format", "warn")]),
        ("author-date", True, [("journal-style-format", "warn")]),
        ("author-date", False, []),
        ("note", True, [("journal-style-format", "warn")]),
    ],
)
def test_a_style_that_numbers_otherwise_than_the_profile_is_said(
    project: Path, found: str, numbered: bool, said: list
) -> None:
    """The style's own citation format against the profile's `numbered:`: one of the two
    was read wrong from the journal's page."""
    from test_style import DEPENDENT, keep_style, name_style

    keep_style(project, DEPENDENT)
    record = project / "profiles" / "journals" / "styles" / f"{DEPENDENT}.yaml"
    document = yaml.safe_load(record.read_text(encoding="utf-8"))
    record.write_text(yaml.safe_dump({**document, "citation_format": found}, sort_keys=False),
                      encoding="utf-8")  # fmt: skip
    name_style(project, DEPENDENT, numbered=numbered)
    assert _style_said(project) == said


# ------------------------------------------------------------- what the build prints
# The build strips every file's front matter and writes the header from paper.yaml. Text
# the gates read there and the build drops is checked, then left out of the document.

SENTINEL = "Zebrafish marmalade sentinel phrase."


@pytest.mark.parametrize(
    "abstract",
    [
        f"abstract: |\n  {SENTINEL}\n",
        "abstract: >-\n  Zebrafish marmalade\n  sentinel phrase.\n",
        f"abstract: {SENTINEL}\n",
        f'"abstract": {SENTINEL}\n',
        # Merged in through a list that is met twice: under the first of two merge keys,
        # by a mapping that merges it, and as the second. See `_MET_TWICE` further down.
        f"l: &l [{{abstract: {SENTINEL}}}]\ny: &y {{abstract: ~}}\nm2: &m2 {{<<: *l}}\n"
        "a: &a {<<: [*m2, *y]}\n<<: *a\n<<: *l\n",
    ],
)
def test_an_abstract_in_the_front_matter_is_refused(project: Path, abstract: str, capsys) -> None:
    """G2 read an `abstract:` in the front matter, because pandoc prints one, and the build
    stripped the block and wrote a header from paper.yaml, which has no abstract. The
    abstract was checked and then left out of the document without a word, and the word
    count, which follows the build, gave a journal's abstract limit 0 words to pass on.
    `check` refuses it now, and the build refuses it even when told to skip the checks."""
    from manuscript_guard.cli import main

    source = main_md(project)
    text = source.read_text(encoding="utf-8")
    source.write_text(text.replace("---\n", "---\n" + abstract, 1), encoding="utf-8")

    assert main(["check", str(project), "--json"]) == 1
    findings = json.loads(capsys.readouterr().out)["findings"]
    failing = [(f["code"], f["line"]) for f in findings if f["severity"] == "fail"]
    assert failing == [("front-matter-abstract", 2)]

    assert main(["build", str(project), "--offline", "--skip-checks"]) == 1
    assert "under a `# Abstract` heading" in capsys.readouterr().out
    # Any name: a build that skipped failing checks writes `manuscript.UNCHECKED.*`.
    assert list((project / "build").glob("manuscript*")) == []


def test_a_supplements_front_matter_abstract_is_refused(project: Path) -> None:
    """The build strips a supplement's front matter as it strips the paper's."""
    from manuscript_guard.build.assemble import assemble

    supplement = project / "manuscript" / "supplementary" / "appendix.md"
    supplement.parent.mkdir(parents=True, exist_ok=True)
    supplement.write_text(f"---\nabstract: {SENTINEL}\n---\n\n# Appendix\n\nText.\n", "utf-8")

    def refused(report) -> list[tuple[str, str, int | None]]:
        found = [f for f in report.failures if f.code == "front-matter-abstract"]
        return [(f.gate, f.path.name, f.line) for f in found]

    assert refused(gate_report(project)) == [("G2", "appendix.md", 2)]
    projekt, _ = load_project(project)
    namespace, results, _literature, _report = load_namespace(projekt)
    assert refused(assemble(projekt, namespace, results)[1]) == [("BUILD", "appendix.md", 2)]


#: The rendered keys of a front matter other than the abstract and the title, each with a
#: word nothing else in the example holds and a number G2 has no source for.
_OTHER_RENDERED = {
    "subtitle": "Zebrafish 3.71",
    "summary": "Marmalade 4.72",
    "keywords": "Quokka 5.73",
    "short_title": "Tamarind 6.74",
    "running_title": "Pangolin 7.75",
}


@pytest.mark.skipif(shutil.which("pandoc") is None, reason="pandoc is not installed")
def test_the_other_rendered_keys_of_a_front_matter_are_checked_and_printed_by_nothing(
    project: Path, capsys
) -> None:
    """A known gap (DESIGN.md, Known gaps, "The other rendered keys in a manuscript's front
    matter are read by G2 and printed by nothing"): a number in each is said by G2, and
    nothing else is: the abstract alone is refused and the title alone compared. The build
    strips the block, and none of the text is in the document. The 2026-11-09 triage
    planned a fix (F08), which will change this test."""
    from manuscript_guard.cli import main
    from manuscript_guard.text.docx import read_docx

    source = main_md(project)
    text = source.read_text(encoding="utf-8")
    keys = "".join(f"{key}: {value}\n" for key, value in _OTHER_RENDERED.items())
    source.write_text(text.replace("---\n", "---\n" + keys, 1), encoding="utf-8")
    assert main(["check", str(project), "--json"]) == 1
    findings = json.loads(capsys.readouterr().out)["findings"]
    in_header = sorted(
        (f["code"], f["line"])
        for f in findings
        if f["path"] and Path(f["path"]).name == "main.md" and f["line"] in range(2, 7)
    )
    assert in_header == [("unclassified-number", line) for line in range(2, 7)], in_header
    said = {f["code"] for f in findings}
    assert not said & {"front-matter-abstract", "two-titles"}, said
    assert main(["build", str(project), "--offline", "--skip-checks"]) == 0
    printed = read_docx(project / "build" / "manuscript.UNCHECKED.docx")
    for value in _OTHER_RENDERED.values():
        assert value.split()[0] not in printed, value


#: A header whose root has two merge keys. Under the first, `a` merges `m2` and then `y`,
#: and `m2` merges the list `l`, which the second key names as well. Pandoc takes the
#: abstract of the list's member, since `m2` stands before `y`. A search that goes through
#: a merged list once, and marks it when the mapping that merges it is read, has marked `l`
#: at the root before `m2` is reached, passes over it there, and takes `y`'s: tried for
#: speed in #168, it left an abstract pandoc prints unrefused, and was taken back.
_MET_TWICE = (
    "l: &l [{{abstract: {first}}}]\ny: &y {{abstract: {second}}}\nm2: &m2 {{<<: *l}}\n"
    "a: &a {{<<: [*m2, *y]}}\n<<: *a\n<<: *l\n"
)


def _abstract_line(front: str) -> int | None:
    from manuscript_guard.text.masking import front_matter_abstract

    found = front_matter_abstract(f"---\n{front}---\n\nBody.\n")
    return None if found is None else found[0]


@pytest.mark.parametrize(
    ("front", "line"),
    [
        (f"abstract: {SENTINEL}\n", 2),
        (f"'abstract': {SENTINEL}\n", 2),
        (f'abstract: "\n  {SENTINEL}"\n', 2),
        (f"abstract: '\n  {SENTINEL}'\n", 2),
        (f"{{title: T, abstract: {SENTINEL}}}\n", 2),
        (f"title: T\nabstract:\n\n  {SENTINEL}\n", 3),
        ("abstract: 0\n", 2),
        # Blocks pandoc reads and PyYAML could not turn into Python values, or not scan.
        (f'date: 2024-02-30\n"abstract": {SENTINEL}\n', 3),
        (f"created: !r Sys.Date()\n'abstract': {SENTINEL}\n", 3),
        (f'subtitle:\tS\n"abstract": {SENTINEL}\n', 3),
        # Pandoc expands a tab to the next multiple of four columns, so this is one block.
        ('"abstract": |\n  Zebrafish marmalade\n\tsentinel phrase.\n', 2),
        (f'title:\tT\n"abstract":\t{SENTINEL}\n', 3),
        # Pandoc takes a merge key's mapping into the one holding it, and knows a merge key
        # by its text, `<<`, however it is quoted or tagged.
        (f"base: &b {{abstract: {SENTINEL}}}\n<<: *b\n", 2),
        (f'base: &b {{abstract: {SENTINEL}}}\n"<<": *b\n', 2),
        (f"base: &b {{abstract: {SENTINEL}}}\n'<<': *b\n", 2),
        (f"!!merge abstract: {SENTINEL}\n", 2),
        (_MET_TWICE.format(first=SENTINEL, second="~"), 2),
        # PyYAML counts U+2028 as a line break, and the file does not.
        (f'title: "Hepatic{chr(0x2028)}injury"\nabstract: {SENTINEL}\n', 3),
        # Pandoc prints the text whatever the tag says, and a quoted "null" is the word.
        (f"abstract: !!null {SENTINEL}\n", 2),
        ('abstract: "null"\n', 2),
    ],
)
def test_every_spelling_of_a_front_matter_abstract_is_found(front: str, line: int) -> None:
    """G2 finds a front-matter value by its key line, and YAML has spellings that line
    misses: a quoted key, a quoted value opened on the key's line and continued below it, a
    flow mapping, a merge key. Pandoc prints each as the abstract, so the refusal reads the
    block as YAML, the way pandoc reads it, and names the line of the key."""
    assert _abstract_line(front) == line


@pytest.mark.parametrize(
    "front",
    [
        'abstract: ""\n',
        "abstract:\n",
        "abstract: |\n",
        "abstract: >-\n",
        "abstract: |2\n",
        "abstract: null\n",
        "abstract: # written last\n",
        'abstract: "" # none\n',
        f"meta:\n  abstract: {SENTINEL}\n",
        # The first of two merge keys wins, quoted or not, and its abstract is empty.
        f'e: &e {{abstract: ""}}\nf: &f {{abstract: {SENTINEL}}}\n"<<": *e\n<<: *f\n',
        # The list's member is null and stands before the text, which is not the abstract.
        _MET_TWICE.format(first="~", second=SENTINEL),
    ],
)
def test_a_front_matter_abstract_pandoc_prints_nothing_for_is_not_refused(front: str) -> None:
    """Nothing is lost by stripping an abstract pandoc reads as empty, or a key named
    `abstract` inside another mapping, which pandoc does not take for the abstract."""
    assert _abstract_line(front) is None


def test_a_merge_key_bomb_in_the_front_matter_does_not_hold_up_check() -> None:
    """A mapping merging the one before it twice doubles, with each line, the work of
    anything that expands merge keys: 22 lines, 614 bytes, held `check` for 38 seconds when
    the block was built into Python values. The search for a merged abstract has the same
    shape, so it visits each mapping once; this one is found only after all of `a21`."""
    merges = [f"a{i}: &a{i} {{<<: [*a{i - 1}, *a{i - 1}]}}" for i in range(1, 22)]
    lines = ["a0: &a0 {k: v}", *merges, f"z: &z {{abstract: {SENTINEL}}}", "<<: [*a21, *z]"]
    started = time.perf_counter()
    line = _abstract_line("\n".join(lines) + "\n")
    assert time.perf_counter() - started < 5
    assert line == 24


# ------------------------------------------------------------------------------ audit
# `audit` is the weak check, set membership against the outputs, and says so. These are the
# ways it was weaker than it said: a wrong number that matched, and wrong numbers it never
# looked at while reporting the file as audited.

W = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'


def _p(text: str, style: str | None = None) -> str:
    props = f'<w:pPr><w:pStyle w:val="{style}"/></w:pPr>' if style else ""
    return f"<w:p>{props}<w:r><w:t>{text}</w:t></w:r></w:p>"


def _docx(path: Path, body: str, parts: dict[str, str] | None = None) -> Path:
    import zipfile

    with zipfile.ZipFile(path, "w") as archive:
        document = f"<w:document {W}><w:body>{body}</w:body></w:document>"
        archive.writestr("word/document.xml", document)
        for name, xml in (parts or {}).items():
            archive.writestr(name, xml)
    return path


def _outputs(tmp_path: Path, text: str) -> Path:
    path = tmp_path / "out.json"
    path.write_text(text, encoding="utf-8")
    return path


_COUNTED = (
    f"<w:numbering {W}><w:abstractNum w:abstractNumId='0'><w:lvl w:ilvl='0'><w:start "
    "w:val='1'/><w:numFmt w:val='decimal'/><w:lvlText w:val='[%1]'/></w:lvl></w:abstractNum>"
    "<w:num w:numId='1'><w:abstractNumId w:val='0'/></w:num></w:numbering>"
)


@pytest.mark.parametrize(
    ("entries", "numbered", "listed"),
    [(2, True, ["citation-beyond-list"]), (2, False, []), (0, False, [])],
    ids=["numbered by Word", "author-year", "an empty list"],
)
def test_an_audited_docx_list_is_numbered_by_place_only_where_word_numbers_it(
    tmp_path: Path, entries: int, numbered: bool, listed: list[str]
) -> None:
    """Round 1 of #463: one bracketed number in the text, `range [0, 3]`, made an author-year
    list numbered by place, every entry "cited nowhere"; and under a final heading with no
    entry, `max()` of nothing raised. Now only a list Word numbers 1, 2, 3 is held to the
    text's numbers: there [3] is beyond its two entries."""
    from manuscript_guard.audit import audit

    number = "<w:numPr><w:ilvl w:val='0'/><w:numId w:val='1'/></w:numPr>" if numbered else ""
    listed_entries = "".join(
        f"<w:p><w:pPr>{number}</w:pPr><w:r><w:t>Author {n}. J Ex. 2019;1:1-2.</w:t></w:r></w:p>"
        for n in range(entries)
    )
    body = (_p("Scores range [0, 3] [1, 2] (Author 2019).") + _p("References", "Heading1")
            + listed_entries)  # fmt: skip
    paper = _docx(tmp_path / "paper.docx", body,
                  {"word/numbering.xml": _COUNTED} if numbered else None)  # fmt: skip
    [census] = audit([paper], None).references
    assert [p.code for p in census.problems] == listed


#: A numbered list of three entries, as typed: the second holds a number in parentheses and
#: the third a superscript, which, being the list's, cite nothing.
_UNCITED_ENTRIES = (
    "1. Smith J. A trial of care. J Ex. 2019;12(3):1-2.",
    "2. Jones K. A cohort of women. J Ex. 2020;2(4):3-4.",
    "3. Brown L. Rates per m\N{SUPERSCRIPT TWO} of land. J Ex. 2021;3:5-6.",
)
#: The sentence a shape is put into, at its `{}`, which holds no number at all.
_UNCITED_SENTENCE = "The trials were run in the clinic{} and the results were clear."
#: Each shape a citation by number can take outside brackets, as typed text holds it.
_TYPED_SHAPES = {
    "a Unicode superscript": "\N{SUPERSCRIPT THREE}",
    "a pandoc superscript": "^3^",
    "an HTML superscript": "<sup>3</sup>",
    "one number in parentheses": " (3)",
    "a list in parentheses": " (3, 5)",
    "a range in parentheses": " (3-5)",
    "a range with a dash in parentheses": " (3\N{EN DASH}5)",
    "a list and a range in parentheses": " (2,4-6)",
    "digits after a stop": ".12",
    "a range after a comma": ",3-5",
    "digits after two stops": ");4",
    "an author of the list cited in parentheses": " (Smith et al., 2019)",
    "two authors of the list cited in parentheses": " (Smith and Lee 2019; Adams, 2020a)",
    "an author of the list cited in a sentence": " that Jones (2020) ran",
    "two authors of the list cited in a sentence": " that Lee and Brown (2021, p. 4) ran",
    "an author of the list cited in square brackets": " [Smith et al., 2019]",
    "two authors cited in square brackets": " [Smith, 2019; Lee, 2020]",
    "an author with particles": " (see van der Jones, 2019, p. 4)",
    "a reference's number in parentheses": " (ref. 3)",
    "references' numbers in parentheses": " (refs 1-3)",
    "a list of references in parentheses": " (refs. 1, 2)",
    "two numbers with and in parentheses": " (1 and 2)",
    "a list with and in parentheses": " (1, 2 and 5)",
    "a link whose text is a number": " [1](#B1)",
    "links whose text is a number in brackets": " [[1](#B1)] and [[2](#B2), [3](#B3)]",
    "a link to an address whose text is a range": " [1-3](https://example.org/a)",
    "a link to a figure whose text is a number": " [2](#fig2)",
    "an author with a page after a colon": " (Smith 2019: 45)",
    "an author with a page after the year": " (Smith, 2019 p. 4)",
    "an author with pages after the year": " (Smith et al., 2019 pp. 4-5)",
    "a comma before et al.": " (Smith, et al., 2019)",
    "a possessive in a sentence": " as Smith et al.'s (2019) work",
    "a possessive with a curly apostrophe":
        " as Smith et al.\N{RIGHT SINGLE QUOTATION MARK}s (2019) work",
    "an author's possessive": " as Jones's (2020) work",
    "authors' links": " ([Smith et al., 2019](#B12); [Lee, 2020](#B2))",
}
#: Digits typed straight onto a word, which a citation may be, and names with digits.
_RUN_ON = {"digits after a letter": "s12", "a name with a hyphen and digits": " during COVID-19",
           "a name with digits": " with VGG16", "a size": " with 3x3 filters"}  # fmt: skip


def _uncited_docx(path: Path, runs: str, parts: dict[str, str] | None = None,
                  numbered: bool = False, listed: str = "") -> Path:  # fmt: skip
    """A .docx whose one paragraph of text is `runs`, then a heading and the three
    entries, typed, or numbered by Word, with the runs `listed` at the end of the first."""
    from xml.sax.saxutils import escape

    number = "<w:pPr><w:numPr><w:ilvl w:val='0'/><w:numId w:val='1'/></w:numPr></w:pPr>"
    entries = "".join(
        f"<w:p>{number if numbered else ''}<w:r><w:t>"
        f"{escape(entry.split(' ', 1)[1] if numbered else entry)}</w:t></w:r>"
        f"{'' if at else listed}</w:p>"
        for at, entry in enumerate(_UNCITED_ENTRIES)
    )
    styles = (f'<w:styles {W}><w:style w:type="paragraph" w:styleId="Heading1"><w:name '
              'w:val="heading 1"/></w:style><w:style w:type="character" w:styleId="Raised">'
              '<w:name w:val="Endnote Reference"/><w:rPr><w:vertAlign w:val="superscript"/>'
              "</w:rPr></w:style></w:styles>")  # fmt: skip
    extra = {"word/numbering.xml": _COUNTED} if numbered else {}
    return _docx(path, f"<w:p>{runs}</w:p>" + _p("References", "Heading1") + entries,
                 {"word/styles.xml": styles, **extra, **(parts or {})})


def _plain_runs(text: str) -> str:
    from xml.sax.saxutils import escape

    return f'<w:r><w:t xml:space="preserve">{escape(text)}</w:t></w:r>'


def _never_cited(paper: Path) -> list[str]:
    from manuscript_guard.audit import audit

    [census] = audit([paper], None).references
    assert all(p.code == "entry-never-cited" for p in census.problems), census.problems
    return [p.subject for p in census.problems]


_EVERY_ENTRY = ["entry 1", "entry 2", "entry 3"]


@pytest.mark.parametrize("form", ["md", "docx"])
def test_a_numbered_list_in_a_text_that_cites_nothing_by_number_is_every_entry_uncited(
    tmp_path: Path, form: str
) -> None:
    """A numbered list's entries are each cited nowhere where the text cites nothing by
    number: no marker in brackets, no superscript, no "(n)", no digits after a word's stop,
    no citation field, and no author of the list cited with a year. G7 reported nothing,
    and after #782 one paper's entry never cited
    was lost: it had been reported only because the list's own entries, read as text past
    one styled as a heading, counted as citations (Basile, 2026-11-25, "Strict rule"). The
    list's own "(3)" and "m\N{SUPERSCRIPT TWO}" are not the text's."""
    sentence = _UNCITED_SENTENCE.format("")
    if form == "md":
        paper = tmp_path / "paper.md"
        paper.write_text(f"# Results\n\n{sentence}\n\n# References\n\n"
                         + "\n".join(_UNCITED_ENTRIES) + "\n", encoding="utf-8")  # fmt: skip
    else:
        paper = _uncited_docx(tmp_path / "paper.docx", _plain_runs(sentence))
    assert _never_cited(paper) == _EVERY_ENTRY
    from manuscript_guard.audit import audit

    [census] = audit([paper], None).references
    assert "cites nothing by number" in census.problems[0].message


@pytest.mark.parametrize("numbered", [False, True], ids=["typed", "numbered by Word"])
def test_a_digit_raised_in_the_list_is_the_list_s_and_cites_nothing(
    tmp_path: Path, numbered: bool
) -> None:
    """A digit raised as superscript in the list is the list's, as its text is, and the
    entries are each never cited, in a list typed and in one Word numbers 1, 2, 3 itself."""
    raised = '<w:r><w:rPr><w:vertAlign w:val="superscript"/></w:rPr><w:t>2</w:t></w:r>'
    from manuscript_guard.text.docx import read_docx_text

    paper = _uncited_docx(tmp_path / "paper.docx", _plain_runs(_UNCITED_SENTENCE.format("")),
                          numbered=numbered, listed=raised)  # fmt: skip
    document = read_docx_text(paper)
    first = _UNCITED_ENTRIES[0].split(" ", 1)[1] if numbered else _UNCITED_ENTRIES[0]
    assert [document.body.split("\n")[line] for line in document.raised] == [first + "2"]
    assert _never_cited(paper) == _EVERY_ENTRY


def _typed_paper(folder: Path, form: str, said: str) -> Path:
    """A paper in Markdown or in Word whose one paragraph of text is the sentence with `said`
    in it, then its numbered list of `_UNCITED_ENTRIES`."""
    sentence = _UNCITED_SENTENCE.format(said)
    if form == "docx":
        return _uncited_docx(folder / "paper.docx", _plain_runs(sentence))
    paper = folder / "paper.md"
    paper.write_text(f"# Results\n\n{sentence}\n\n# References\n\n"
                     + "\n".join(_UNCITED_ENTRIES) + "\n", encoding="utf-8")  # fmt: skip
    return paper


@pytest.mark.parametrize("form", ["md", "docx"])
@pytest.mark.parametrize("shape", sorted(_TYPED_SHAPES))
def test_any_number_a_citation_may_be_keeps_a_list_with_no_marker_unreported(
    tmp_path: Path, form: str, shape: str
) -> None:
    """Strict: where a text may cite by number other than in brackets, or cites an author of
    the list with a year, its list's entries are not reported as never cited (Basile,
    2026-11-25, "Strict rule", "Drop run-on digits")."""
    assert _never_cited(_typed_paper(tmp_path, form, _TYPED_SHAPES[shape])) == []


@pytest.mark.parametrize("form", ["md", "docx"])
@pytest.mark.parametrize("shape", sorted(_RUN_ON))
def test_digits_typed_onto_a_word_are_no_citation_and_the_list_is_reported(
    tmp_path: Path, form: str, shape: str
) -> None:
    """Digits run straight on into letters are read as no citation, a name's as a superscript
    typed flat, "disease12": with nothing else, every entry is reported (Basile, 2026-11-25,
    "Drop run-on digits"; DESIGN.md, "Known gaps")."""
    assert _never_cited(_typed_paper(tmp_path, form, _RUN_ON[shape])) == _EVERY_ENTRY


_ZOTERO_CODE = ('ADDIN ZOTERO_ITEM CSL_CITATION {"citationID":"a","citationItems":[{"id":1,'
                '"uris":["http://zotero.org/users/1/items/ABCD1234"],"itemData":{"id":1,'
                '"type":"article-journal","title":"A trial"}}],"schema":"x"}')
#: Each kind of a citation field, by the runs that hold it, its shown text "Smith".
_FIELDS = {
    "Zotero": _ZOTERO_CODE,
    "EndNote": "ADDIN EN.CITE <EndNote><Cite><Author>Smith</Author></Cite></EndNote>",
    "Word": "CITATION Smi19 \\l 1033",
    "Citavi": "ADDIN CITAVI.PLACEHOLDER 0a1b2c",
}


def _field_runs(code: str, split: bool = True) -> str:
    """A complex field whose code is `code`, split over two `instrText` runs, showing
    "Smith"."""
    from xml.sax.saxutils import escape

    half = len(code) // 2 if split else len(code)
    return ("<w:r><w:fldChar w:fldCharType='begin'/></w:r>"
            f"<w:r><w:instrText xml:space='preserve'>{escape(code[:half])}</w:instrText></w:r>"
            f"<w:r><w:instrText xml:space='preserve'>{escape(code[half:])}</w:instrText></w:r>"
            "<w:r><w:fldChar w:fldCharType='separate'/></w:r><w:r><w:t>Smith</w:t></w:r>"
            "<w:r><w:fldChar w:fldCharType='end'/></w:r>")  # fmt: skip


@pytest.mark.parametrize("kind", sorted(_FIELDS))
def test_a_citation_field_keeps_a_word_list_with_no_marker_unreported(
    tmp_path: Path, kind: str
) -> None:
    """A Word paper that cites through a citation field, whatever its words, may cite every
    entry: its list is not reported (Basile, 2026-11-25), read from the field's code."""
    start, end = _UNCITED_SENTENCE.split("{}")
    runs = _plain_runs(start + " ") + _field_runs(_FIELDS[kind]) + _plain_runs(end)
    assert _never_cited(_uncited_docx(tmp_path / "paper.docx", runs)) == []


@pytest.mark.parametrize("held", ["a simple field", "a content control's tag", "a note"])
def test_a_citation_field_held_otherwise_keeps_a_word_list_unreported(
    tmp_path: Path, held: str
) -> None:
    """A citation field as a simple field, a citation Mendeley writes as a content control,
    and one in a footnote, each keep the list unreported too."""
    from xml.sax.saxutils import escape

    start, end = _UNCITED_SENTENCE.split("{}")
    parts = None
    if held == "a simple field":
        cite = (f"<w:fldSimple w:instr='{escape(_FIELDS['Word'])}'><w:r><w:t>Smith</w:t>"
                "</w:r></w:fldSimple>")  # fmt: skip
    elif held == "a content control's tag":
        cite = ("<w:sdt><w:sdtPr><w:tag w:val='MENDELEY_CITATION_v3_eyJ9'/></w:sdtPr>"
                "<w:sdtContent><w:r><w:t>Smith</w:t></w:r></w:sdtContent></w:sdt>")  # fmt: skip
    else:
        # The notes are read whole, so a field in one is read with no reference to it; a
        # reference's mark keeps the list unreported itself.
        cite = ""
        parts = {"word/footnotes.xml": f"<w:footnotes {W}><w:footnote w:id='1'><w:p>"
                 f"{_field_runs(_ZOTERO_CODE)}</w:p></w:footnote></w:footnotes>"}  # fmt: skip
    runs = _plain_runs(start + " ") + cite + _plain_runs(end)
    assert _never_cited(_uncited_docx(tmp_path / "paper.docx", runs, parts)) == []


@pytest.mark.parametrize("raised", ["by its own properties", "by its character style"])
def test_a_digit_raised_as_superscript_keeps_a_word_list_unreported(
    tmp_path: Path, raised: str
) -> None:
    """A digit Word raises as superscript after a space, which read as text is a number
    alone, "clinic 3", is known from the run (`text.docx.DocxText.raised`)."""
    properties = ('<w:vertAlign w:val="superscript"/>' if raised == "by its own properties"
                  else '<w:rStyle w:val="Raised"/>')  # fmt: skip
    start, end = _UNCITED_SENTENCE.split("{}")
    runs = (_plain_runs(start + " ") + f"<w:r><w:rPr>{properties}</w:rPr><w:t>3</w:t></w:r>"
            + _plain_runs(end))  # fmt: skip
    from manuscript_guard.text.docx import read_docx_text

    paper = _uncited_docx(tmp_path / "paper.docx", runs)
    document = read_docx_text(paper)
    assert [document.body.split("\n")[line] for line in document.raised] == [
        _UNCITED_SENTENCE.format(" 3")]
    assert _never_cited(paper) == []


