def test_the_data_made_again_make_the_date_stale(project: Path) -> None:
    """New data at the path: G1 names the date it makes stale, and the analysis run again
    with the old date is refused."""
    data = project / "data" / "reports.csv"
    data.write_text(data.read_text(encoding="utf-8") + "R99999,2024,example-drug,rash,N,F,75+\n",
                    encoding="utf-8", newline="")  # fmt: skip
    found = [f for f in gate_report(project).failures if f.code == "input-changed"]
    assert any("dataset.reports.extracted dates the data as they were" in f.message
               for f in found)  # fmt: skip
    import subprocess
    import sys

    out = subprocess.run([sys.executable, str(_analysis(project))], capture_output=True,
                         text=True, cwd=project)  # fmt: skip
    assert out.returncode != 0
    assert "is not the data pinned as extracted on 2026-08-03" in out.stderr


def test_a_dataset_pinned_to_other_data_fails(project: Path) -> None:
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["datasets"]["reports"]["fingerprint"] = "0123456789abcdef"
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    assert "dataset-pin-mismatch" in codes(gate_report(project))


def test_a_report_dated_outside_the_years_covered_is_refused(project: Path) -> None:
    _replace_once(_analysis(project), 'covers=("2015", "2024")', 'covers=("2016", "2024")')
    import subprocess
    import sys

    out = subprocess.run([sys.executable, str(_analysis(project))], capture_output=True,
                         text=True, cwd=project)  # fmt: skip
    assert out.returncode != 0
    assert "dates lie outside the period the data are declared to cover (2016 to 2024)" in (
        out.stderr
    )


#: The example's supplement, which every gate that reads prose reads as it reads the main text.
_SUPPLEMENT = "manuscript/supplementary/S1_code_lists.md"


@pytest.mark.parametrize("where", ["manuscript/main.md", _SUPPLEMENT])
def test_a_date_of_the_data_in_the_supplement_is_held_as_in_the_methods(
    project: Path, where: str
) -> None:
    """The supplement is held to the rules of the main text (Basile, 2026-10-21): an
    extraction date typed in Supplementary Methods fails as one typed in the Methods does,
    and one typed into the script is warned of there too, at the file it stands in."""
    fragment = next((project / "results").glob("*.json"))
    document = json.loads(fragment.read_text(encoding="utf-8"))
    document["values"]["data.extracted"] = {"value": "2026-08-03", "display": "3 August 2026"}
    fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
    write_digest(fragment)
    page = project / where
    page.write_text(page.read_text(encoding="utf-8") + "\n\nThe data were extracted on 3 August "
                    "2026. They were downloaded on {{results.data.extracted}}.\n",
                    encoding="utf-8")  # fmt: skip
    report = gate_report(project)
    typed = {f.message.split(" is ")[0] for f in report.failures
             if f.code == "unclassified-number" and f.path.name == page.name}  # fmt: skip
    assert typed == {"'3'", "'2026'"}, report.render(project)
    warned = [f for f in report.findings if f.code == "data-date-not-declared"]
    assert [f.path.name for f in warned] == [page.name]


def test_a_dataset_date_bound_in_the_supplement_alone_is_quoted(project: Path) -> None:
    """The date bound only in Supplementary Methods is quoted, as one bound in the Methods
    is: direction two reads the supplement too."""
    _replace_once(main_md(project), "generated on\n{{results.dataset.reports.extracted}} to cover",
                  "made to cover")  # fmt: skip
    page = project / _SUPPLEMENT
    page.write_text(page.read_text(encoding="utf-8") + "\n\nThe database was generated on "
                    "{{results.dataset.reports.extracted}}.\n", encoding="utf-8")  # fmt: skip
    report = gate_report(project)
    assert report.ok, report.render(project)
    assert "unquoted-result" not in {f.code for f in report.findings}


def test_a_parameter_declared_and_never_read_fails(project: Path) -> None:
    """The example's signal criterion before this check: stated, declared, bound, and
    applied nowhere. Binding the threshold printed the right number for a step that was not
    there."""
    _replace_once(_analysis(project), "a >= min_cases and low > 1", "a >= 3 and low > 1")
    _rerun_disproportionality(project)
    found = [f for f in gate_report(project).failures if f.code == "parameter-unread"]
    assert [f.message.split()[0] for f in found] == ["param.signal.min_cases"]


def test_a_changed_parameter_reaches_the_methods_and_a_typed_copy_is_named(
    project: Path,
) -> None:
    """Bound, the Methods print the value the code now runs with. Typed, the copy no longer
    equals the parameter, so it is named as a threshold no parameter has."""
    _replace_once(_analysis(project), '"signal.min_cases", 3)', '"signal.min_cases", 5)')
    _rerun_disproportionality(project)
    namespace, *_ = load_namespace(load_project(project)[0])
    assert namespace["results.param.signal.min_cases"].display == "5"
    assert gate_report(project).ok

    _replace_once(main_md(project), "{{results.param.signal.min_cases}}", "3")
    report = gate_report(project)
    assert "typed-parameter" not in codes(report)
    assert [f.code for f in report.warnings if f.code == "threshold-undeclared"] == [
        "threshold-undeclared"
    ]


def test_a_parameter_equal_to_a_name_is_not_a_typed_threshold(project: Path) -> None:
    """`2 x 2` names a structure, whatever a parameter equals: only the conventions that
    hold in the Methods alone are thresholds an analysis chooses."""
    _replace_once(
        _analysis(project),
        '    min_cases = em.parameter("signal.min_cases", 3)\n',
        '    min_cases = em.parameter("signal.min_cases", 3)\n'
        '    rows_per_table = em.parameter("rows_per_table", 2)\n'
        "    assert rows_per_table == 2\n",
    )
    _rerun_disproportionality(project)
    assert "typed-parameter" not in codes(gate_report(project))


_CRITERION = "interval of the reporting odds ratio above 1."
_OMEGA = "\N{GREEK CAPITAL LETTER OMEGA}"
_AT_LEAST = "\N{GREATER-THAN OR EQUAL TO}"


def _declare_a_parameter_of(root: Path, value: int) -> None:
    _replace_once(
        _analysis(root),
        '    min_cases = em.parameter("signal.min_cases", 3)\n',
        '    min_cases = em.parameter("signal.min_cases", 3)\n'
        f'    other = em.parameter("other", {value})\n'
        f"    assert other == {value}\n",
    )
    _rerun_disproportionality(root)


@pytest.mark.parametrize(
    ("typed", "name", "digits", "threshold"),
    [
        ("I2 > 50%", "I2", 2, "50%"),
        (f"X2 {_AT_LEAST} 4", "X2", 2, "4"),
        (f"{_OMEGA}025 > 0", f"{_OMEGA}025", 25, "0"),
    ],
)
def test_the_name_of_a_statistic_is_no_threshold_whatever_its_digits_equal(
    project: Path, typed: str, name: str, digits: int, threshold: str
) -> None:
    """The convention that accepts a published criterion covers the statistic's name with
    its threshold. The name was read from its first digit: with a parameter of 2 declared,
    `I2` failed as a typed copy of it, and with none it was a threshold no parameter has.
    Only the threshold beside the name is one."""
    _declare_a_parameter_of(project, digits)
    _replace_once(main_md(project), _CRITERION, f"{_CRITERION} Another rule asked for {typed}.")
    report = gate_report(project)
    said = [
        (f.code, f.message.split()[0])
        for f in report.findings
        if f.code in ("typed-parameter", "threshold-undeclared")
    ]
    assert said == [("threshold-undeclared", repr(threshold))], report.render(project)
    assert not any(repr(name) in f.message for f in report.findings), report.render(project)


def test_a_threshold_typed_against_the_name_of_its_statistic_is_still_read(
    project: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    """`I2>50%` is one atom. Its name states nothing and its 50 is the threshold, as the
    0.05 of `P<0.05` is: a declared parameter of 50 makes it a typed copy, in `check` and
    in `explain`, and the name alone is passed by both."""
    from manuscript_guard.cli import main

    _declare_a_parameter_of(project, 50)
    _replace_once(
        main_md(project),
        _CRITERION,
        f"{_CRITERION} One rule asked for I2>50% and another for I2 > 75%.",
    )
    report = gate_report(project)
    said = [
        (f.code, f.message.split()[0])
        for f in report.findings
        if f.code in ("typed-parameter", "threshold-undeclared")
    ]
    assert said == [("typed-parameter", "'I2>50%'"), ("threshold-undeclared", "'75%'")]
    typed = next(f for f in report.failures if f.code == "typed-parameter")
    assert "{{results.param.other}}" in typed.hint

    main(["explain", str(main_md(project))])
    rows = {line.split()[2]: line for line in capsys.readouterr().out.splitlines()}
    assert rows["I2>50%"].startswith("FAIL") and "typed: write" in rows["I2>50%"]
    assert rows["I2"].startswith("ok") and "typed" not in rows["I2"], rows["I2"]


@pytest.mark.parametrize(
    ("atom", "figure", "states"),
    [
        # A figure typed against a letter is part of a name.
        ("I2", None, None),
        ("X2", None, None),
        ("R2", None, None),
        ("IC025", None, None),
        ("EB05", None, None),
        ("\N{GREEK SMALL LETTER CHI}2", None, None),
        (f"{_OMEGA}025", None, None),
        ("omega025", None, None),
        # A figure after anything else is the atom's own.
        ("0.05", "0.05", 0.05),
        (".05", ".05", 0.05),
        ("P<0.05", "0.05", 0.05),
        ("p<.05", ".05", 0.05),
        ("n=3", "3", 3),
        (f"{_AT_LEAST}3", "3", 3),
        ("=3", "3", 3),
        ("50%", "50%", 50),
        ("alpha=0.05", "0.05", 0.05),
        ("\N{GREEK SMALL LETTER ALPHA}=0.05", "0.05", 0.05),
        ("SMD<0.1", "0.1", 0.1),
        ("PRR>2", "2", 2),
        ("1,000", "1,000", 1000),
        # After a name in the same atom, too.
        ("I2>50%", "50%", 50),
        ("IC025>0", "0", 0),
        (f"\N{GREEK SMALL LETTER CHI}2{_AT_LEAST}4", "4", 4),
        # A figure of its own that is not one number: a threshold still, and equal to none.
        ("1:1", "1:1", None),
        # The limit DESIGN.md writes down: a threshold typed against the word before it.
        ("power80%", None, None),
        ("caliper0.2", None, None),
    ],
)
def test_a_figure_typed_against_a_letter_is_part_of_a_name(
    atom: str, figure: str | None, states: float | None
) -> None:
    from manuscript_guard.gates.numbers import own_figure, stated_number

    assert own_figure(atom) == figure
    assert stated_number(atom) == states


_COPIES = ("typed-parameter", "threshold-undeclared", "typed-software-version")


@pytest.mark.parametrize(
    ("declared", "sentence", "said"),
    [
        (95, "The 95% CI was used, and one rule asked for I2 > 95%.", []),
        # The other side: a level that is no confidence level is read for its parameter.
        (75, "One rule asked for I2 > 75%.", [("typed-parameter", "'75%'")]),
        (None, "Another rule asked for at least three cases.", []),
        (None, "Another rule asked for at least 3 cases.", [("typed-parameter", "'3'")]),
        (None, "Another rule asked for caliper0.2 and power80%.", []),
        (None, "Another rule asked for a caliper of 0.2 and a power of 80%.",
         [("threshold-undeclared", "'0.2'"), ("threshold-undeclared", "'80%'")]),
        # The declared version's first two parts, "3.13" of "3.13.16".
        (None, "It ran in Python {short}.", []),
        (None, "It ran in Python {python}.", [("typed-software-version", "'{python}'")]),
    ],
    ids=["a confidence level", "a threshold equal to a parameter", "a word",
         "the word's figure", "against the word before it", "spaced from the word",
         "a version's first parts", "the version whole"],
)
def test_only_an_equal_typed_copy_of_a_figure_is_read_for_a_parameter(
    project: Path, declared: int | None, sentence: str, said: list[tuple[str, str]]
) -> None:
    """A known gap (DESIGN.md, Known gaps, "Only an equal typed copy fails"): "95% CI" is
    never read for a parameter, a version is matched by its whole text, a copy typed as a
    word holds no figure, and a threshold typed against the word before it is a name: none
    of these is seen by either rule."""
    if declared is not None:
        _declare_a_parameter_of(project, declared)
    python = load_namespace(load_project(project)[0])[0]["results.software.python"].display
    short = python.rsplit(".", 1)[0]
    _replace_once(main_md(project), _CRITERION,
                  f"{_CRITERION} {sentence.format(python=python, short=short)}")  # fmt: skip
    found = [(f.code, f.message.split()[0]) for f in gate_report(project).findings
             if f.code in _COPIES]  # fmt: skip
    assert found == [(code, typed.format(python=python)) for code, typed in said]


@pytest.mark.parametrize("parameters", [True, False], ids=["declared", "none declared"])
def test_a_typed_threshold_unlike_every_parameter_is_warned_only_where_some_are_declared(
    project: Path, parameters: bool
) -> None:
    """A known gap (DESIGN.md, Known gaps, "Only an equal typed copy fails"): a threshold
    typed in the Methods that equals no parameter is `threshold-undeclared`, a warning, and
    only in an analysis that declares parameters."""
    if not parameters:
        fragment = next((project / "results").glob("*.json"))
        document = json.loads(fragment.read_text(encoding="utf-8"))
        for key in [key for key in document["values"] if key.startswith("param.")]:
            del document["values"][key]
        fragment.write_text(json.dumps(document, indent=2), encoding="utf-8")
        write_digest(fragment)
        text = main_md(project).read_text(encoding="utf-8")
        main_md(project).write_text(text.replace("{{results.param.alpha}}", "0.05").replace(
            "{{results.param.signal.min_cases}}", "3"), encoding="utf-8")  # fmt: skip
    _replace_once(main_md(project), _CRITERION, f"{_CRITERION} Another rule asked for p < 0.01.")
    report = gate_report(project)
    found = [(f.code, f.severity, f.message.split()[0]) for f in report.findings
             if f.code in _COPIES]  # fmt: skip
    assert found == ([("threshold-undeclared", "warn", "'0.01'")] if parameters else [])


def test_explain_says_a_declared_threshold_is_typed(
    project: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    """`explain` is what an author reads when a finding surprises them, so it fails what
    `check` fails, and names the binding to write."""
    from manuscript_guard.cli import main

    _replace_once(main_md(project), "{{results.param.alpha}}", "0.05")
    main(["explain", str(main_md(project))])
    row = next(line for line in capsys.readouterr().out.splitlines() if " 0.05 " in line)
    assert row.startswith("FAIL") and "typed: write {{results.param.alpha}}" in row, row


